    private StudioRuntime(
        RuntimePaths runtimePaths,
        ScumInstallation scum,
        string unrealPakPath,
        List<PresetDefinition> presets)
    {
        _runtimePaths = runtimePaths;
        _scum = scum;
        _unrealPakPath = unrealPakPath;
        _presets = presets;
        _builder = new ModBuilder(runtimePaths, scum, unrealPakPath, DefaultAesKeyHex);
        _presetFiles = _builder.GetStudioFileEntries(presets).ToList();
        _presetFileById = _presetFiles.ToDictionary(GetAssetId, x => x, StringComparer.OrdinalIgnoreCase);
        _iconService = new ItemIconService(runtimePaths, scum, unrealPakPath, DefaultAesKeyHex);
        _knowledgeBase = new ScumKnowledgeBaseService();
        (_features, _featureAssetIds) = BuildFeatureCatalog(_presetFiles);
    }

    public static StudioRuntime Create()
    {
        var appRoot = AppContext.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        var workspaceRoot = ResolveWorkspaceRoot(appRoot);
        var runtimePaths = new RuntimePaths(
            appRoot,
            workspaceRoot,
            Path.Combine(Path.GetTempPath(), "ScumPakWizard"),
            Path.Combine(workspaceRoot, "builds", "ScumPakWizard"));

        Directory.CreateDirectory(runtimePaths.TempRoot);
        Directory.CreateDirectory(runtimePaths.BuildsRoot);

        var scum = ScumLocator.Locate() ?? CreateMissingScumInstallation();
        var unrealPakPath = UnrealPakLocator.Locate(appRoot) ?? string.Empty;

        var presets = PresetCatalog.Load(appRoot);
        if (presets.Count == 0)
        {
            throw new InvalidOperationException("Встроенные пресеты не найдены (папка presets пуста).");
        }

        return new StudioRuntime(runtimePaths, scum, unrealPakPath, presets);
    }

    private static ScumInstallation CreateMissingScumInstallation()
    {
        return new ScumInstallation(
            "SCUM не найдена",
            string.Empty,
            string.Empty,
            null,
            null,
            IsAvailable: false);
    }

    private static string ResolveWorkspaceRoot(string appRoot)
    {
        var probes = new List<string?>
        {
            Directory.GetCurrentDirectory(),
            appRoot,
            Directory.GetParent(appRoot)?.FullName,
            Directory.GetParent(Directory.GetParent(appRoot)?.FullName ?? string.Empty)?.FullName
        };

        foreach (var probe in probes.Where(path => !string.IsNullOrWhiteSpace(path)))
        {
            var candidate = FindWorkspaceRootUpward(probe!);
            if (!string.IsNullOrWhiteSpace(candidate))
            {
                return candidate;
            }
        }

        return Directory.GetCurrentDirectory();
    }

    private static string? FindWorkspaceRootUpward(string startPath)
    {
        var current = new DirectoryInfo(startPath);
        while (current is not null)
        {
            var hasMainProject = Directory.Exists(Path.Combine(current.FullName, "ScumPakWizard"));
            var hasResearchRoots = Directory.Exists(Path.Combine(current.FullName, "analysis"))
                || Directory.Exists(Path.Combine(current.FullName, "mods"));

            if (hasMainProject && hasResearchRoots)
            {
                return current.FullName;
            }

            current = current.Parent;
        }

        return null;
    }

    public StudioStatusDto GetStatus()
    {
        var warnings = new List<string>();
        if (!HasUsableScumInstallation())
        {
            warnings.Add("SCUM не найдена автоматически. Установи игру через Steam или укажи путь в переменной окружения SCUM_PATH.");
        }

        if (!HasUsableUnrealPak())
        {
            warnings.Add("UnrealPak.exe не найден. Сборка .pak будет недоступна, пока он не появится в Engine\\Binaries\\Win64 внутри папки программы.");
        }

        var toolchain = BuildToolchainStatus();
        if (!toolchain.ReadyForRawModelCook)
        {
            warnings.Add("Полный импорт raw-моделей в игру требует UE4.27 cook toolchain. Программа уже принимает и анализирует модели, но cooked .uasset создаётся только через легальный UE4.27 pipeline.");
        }

        return new StudioStatusDto(
            _scum.RootPath,
            _scum.PaksPath,
            _scum.BuildId,
            _unrealPakPath,
            _presets.Select(x => new StudioPresetDto(x.Id, x.DisplayName, x.Description, x.EditableSurfaces)).ToList(),
            _features,
            _presetFiles.Count,
            HasUsableScumInstallation(),
            HasUsableUnrealPak(),
            toolchain,
            warnings);
    }

    private StudioToolchainStatusDto BuildToolchainStatus()
    {
        var toolsRoot = GetToolsRoot();
        var steps = new List<StudioToolchainStepDto>
        {
            new(
                "raw-model-analysis",
                "Анализ raw-моделей",
                "Встроено",
                true,
                null,
                "Программа сама читает габариты OBJ/GLTF/GLB/DAE/STL/PLY/ASCII FBX и готовит fit-профиль."),
            new(
                "cooked-asset-import",
                "Импорт cooked ассетов",
                "Встроено",
                true,
                GetWritableCustomVisualAssetRoot(),
                "Cooked .uasset/.uexp/.ubulk можно загрузить прямо в программу и выбрать в мастере замены модели.")
        };

        var unrealPakReady = HasUsableUnrealPak();
        steps.Add(new StudioToolchainStepDto(
            "pak-build",
            "Сборка PAK",
            unrealPakReady ? "Готово" : "Не найден UnrealPak",
            unrealPakReady,
            unrealPakReady ? _unrealPakPath : null,
            "Финальный мод собирается в PAK через UnrealPak.",
            "Как включить сборку PAK",
            [
                "Обычно UnrealPak уже лежит в поставке программы или в совместимом UE4.27 toolchain.",
                $"Если у тебя есть UE4.27, положи его папку в {Path.Combine(toolsRoot, "UE_4.27")} или задай переменную SCUM_MOD_STUDIO_UE427.",
                "После этого перезапусти программу или нажми проверку статуса."
            ],
            "Открыть папку tools",
            null));

        var ueEditorCmd = FindUnrealEditorCmdPath();
        steps.Add(new StudioToolchainStepDto(
            "ue4-cook",
            "Raw → cooked UE4.27",
            string.IsNullOrWhiteSpace(ueEditorCmd) ? "Требуется UE4.27 cook toolchain" : "Готово",
            !string.IsNullOrWhiteSpace(ueEditorCmd),
            ueEditorCmd,
            "Для полной автоматической подготовки FBX/OBJ/GLTF в игровые .uasset нужен UE4Editor-Cmd 4.27 или совместимый SCUM devkit/toolchain.",
            "Как подключить UE4.27 cook toolchain",
            [
                "Вариант 1: установить Unreal Engine 4.27 через Epic Games Launcher, затем программа найдёт стандартный путь C:\\Program Files\\Epic Games\\UE_4.27.",
                $"Вариант 2: положить легальную копию UE_4.27 в {Path.Combine(toolsRoot, "UE_4.27")}.",
                "Вариант 3: задать переменную окружения SCUM_MOD_STUDIO_UE427 на корень UE4.27.",
                "Из-за лицензии Epic программа не будет тайно распространять Unreal Editor; она может только использовать уже подключённый легальный toolchain."
            ],
            "Открыть страницу Unreal Engine",
            "https://www.unrealengine.com/download"));

        var blenderPath = FindBlenderExecutablePath();
        steps.Add(new StudioToolchainStepDto(
            "blend-conversion",
            ".blend → FBX",
            string.IsNullOrWhiteSpace(blenderPath) ? "Опционально" : "Готово",
            !string.IsNullOrWhiteSpace(blenderPath),
            blenderPath,
            "Blender запускается программой в фоне для .blend/.obj/.glb/.gltf/.dae/.stl/.ply и для нормализации модели перед UE4 cook.",
            "Как включить импорт моделей через Blender",
            [
                "Установи Blender обычным способом или положи portable Blender в папку tools\\blender рядом с программой.",
                "После установки программа найдёт blender.exe сама; клиенту не нужно открывать Blender или нажимать кнопки внутри него.",
                "Для уже готового FBX Blender не обязателен, UE4.27 будет запущен напрямую."
            ],
            "Открыть Blender",
            "https://www.blender.org/download/"));

        var readyForCookedMods = HasUsableScumInstallation() && unrealPakReady;
        var readyForRawModelCook = readyForCookedMods && !string.IsNullOrWhiteSpace(ueEditorCmd);
        var summary = readyForRawModelCook
            ? "Полный pipeline готов: raw модель можно подготовить, cook-нуть и добавить в PAK."
            : readyForCookedMods
                ? "Cooked-моды готовы. Для полной автоматической подготовки raw-моделей нужен подключённый UE4.27 cook toolchain."
                : "Нужно найти SCUM и UnrealPak, чтобы собирать моды.";

        return new StudioToolchainStatusDto(
            readyForCookedMods,
            readyForRawModelCook,
            summary,
            steps);
    }

    public void OpenToolsFolder()
    {
        var toolsRoot = GetToolsRoot();
        Directory.CreateDirectory(toolsRoot);
        try
        {
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
            {
                FileName = toolsRoot,
                UseShellExecute = true
            });
        }
        catch
        {
            // The folder still exists; UI will keep showing the path if Explorer cannot open.
        }
    }

    private string GetToolsRoot()
    {
        return Path.Combine(_runtimePaths.AppRoot, "tools");
    }

    private string GetCookScratchRoot()
    {
        var overrideRoot = Environment.GetEnvironmentVariable("SCUM_MOD_STUDIO_COOK_TEMP");
        if (!string.IsNullOrWhiteSpace(overrideRoot))
        {
            var configured = Path.GetFullPath(overrideRoot);
            Directory.CreateDirectory(configured);
            return configured;
        }

        var appScratch = Path.Combine(_runtimePaths.AppRoot, ".smscook");
        var tempScratch = Path.Combine(Path.GetTempPath(), "smscook");
        var candidates = new[] { appScratch, tempScratch };
        foreach (var candidate in candidates
                     .Select(Path.GetFullPath)
                     .OrderByDescending(GetAvailableFreeBytesForPath))
        {
            try
            {
                Directory.CreateDirectory(candidate);
                return candidate;
            }
            catch
            {
                // Try the next candidate; the final failure will surface below.
            }
        }

        Directory.CreateDirectory(tempScratch);
        return tempScratch;
    }

    private static long GetAvailableFreeBytesForPath(string path)
    {
        try
        {
            var root = Path.GetPathRoot(path);
            if (string.IsNullOrWhiteSpace(root))
            {
                return -1;
            }

            return new DriveInfo(root).AvailableFreeSpace;
        }
        catch
        {
            return -1;
        }
    }

    private string? FindUnrealEditorCmdPath()
    {
        var candidates = new List<string>();
        void AddCandidate(string? root)
        {
            if (string.IsNullOrWhiteSpace(root))
            {
                return;
            }

            candidates.Add(Path.Combine(root, "Engine", "Binaries", "Win64", "UE4Editor-Cmd.exe"));
            candidates.Add(Path.Combine(root, "UE4Editor-Cmd.exe"));
        }

        AddCandidate(Environment.GetEnvironmentVariable("SCUM_MOD_STUDIO_UE427"));
        AddCandidate(Environment.GetEnvironmentVariable("UE4_27_ROOT"));
        AddCandidate(Environment.GetEnvironmentVariable("UNREAL_ENGINE_4_27_PATH"));
        AddCandidate(Path.Combine(_runtimePaths.AppRoot, "tools", "UE_4.27"));
        AddCandidate(Path.Combine(_runtimePaths.WorkspaceRoot, "tools", "UE_4.27"));
        AddCandidate(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "Epic Games", "UE_4.27"));
        AddCandidate(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86), "Epic Games", "UE_4.27"));

        return candidates
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(Path.GetFullPath)
            .FirstOrDefault(File.Exists);
    }

    private string? FindOptionalToolExecutable(string folderName, string exeName)
    {
        var candidates = new[]
        {
            Path.Combine(_runtimePaths.AppRoot, "tools", folderName, exeName),
            Path.Combine(_runtimePaths.WorkspaceRoot, "tools", folderName, exeName),
            Path.Combine(_runtimePaths.AppRoot, "tools", exeName),
            Path.Combine(_runtimePaths.WorkspaceRoot, "tools", exeName)
        };

        return candidates
            .Select(Path.GetFullPath)
            .FirstOrDefault(File.Exists);
    }

    private string? FindBlenderExecutablePath()
    {
        var candidates = new List<string?>();
        void AddCandidate(string? path)
        {
            if (!string.IsNullOrWhiteSpace(path))
            {
                candidates.Add(path);
            }
        }

        AddCandidate(Environment.GetEnvironmentVariable("SCUM_MOD_STUDIO_BLENDER"));
        AddCandidate(Environment.GetEnvironmentVariable("BLENDER_EXE"));
        AddCandidate(FindOptionalToolExecutable("blender", "blender.exe"));
        foreach (var portableBlender in EnumerateToolExecutables("blender", "blender.exe"))
        {
            AddCandidate(portableBlender);
        }

        var programFiles = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);
        var programFilesX86 = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86);
        AddBlenderProgramFilesCandidates(programFiles, candidates);
        AddBlenderProgramFilesCandidates(programFilesX86, candidates);
        AddCandidate(FindExecutableOnPath("blender.exe"));

        return candidates
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => Path.GetFullPath(path!))
            .FirstOrDefault(File.Exists);
    }

    private IEnumerable<string> EnumerateToolExecutables(string folderName, string exeName)
    {
        foreach (var toolsRoot in new[]
                 {
                     Path.Combine(_runtimePaths.AppRoot, "tools", folderName),
                     Path.Combine(_runtimePaths.WorkspaceRoot, "tools", folderName)
                 })
        {
            if (!Directory.Exists(toolsRoot))
            {
                continue;
            }

            foreach (var exe in Directory.EnumerateFiles(toolsRoot, exeName, SearchOption.AllDirectories))
            {
                yield return exe;
            }
        }
    }

    private static void AddBlenderProgramFilesCandidates(string root, List<string?> candidates)
    {
        if (string.IsNullOrWhiteSpace(root))
        {
            return;
        }

        var blenderRoot = Path.Combine(root, "Blender Foundation");
        if (!Directory.Exists(blenderRoot))
        {
            return;
        }

        foreach (var exe in Directory.EnumerateFiles(blenderRoot, "blender.exe", SearchOption.AllDirectories))
        {
            candidates.Add(exe);
        }
    }

    private static string? FindExecutableOnPath(string exeName)
    {
        var pathValue = Environment.GetEnvironmentVariable("PATH");
        if (string.IsNullOrWhiteSpace(pathValue))
        {
            return null;
        }

        foreach (var segment in pathValue.Split(Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            try
            {
                var candidate = Path.Combine(segment, exeName);
                if (File.Exists(candidate))
                {
                    return candidate;
                }
            }
            catch
            {
                // PATH can contain malformed entries; ignore and keep scanning.
            }
        }

        return null;
    }

    private static string? FindExternalRawArchiveExtractor()
    {
        var candidates = new[]
        {
            FindExecutableOnPath("tar.exe"),
            FindExecutableOnPath("bsdtar.exe"),
            FindExecutableOnPath("7z.exe"),
            Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "7-Zip", "7z.exe"),
            Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86), "7-Zip", "7z.exe")
        };

        return candidates
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => Path.GetFullPath(path!))
            .FirstOrDefault(File.Exists);
    }

    private static void TryDeleteFile(string path)
    {
        try
        {
            if (File.Exists(path))
            {
                File.Delete(path);
            }
        }
        catch
        {
            // best-effort cleanup
        }
    }

    private static void TryDeleteDirectory(string path)
    {
        try
        {
            if (Directory.Exists(path))
            {
                Directory.Delete(path, recursive: true);
            }
        }
        catch
        {
            // best-effort cleanup
        }
    }

    private bool HasUsableScumInstallation()
    {
        return _scum.IsAvailable && Directory.Exists(_scum.PaksPath);
    }

    private bool HasUsableUnrealPak()
    {
        return !string.IsNullOrWhiteSpace(_unrealPakPath) && File.Exists(_unrealPakPath);
    }

    public StudioResearchModPatternDto InspectResearchModPattern(string assetPath, bool includeImportDiff, int maxItems)
    {
        maxItems = Math.Clamp(maxItems, 4, 40);

        var warnings = new List<string>();
        var normalized = NormalizeResearchRelativePath(assetPath);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return new StudioResearchModPatternDto(
                assetPath,
                string.Empty,
                string.Empty,
                false,
                [],
                [],
                [],
                ["Не удалось привести путь ассета к игровому relative path."]);
        }

        var gamePackagePath = BuildResearchGamePackagePath(normalized);
        var isBlueprintLike = IsBlueprintLikePath(normalized);
        var originalFiles = FindOriginalResearchFiles(normalized, warnings);
        var variants = BuildResearchVariants(normalized, isBlueprintLike, originalFiles, includeImportDiff, maxItems, warnings);
        var globalTags = variants
            .SelectMany(x => x.Tags)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();

        if (variants.Count == 0)
        {
            warnings.Add("Локальные mod-варианты по этому runtime path не найдены в известных research-корнях.");
        }

        return new StudioResearchModPatternDto(
            assetPath,
            normalized,
            gamePackagePath,
            isBlueprintLike,
            originalFiles,
            variants,
            globalTags,
            warnings.Distinct(StringComparer.OrdinalIgnoreCase).ToList());
    }

    public StudioAssetQueryResultDto GetAssets(string? search, string? presetId, string? scope, int page, int pageSize)
    {
        page = Math.Max(1, page);
        pageSize = Math.Clamp(pageSize, 40, 500);

        IEnumerable<StudioAssetDto> query = GetAssetRowsByScope(scope);

        if (!string.IsNullOrWhiteSpace(presetId))
        {
            query = query.Where(x => x.PresetId.Equals(presetId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(x =>
                x.RelativePath.Contains(term, StringComparison.OrdinalIgnoreCase)
                || x.PresetName.Contains(term, StringComparison.OrdinalIgnoreCase)
                || x.Surface.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        var materialized = query.ToList();
        var total = materialized.Count;
        var pageCount = Math.Max(1, (int)Math.Ceiling(total / (double)pageSize));
        var actualPage = Math.Min(page, pageCount);
        var skip = (actualPage - 1) * pageSize;
        var items = materialized
            .Skip(skip)
            .Take(pageSize)
            .ToList();

        return new StudioAssetQueryResultDto(total, actualPage, pageSize, items);
    }

    private IEnumerable<StudioAssetDto> GetAssetRowsByScope(string? scope)
    {
        var normalized = (scope ?? "all").Trim().ToLowerInvariant();

        lock (_sync)
        {
            _presetAssetsCache ??= BuildPresetAssetRows();
        }

        if (normalized == "preset")
        {
            return _presetAssetsCache!;
        }

        lock (_sync)
        {
            _gameAssetsCache ??= BuildGameAssetRows();
        }

        if (normalized == "game")
        {
            return _gameAssetsCache!;
        }

        return _presetAssetsCache!.Concat(_gameAssetsCache!);
    }

    private List<StudioAssetDto> BuildPresetAssetRows()
    {
        return _presetFiles
            .OrderBy(x => x.TargetRelativePath, StringComparer.OrdinalIgnoreCase)
            .Select(x => new StudioAssetDto(
                GetAssetId(x),
                x.PresetId,
                x.PresetName,
                x.TargetRelativePath,
                x.SurfaceLabel,
                false,
                false))
            .ToList();
    }

    private List<StudioAssetDto> BuildGameAssetRows()
    {
        var pakIndex = GetOrLoadPakIndex();
        var presetPathSet = _presetFiles
            .Select(x => PathUtil.NormalizeRelative(x.TargetRelativePath))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var result = new List<StudioAssetDto>(12000);
        foreach (var path in pakIndex.GetAllRelativePaths())
        {
            if (!IsModdableGameAsset(path))
            {
                continue;
            }

            var normalized = PathUtil.NormalizeRelative(path);
            var hasPresetAlternative = presetPathSet.Contains(normalized);
            result.Add(new StudioAssetDto(
                $"game::{normalized.ToLowerInvariant()}",
                "game",
                "Файлы Игры",
                normalized,
                ResolveSurfaceLabel(normalized),
                true,
                hasPresetAlternative));
        }

        result.Sort((a, b) => string.Compare(a.RelativePath, b.RelativePath, StringComparison.OrdinalIgnoreCase));
        return result;
    }

    public List<StudioModCategoryDto> GetModdingCategories()
    {
        lock (_sync)
        {
            _modAssetsCache ??= BuildModAssets();
            _modCategoriesCache ??= BuildModCategories(_modAssetsCache);
            _visibleModAssetsCache ??= BuildVisibleModAssets(_modAssetsCache);
            _visibleModCategoriesCache ??= BuildModCategories(_visibleModAssetsCache);
            return _visibleModCategoriesCache.ToList();
        }
    }

    public StudioModAssetQueryResultDto GetModdingAssets(string? categoryId, string? search, int page, int pageSize)
    {
        page = Math.Max(1, page);
        pageSize = Math.Clamp(pageSize, 40, 300);

        List<StudioModAssetDto> allAssets;
        lock (_sync)
        {
            _modAssetsCache ??= BuildModAssets();
            _modCategoriesCache ??= BuildModCategories(_modAssetsCache);
            _visibleModAssetsCache ??= BuildVisibleModAssets(_modAssetsCache);
            _visibleModCategoriesCache ??= BuildModCategories(_visibleModAssetsCache);
            allAssets = _visibleModAssetsCache;
        }

        IEnumerable<StudioModAssetDto> query = allAssets;
        if (!string.IsNullOrWhiteSpace(categoryId))
        {
            query = query.Where(x => x.CategoryId.Equals(categoryId, StringComparison.OrdinalIgnoreCase));
        }

        List<StudioModAssetDto> materialized;
        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            var looseTerm = NormalizeLooseSearch(term);
            materialized = query
                .Select(x => new { Asset = x, Score = ComputeModAssetSearchScore(x, term, looseTerm) })
                .Where(x => x.Score > 0)
                .OrderByDescending(x => x.Score)
                .ThenBy(x => x.Asset.DisplayName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Asset.RelativePath, StringComparer.OrdinalIgnoreCase)
                .Select(x => x.Asset)
                .ToList();
        }
        else
        {
            materialized = query.ToList();
        }

        var total = materialized.Count;
        var pageCount = Math.Max(1, (int)Math.Ceiling(total / (double)pageSize));
        var actualPage = Math.Min(page, pageCount);
        var skip = (actualPage - 1) * pageSize;
        var items = materialized
            .Skip(skip)
            .Take(pageSize)
            .ToList();

        return new StudioModAssetQueryResultDto(total, actualPage, pageSize, items);
    }

    public List<StudioReferenceOptionDto> GetModdingReferenceOptions(string pickerKind, string? term, int limit)
    {
        limit = Math.Clamp(limit, 1, 80);
        var normalizedPicker = (pickerKind ?? string.Empty).Trim().ToLowerInvariant();

        if (normalizedPicker is "crafting-ingredient-asset" or "crafting-ingredient")
        {
            return GetCraftingIngredientReferenceOptions(term, limit);
        }

        if (normalizedPicker is "item-asset" or "item-reference")
        {
            return GetItemAssetReferenceOptions(term, limit);
        }

        if (normalizedPicker is "ammo-item-asset" or "ammo-item-reference" or "ammunition-item-asset")
        {
            return GetAmmoItemReferenceOptions(term, limit);
        }

        if (normalizedPicker is "weapon-bullet-class-asset" or "weapon-bullet-class-reference" or "ammo-projectile-class")
        {
            return GetWeaponBulletClassReferenceOptions(term, limit);
        }

        if (!string.IsNullOrWhiteSpace(term) && TryBuildFastVisualReferenceOptions(normalizedPicker, term, limit, out var fastVisualOptions))
        {
            return fastVisualOptions;
        }

        List<StudioReferenceOptionDto> allOptions;
        lock (_sync)
        {
            allOptions = normalizedPicker switch
            {
                "foreign-substance-all" or "foreign-substance-source" =>
                    _foreignSubstanceReferenceOptionsCache ??= BuildForeignSubstanceReferenceOptions(),
                "foreign-substance" or "foreign-substance-attribute" =>
                    _foreignSubstanceAttributeReferenceOptionsCache ??= BuildForeignSubstanceAttributeReferenceOptions(),
                "bodyeffect-symptom" or "bodyeffect-symptom-class" =>
                    _bodyEffectSymptomReferenceOptionsCache ??= BuildBodyEffectSymptomReferenceOptions(),
                "bodyeffect-side-effect" =>
                    _bodyEffectSideEffectReferenceOptionsCache ??= BuildBodyEffectSideEffectReferenceOptions(),
                "encounter-character-preset" or "encounter-preset" =>
                    _encounterCharacterPresetReferenceOptionsCache ??= BuildEncounterCharacterPresetReferenceOptions(),
                "encounter-class" =>
                    _encounterClassReferenceOptionsCache ??= BuildEncounterClassReferenceOptions(),
                "encounter-spawn-amount-curve" or "spawn-amount-curve" =>
                    _encounterSpawnAmountCurveReferenceOptionsCache ??= BuildEncounterSpawnAmountCurveReferenceOptions(),
                "economy-curve" or "economy-curve-float" =>
                    _economyCurveReferenceOptionsCache ??= BuildEconomyCurveReferenceOptions(),
                "cargo-drop-encounter-class" =>
                    _cargoDropEncounterClassReferenceOptionsCache ??= BuildCargoDropEncounterClassReferenceOptions(),
                "cargo-drop-container-class" =>
                    _cargoDropContainerClassReferenceOptionsCache ??= BuildCargoDropContainerClassReferenceOptions(),
                "guarded-zone-dropship-class" or "dropship-class" =>
                    _guardedZoneDropshipClassReferenceOptionsCache ??= BuildGuardedZoneDropshipClassReferenceOptions(),
                "encounter-npc-class" =>
                    _encounterNpcClassReferenceOptionsCache ??= BuildEncounterNpcClassReferenceOptions(),
                "crafting-item-recipe-asset" or "crafting-item-recipe" =>
                    _craftingItemRecipeReferenceOptionsCache ??= BuildCraftingRecipeReferenceOptions(
                        recipeClassName: "ItemCraftingRecipe",
                        labelPrefix: "Рецепт предмета"),
                "crafting-placeable-recipe-asset" or "crafting-placeable-recipe" =>
                    _craftingPlaceableRecipeReferenceOptionsCache ??= BuildCraftingRecipeReferenceOptions(
                        recipeClassName: "PlaceableCraftingRecipe",
                        labelPrefix: "Рецепт строительства"),
                "crafting-recipe-asset" or "crafting-recipe" =>
                    (_craftingItemRecipeReferenceOptionsCache ??= BuildCraftingRecipeReferenceOptions(
                        recipeClassName: "ItemCraftingRecipe",
                        labelPrefix: "Рецепт предмета"))
                    .Concat(_craftingPlaceableRecipeReferenceOptionsCache ??= BuildCraftingRecipeReferenceOptions(
                        recipeClassName: "PlaceableCraftingRecipe",
                        labelPrefix: "Рецепт строительства"))
                    .ToList(),
                "skill-asset" or "skill-reference" =>
                    _skillReferenceOptionsCache ??= BuildSkillReferenceOptions(),
                "skill-blueprint-asset" or "skill-blueprint-reference" =>
                    _skillBlueprintReferenceOptionsCache ??= BuildSkillBlueprintReferenceOptions(),
                "quest-giver" or "quest-giver-class" =>
                    _questGiverReferenceOptionsCache ??= BuildQuestGiverReferenceOptions(),
                "quest-asset" or "quest-reference" =>
                    _questAssetReferenceOptionsCache ??= BuildQuestAssetReferenceOptions(),
                "gameevent-primary-loadout" =>
                    _gameEventPrimaryLoadoutReferenceOptionsCache ??= BuildGameEventLoadoutReferenceOptions(
                        "/ui/gameevents/itemselection/rifles/",
                        "основное оружие"),
                "gameevent-secondary-loadout" =>
                    _gameEventSecondaryLoadoutReferenceOptionsCache ??= BuildGameEventLoadoutReferenceOptions(
                        "/ui/gameevents/itemselection/pistols/",
                        "пистолет"),
                "gameevent-tertiary-loadout" =>
                    _gameEventTertiaryLoadoutReferenceOptionsCache ??= BuildGameEventLoadoutReferenceOptions(
                        "/ui/gameevents/itemselection/melee/",
                        "ближний бой"),
                "gameevent-outfit-loadout" =>
                    _gameEventOutfitLoadoutReferenceOptionsCache ??= BuildGameEventLoadoutReferenceOptions(
                        "/ui/gameevents/itemselection/outfits/",
                        "одежда"),
                "gameevent-mandatory-loadout" =>
                    _gameEventMandatoryLoadoutReferenceOptionsCache ??= BuildGameEventLoadoutReferenceOptions(
                        "/ui/gameevents/itemselection/mandatory/",
                        "обязательное снаряжение"),
                "gameevent-support-loadout" =>
                    _gameEventSupportLoadoutReferenceOptionsCache ??= BuildGameEventLoadoutReferenceOptions(
                        "/ui/gameevents/itemselection/support/",
                        "дополнительное снаряжение"),
                "gameevent-team-equipment-set" =>
                    _gameEventTeamEquipmentSetReferenceOptionsCache ??= BuildGameEventTeamEquipmentSetReferenceOptions(),
                "gameevent-dropzone-crate-class" =>
                    _gameEventDropzoneCrateClassReferenceOptionsCache ??= BuildGameEventDropzoneClassReferenceOptions(
                        "bp_dropzonecrate",
                        "Ящик Drop Zone"),
                "gameevent-dropzone-cargo-class" =>
                    _gameEventDropzoneCargoClassReferenceOptionsCache ??= BuildGameEventDropzoneClassReferenceOptions(
                        "bp_dropzonecargo",
                        "Груз Drop Zone"),
                "gameevent-class" =>
                    _gameEventClassReferenceOptionsCache ??= BuildGameEventClassReferenceOptions(),
                "gameevent-border-class" =>
                    _gameEventBorderClassReferenceOptionsCache ??= BuildGameEventBorderClassReferenceOptions(),
                "worldevent-class" =>
                    _worldEventClassReferenceOptionsCache ??= BuildWorldEventClassReferenceOptions(),
                "fish-species-asset" or "fish-species" =>
                    _fishSpeciesReferenceOptionsCache ??= BuildFishSpeciesReferenceOptions(),
                "plant-species-asset" or "plant-species" =>
                    _plantSpeciesReferenceOptionsCache ??= BuildPlantSpeciesReferenceOptions(),
                "plant-pest-asset" or "plant-pest" =>
                    _plantPestReferenceOptionsCache ??= BuildPlantPestReferenceOptions(),
                "plant-disease-asset" or "plant-disease" =>
                    _plantDiseaseReferenceOptionsCache ??= BuildPlantDiseaseReferenceOptions(),
                "item-spawner-preset" or "regular-item-spawner-preset" =>
                    _regularItemSpawnerPresetReferenceOptionsCache ??= BuildRegularItemSpawnerPresetReferenceOptions(),
                "advanced-item-spawner-preset" or "container-loot-preset" or "examine-data-preset" =>
                    _advancedItemSpawnerPresetReferenceOptionsCache ??= BuildAdvancedItemSpawnerPresetReferenceOptions(),
                "advanced-item-spawner-subpreset" or "container-subpreset-preset" =>
                    _advancedItemSpawnerSubpresetReferenceOptionsCache ??= BuildAdvancedItemSpawnerSubpresetReferenceOptions(),
                "vehicle-spawn-preset" or "vehicle-preset" =>
                    _vehicleSpawnPresetReferenceOptionsCache ??= BuildVehicleSpawnPresetReferenceOptions(),
                "vehicle-class" =>
                    _vehicleClassReferenceOptionsCache ??= BuildVehicleClassReferenceOptions(),
                "vehicle-attachment-class" =>
                    _vehicleAttachmentClassReferenceOptionsCache ??= BuildVehicleAttachmentClassReferenceOptions(),
                "food-resource-class" or "food-resource" =>
                    _foodResourceReferenceOptionsCache ??= BuildFoodResourceReferenceOptions(),
                "visual-static-mesh-object" =>
                    _visualStaticMeshObjectReferenceOptionsCache ??= BuildVisualStaticMeshObjectReferenceOptions(),
                "visual-static-mesh-asset" =>
                    _visualStaticMeshSoftReferenceOptionsCache ??= BuildVisualStaticMeshSoftReferenceOptions(),
                "visual-skeletal-mesh-object" =>
                    _visualSkeletalMeshObjectReferenceOptionsCache ??= BuildVisualSkeletalMeshObjectReferenceOptions(),
                "visual-skeletal-mesh-asset" =>
                    _visualSkeletalMeshSoftReferenceOptionsCache ??= BuildVisualSkeletalMeshSoftReferenceOptions(),
                "visual-material-object" =>
                    _visualMaterialObjectReferenceOptionsCache ??= BuildVisualMaterialObjectReferenceOptions(),
                "visual-material-asset" =>
                    _visualMaterialSoftReferenceOptionsCache ??= BuildVisualMaterialSoftReferenceOptions(),
                "visual-texture-object" or "visual-icon-object" =>
                    _visualTextureObjectReferenceOptionsCache ??= BuildVisualTextureObjectReferenceOptions(),
                "visual-texture-asset" or "visual-icon-asset" =>
                    _visualTextureSoftReferenceOptionsCache ??= BuildVisualTextureSoftReferenceOptions(),
                "item-hands-corrections" or "hands-corrections-data" =>
                    _itemHandsCorrectionsReferenceOptionsCache ??= BuildItemHandsCorrectionsReferenceOptions(),
                "item-first-person-animations" or "first-person-animations-data" =>
                    _itemFirstPersonAnimationsReferenceOptionsCache ??= BuildItemFirstPersonAnimationsReferenceOptions(),
                "item-attachment-socket-mount-type" or "attachment-socket-mount-type" =>
                    _itemAttachmentSocketMountTypeReferenceOptionsCache ??= BuildItemAttachmentSocketMountTypeReferenceOptions(),
                "generic-gameplay-asset" or "generic-gameplay-reference" or "gameplay-asset" or "gameplay-reference" =>
                    _genericGameplayReferenceOptionsCache ??= BuildGenericGameplayReferenceOptions(),
                _ => []
            };
        }

        if (allOptions.Count == 0)
        {
            return [];
        }

        IEnumerable<StudioReferenceOptionDto> query = allOptions;

        if (!string.IsNullOrWhiteSpace(term))
        {
            var trimmed = term.Trim();
            var searchTerms = ExpandReferenceSearchTerms(pickerKind, trimmed).ToList();
            var normalizedTerms = searchTerms
                .Select(NormalizeLooseSearch)
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.Ordinal)
                .ToList();
            query = query.Where(option => MatchesReferenceSearch(option, searchTerms, normalizedTerms));
        }

        if (!string.IsNullOrWhiteSpace(term) && IsGenericGameplayPickerKind(normalizedPicker))
        {
            var trimmed = term.Trim();
            var looseTerm = NormalizeLooseSearch(trimmed);
            return query
                .Select(option => new
                {
                    Option = option,
                    Score = ComputeGenericGameplayReferenceSearchScore(option, trimmed, looseTerm)
                })
                .Where(x => x.Score > 0)
                .OrderByDescending(x => x.Score)
                .ThenBy(x => x.Option.Label, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Option.Value, StringComparer.OrdinalIgnoreCase)
                .Select(x => x.Option)
                .Take(limit)
                .ToList();
        }

        return query
            .OrderBy(option => option.Label, StringComparer.OrdinalIgnoreCase)
            .ThenBy(option => option.Value, StringComparer.OrdinalIgnoreCase)
            .Take(limit)
            .ToList();
    }

    private bool TryBuildFastCustomVisualReferenceOptions(
        string normalizedPicker,
        string term,
        int limit,
        out List<StudioReferenceOptionDto> options)
    {
        options = [];
        var kind = ResolveCustomVisualKindFromPicker(normalizedPicker);
        if (string.IsNullOrWhiteSpace(kind))
        {
            return false;
        }

        var objectReference = normalizedPicker.EndsWith("-object", StringComparison.OrdinalIgnoreCase)
                              || normalizedPicker.Equals("visual-icon-object", StringComparison.OrdinalIgnoreCase);
        var allOptions = GetCustomVisualAssetCatalog()
            .Where(asset => asset.Kind.Equals(kind, StringComparison.OrdinalIgnoreCase))
            .Select(asset => new StudioReferenceOptionDto(
                objectReference ? asset.ObjectReference : asset.AssetReference,
                PrefixReferenceOptionLabel("Пользовательский ассет", asset.DisplayName)))
            .Where(option => !string.IsNullOrWhiteSpace(option.Value))
            .ToList();
        if (allOptions.Count == 0)
        {
            return false;
        }

        var trimmed = term.Trim();
        var searchTerms = ExpandReferenceSearchTerms(normalizedPicker, trimmed).ToList();
        var normalizedTerms = searchTerms
            .Select(NormalizeLooseSearch)
            .Where(x => !string.IsNullOrWhiteSpace(x))
            .Distinct(StringComparer.Ordinal)
            .ToList();

        options = allOptions
            .Where(option => MatchesReferenceSearch(option, searchTerms, normalizedTerms))
            .OrderBy(option => option.Label, StringComparer.OrdinalIgnoreCase)
            .ThenBy(option => option.Value, StringComparer.OrdinalIgnoreCase)
            .Take(limit)
            .ToList();
        return options.Count > 0;
    }

    private bool TryBuildFastVisualReferenceOptions(
        string normalizedPicker,
        string term,
        int limit,
        out List<StudioReferenceOptionDto> options)
    {
        options = [];
        var kind = ResolveCustomVisualKindFromPicker(normalizedPicker);
        if (string.IsNullOrWhiteSpace(kind))
        {
            return false;
        }

        var objectReference = normalizedPicker.EndsWith("-object", StringComparison.OrdinalIgnoreCase)
                              || normalizedPicker.Equals("visual-icon-object", StringComparison.OrdinalIgnoreCase);
        var trimmed = term.Trim();
        var searchTerms = ExpandReferenceSearchTerms(normalizedPicker, trimmed).ToList();
        var normalizedTerms = searchTerms
            .Select(NormalizeLooseSearch)
            .Where(x => !string.IsNullOrWhiteSpace(x))
            .Distinct(StringComparer.Ordinal)
            .ToList();
        var result = new Dictionary<string, StudioReferenceOptionDto>(StringComparer.OrdinalIgnoreCase);

        foreach (var asset in GetCustomVisualAssetCatalog().Where(asset =>
                     asset.Kind.Equals(kind, StringComparison.OrdinalIgnoreCase)))
        {
            var value = objectReference ? asset.ObjectReference : asset.AssetReference;
            if (string.IsNullOrWhiteSpace(value))
            {
                continue;
            }

            var option = new StudioReferenceOptionDto(
                value,
                PrefixReferenceOptionLabel("Пользовательский ассет", asset.DisplayName));
            if (MatchesReferenceSearch(option, searchTerms, normalizedTerms))
            {
                result[value] = option;
            }
        }

        foreach (var relativePath in EnumerateFastReferenceSearchPaths(searchTerms))
        {
            var normalizedPath = PathUtil.NormalizeRelative(relativePath);
            if (!TryBuildFastGameVisualReferenceOption(
                    kind,
                    objectReference,
                    normalizedPath,
                    out var option))
            {
                continue;
            }

            if (MatchesReferenceSearch(option, searchTerms, normalizedTerms))
            {
                result[option.Value] = option;
            }
        }

        options = result.Values
            .OrderBy(option => option.Label, StringComparer.OrdinalIgnoreCase)
            .ThenBy(option => option.Value, StringComparer.OrdinalIgnoreCase)
            .Take(limit)
            .ToList();
        return true;
    }

    private IEnumerable<string> EnumerateFastReferenceSearchPaths(IReadOnlyList<string> searchTerms)
    {
        if (HasUsableScumInstallation())
        {
            var cachedMatches = PakIndexService.SearchCachedIndexPaths(_scum, searchTerms, maxMatches: 1024);
            if (cachedMatches.Count > 0 || _pakIndexCache is null)
            {
                return cachedMatches;
            }
        }

        if (_pakIndexCache is not null)
        {
            var normalizedTerms = searchTerms
                .Select(term => (term ?? string.Empty).Trim())
                .Where(term => term.Length >= 2)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (normalizedTerms.Count == 0)
            {
                return [];
            }

            return _pakIndexCache.GetAllRelativePaths()
                .Where(path => normalizedTerms.Any(term => path.Contains(term, StringComparison.OrdinalIgnoreCase)))
                .Take(1024)
                .ToList();
        }

        return [];
    }

    private static bool TryBuildFastGameVisualReferenceOption(
        string kind,
        bool objectReference,
        string relativePath,
        out StudioReferenceOptionDto option)
    {
        option = null!;
        var normalizedPath = PathUtil.NormalizeRelative(relativePath);
        string className;
        string label;

        switch (kind)
        {
            case "static-mesh":
                if (!IsVisualStaticMeshAssetCandidate(normalizedPath))
                {
                    return false;
                }

                className = "StaticMesh";
                label = PrefixReferenceOptionLabel("Модель", ResolveVisualAssetDisplayName(normalizedPath, "SM_"));
                break;
            case "skeletal-mesh":
                if (!IsVisualSkeletalMeshAssetCandidate(normalizedPath))
                {
                    return false;
                }

                className = "SkeletalMesh";
                label = PrefixReferenceOptionLabel("Модель", ResolveVisualAssetDisplayName(normalizedPath, "SK_"));
                break;
            case "material":
                if (!IsVisualMaterialAssetCandidate(normalizedPath))
                {
                    return false;
                }

                className = Path.GetFileNameWithoutExtension(normalizedPath).StartsWith("MI_", StringComparison.OrdinalIgnoreCase)
                    ? "MaterialInstanceConstant"
                    : "Material";
                label = PrefixReferenceOptionLabel("Материал", ResolveVisualAssetDisplayName(normalizedPath, "MI_", "M_", "MAT_"));
                break;
            case "texture":
                if (!IsVisualTextureAssetCandidate(normalizedPath))
                {
                    return false;
                }

                className = "Texture2D";
                label = PrefixReferenceOptionLabel("Текстура", ResolveVisualAssetDisplayName(normalizedPath, "T_", "TX_", "TEX_", "ICO_", "ICON_"));
                break;
            default:
                return false;
        }

        var value = objectReference
            ? BuildGameObjectReferenceFromRelativePath(normalizedPath, "/Script/Engine", className)
            : BuildSoftGameAssetReferenceFromRelativePath(normalizedPath);
        if (string.IsNullOrWhiteSpace(value))
        {
            return false;
        }

        option = new StudioReferenceOptionDto(value, label);
        return true;
    }

    private static string ResolveCustomVisualKindFromPicker(string normalizedPicker)
    {
        return normalizedPicker switch
        {
            "visual-static-mesh-object" or "visual-static-mesh-asset" => "static-mesh",
            "visual-skeletal-mesh-object" or "visual-skeletal-mesh-asset" => "skeletal-mesh",
            "visual-material-object" or "visual-material-asset" => "material",
            "visual-texture-object" or "visual-texture-asset" or "visual-icon-object" or "visual-icon-asset" => "texture",
            _ => string.Empty
        };
    }

    private static bool IsGenericGameplayPickerKind(string pickerKind)
    {
        return pickerKind is "generic-gameplay-asset"
            or "generic-gameplay-reference"
            or "gameplay-asset"
            or "gameplay-reference";
    }

