def center_vehicle_overlay_on_ground(meshes):
    if not vehicle_visual_overlay and not vehicle_query_proxy:
        return
    mins, maxs = world_bounds(meshes)
    center_x = (mins[0] + maxs[0]) * 0.5
    center_y = (mins[1] + maxs[1]) * 0.5
