        };
    }

    private static bool TryAnalyzeStlBounds(string sourcePath, out StudioModelBoundsDto bounds)
    {
        bounds = null!;
        var info = new FileInfo(sourcePath);
        if (!info.Exists || info.Length < 15 || info.Length > 512L * 1024L * 1024L)
        {
            return false;
        }

        try
        {
            if (TryAnalyzeAsciiStlBounds(sourcePath, out bounds))
            {
                return true;
            }
        }
        catch
        {
            bounds = null!;
        }

        var bytes = File.ReadAllBytes(sourcePath);
        if (bytes.Length < 84)
        {
            return false;
        }

        var triangleCount = BitConverter.ToUInt32(bytes, 80);
        var expectedLength = 84L + triangleCount * 50L;
        if (expectedLength > bytes.Length)
        {
            return false;
        }

        var accumulator = new ModelBoundsAccumulator();
        var offset = 84;
        for (var triangle = 0; triangle < triangleCount; triangle++)
        {
            var vertexOffset = offset + 12;
            for (var vertex = 0; vertex < 3; vertex++)
            {
                var x = BitConverter.ToSingle(bytes, vertexOffset);
                var y = BitConverter.ToSingle(bytes, vertexOffset + 4);
                var z = BitConverter.ToSingle(bytes, vertexOffset + 8);
                accumulator.Add(x, y, z);
                vertexOffset += 12;
            }

            offset += 50;
        }

        return accumulator.TryBuild(out bounds);
    }

    private static bool TryAnalyzeAsciiStlBounds(string sourcePath, out StudioModelBoundsDto bounds)
    {
        bounds = null!;
        var accumulator = new ModelBoundsAccumulator();
        var sawSolid = false;
        foreach (var line in File.ReadLines(sourcePath))
        {
            var trimmed = line.Trim();
            if (!sawSolid)
            {
                if (!trimmed.StartsWith("solid", StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }

                sawSolid = true;
                continue;
            }

            if (!trimmed.StartsWith("vertex ", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var parts = trimmed["vertex ".Length..].Split([' ', '\t'], StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length >= 3
                && double.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out var x)
                && double.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out var y)
                && double.TryParse(parts[2], NumberStyles.Float, CultureInfo.InvariantCulture, out var z))
            {
                accumulator.Add(x, y, z);
            }
        }

        return accumulator.TryBuild(out bounds);
    }

    private static bool TryAnalyzeAsciiPlyBounds(string sourcePath, out StudioModelBoundsDto bounds)
    {
        bounds = null!;
        using var reader = new StreamReader(sourcePath, Encoding.UTF8, detectEncodingFromByteOrderMarks: true);
        if (!string.Equals(reader.ReadLine()?.Trim(), "ply", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var vertexCount = 0;
        var isAscii = false;
        string? line;
        while ((line = reader.ReadLine()) is not null)
        {
            var trimmed = line.Trim();
            if (trimmed.Equals("format ascii 1.0", StringComparison.OrdinalIgnoreCase))
            {
                isAscii = true;
            }
            else if (trimmed.StartsWith("element vertex ", StringComparison.OrdinalIgnoreCase))
            {
                _ = int.TryParse(trimmed["element vertex ".Length..], NumberStyles.Integer, CultureInfo.InvariantCulture, out vertexCount);
            }
            else if (trimmed.Equals("end_header", StringComparison.OrdinalIgnoreCase))
            {
                break;
            }
        }

        if (!isAscii || vertexCount <= 0)
        {
            return false;
        }

        var accumulator = new ModelBoundsAccumulator();
        for (var i = 0; i < vertexCount && (line = reader.ReadLine()) is not null; i++)
        {
            var parts = line.Trim().Split([' ', '\t'], StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length >= 3
                && double.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out var x)
                && double.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out var y)
                && double.TryParse(parts[2], NumberStyles.Float, CultureInfo.InvariantCulture, out var z))
            {
                accumulator.Add(x, y, z);
            }
        }

        return accumulator.TryBuild(out bounds);
    }

    private static bool TryAnalyzeObjBounds(string sourcePath, out StudioModelBoundsDto bounds)
    {
        var accumulator = new ModelBoundsAccumulator();
        foreach (var line in File.ReadLines(sourcePath))
        {
            var trimmed = line.TrimStart();
            if (!trimmed.StartsWith("v ", StringComparison.Ordinal))
            {
                continue;
            }

            var parts = trimmed[2..].Split([' ', '\t'], StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length < 3
                || !double.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out var x)
                || !double.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out var y)
                || !double.TryParse(parts[2], NumberStyles.Float, CultureInfo.InvariantCulture, out var z))
            {
                continue;
            }

            accumulator.Add(x, y, z);
        }

        return accumulator.TryBuild(out bounds);
    }

    private static bool TryAnalyzeGlbBounds(string sourcePath, out StudioModelBoundsDto bounds)
    {
        bounds = null!;
        var bytes = File.ReadAllBytes(sourcePath);
        if (bytes.Length < 20
            || Encoding.ASCII.GetString(bytes, 0, 4) != "glTF")
        {
            return false;
        }

        var offset = 12;
        while (offset + 8 <= bytes.Length)
        {
            var chunkLength = BitConverter.ToInt32(bytes, offset);
            var chunkType = BitConverter.ToUInt32(bytes, offset + 4);
            offset += 8;
            if (chunkLength < 0 || offset + chunkLength > bytes.Length)
            {
                return false;
            }

            if (chunkType == 0x4E4F534A)
            {
                var json = Encoding.UTF8.GetString(bytes, offset, chunkLength).TrimEnd('\0', ' ');
                var root = JsonNode.Parse(json);
                return TryAnalyzeGltfBounds(root, out bounds);
            }

            offset += chunkLength;
        }

        return false;
    }

    private static bool TryAnalyzeGltfBounds(JsonNode? root, out StudioModelBoundsDto bounds)
    {
        bounds = null!;
        var accessors = root?["accessors"] as JsonArray;
        if (accessors is null)
        {
            return false;
        }

        var positionAccessorIndices = new HashSet<int>();
        if (root?["meshes"] is JsonArray meshes)
        {
            foreach (var meshNode in meshes)
            {
                if (meshNode?["primitives"] is not JsonArray primitives)
                {
                    continue;
                }

                foreach (var primitive in primitives)
                {
                    var positionIndex = primitive?["attributes"]?["POSITION"]?.GetValue<int?>();
                    if (positionIndex is int index)
                    {
                        positionAccessorIndices.Add(index);
                    }
                }
            }
        }

        if (positionAccessorIndices.Count == 0)
        {
            for (var i = 0; i < accessors.Count; i++)
            {
                if (accessors[i]?["type"]?.GetValue<string>()?.Equals("VEC3", StringComparison.OrdinalIgnoreCase) == true
                    && accessors[i]?["min"] is JsonArray
                    && accessors[i]?["max"] is JsonArray)
                {
                    positionAccessorIndices.Add(i);
                }
            }
        }

        var accumulator = new ModelBoundsAccumulator();
        foreach (var index in positionAccessorIndices)
        {
            if (index < 0 || index >= accessors.Count)
            {
                continue;
            }

            var accessor = accessors[index];
            if (accessor?["min"] is not JsonArray minArray
                || accessor?["max"] is not JsonArray maxArray
                || minArray.Count < 3
                || maxArray.Count < 3)
            {
                continue;
            }

            if (TryGetJsonDouble(minArray[0], out var minX)
                && TryGetJsonDouble(minArray[1], out var minY)
                && TryGetJsonDouble(minArray[2], out var minZ)
                && TryGetJsonDouble(maxArray[0], out var maxX)
                && TryGetJsonDouble(maxArray[1], out var maxY)
                && TryGetJsonDouble(maxArray[2], out var maxZ))
            {
                accumulator.Add(minX, minY, minZ);
                accumulator.Add(maxX, maxY, maxZ);
            }
        }

        return accumulator.TryBuild(out bounds);
    }

    private static bool TryAnalyzeAsciiFbxBounds(string sourcePath, out StudioModelBoundsDto bounds)
    {
        bounds = null!;
        var info = new FileInfo(sourcePath);
        if (!info.Exists || info.Length > 64L * 1024L * 1024L)
        {
            return false;
        }

        var text = File.ReadAllText(sourcePath);
        if (!text.Contains("Vertices:", StringComparison.Ordinal)
            || text.IndexOf('\0') >= 0)
        {
            return false;
        }

        var match = Regex.Match(
            text,
            @"Vertices:\s*\*\d+\s*\{(?<body>.*?)\}",
            RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.CultureInvariant);
        if (!match.Success)
        {
            return false;
        }

        var body = match.Groups["body"].Value;
        var aIndex = body.IndexOf("a:", StringComparison.OrdinalIgnoreCase);
        if (aIndex >= 0)
        {
            body = body[(aIndex + 2)..];
        }

        var numberMatches = Regex.Matches(
            body,
            @"[-+]?(?:\d+\.\d+|\d+|\.\d+)(?:[eE][-+]?\d+)?",
            RegexOptions.CultureInvariant);
        var accumulator = new ModelBoundsAccumulator();
        for (var i = 0; i + 2 < numberMatches.Count; i += 3)
        {
            if (double.TryParse(numberMatches[i].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var x)
                && double.TryParse(numberMatches[i + 1].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var y)
                && double.TryParse(numberMatches[i + 2].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var z))
            {
                accumulator.Add(x, y, z);
            }
        }

        return accumulator.TryBuild(out bounds);
    }

    private static bool TryGetJsonDouble(JsonNode? node, out double value)
    {
        value = 0;
        try
        {
            value = node?.GetValue<double>() ?? 0;
            return node is not null;
        }
        catch
        {
            return false;
        }
    }

    private sealed record BlendRawModelAnalysis(
        StudioModelBoundsDto Bounds,
        List<StudioRawModelPartDto> Parts,
        int ArmatureCount,
        int BoneCount,
        int MaterialCount,
        int HumanoidScore);

    private sealed class ModelBoundsAccumulator
    {
        private bool _hasValue;
        private double _minX;
        private double _minY;
        private double _minZ;
        private double _maxX;
        private double _maxY;
        private double _maxZ;

        public void Add(double x, double y, double z)
        {
            if (!_hasValue)
            {
                _hasValue = true;
                _minX = _maxX = x;
                _minY = _maxY = y;
                _minZ = _maxZ = z;
                return;
            }

            _minX = Math.Min(_minX, x);
            _minY = Math.Min(_minY, y);
            _minZ = Math.Min(_minZ, z);
            _maxX = Math.Max(_maxX, x);
            _maxY = Math.Max(_maxY, y);
            _maxZ = Math.Max(_maxZ, z);
        }

        public bool TryBuild(out StudioModelBoundsDto bounds)
        {
            bounds = null!;
            if (!_hasValue)
            {
                return false;
            }

            bounds = new StudioModelBoundsDto(
                _minX,
                _minY,
                _minZ,
                _maxX,
                _maxY,
                _maxZ,
                _maxX - _minX,
                _maxY - _minY,
                _maxZ - _minZ);
            return true;
        }
    }

    private static bool IsPathInsideDirectory(string path, string directory)
    {
        var normalizedPath = Path.GetFullPath(path)
            .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        var normalizedDirectory = Path.GetFullPath(directory)
            .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);

        return normalizedPath.Equals(normalizedDirectory, StringComparison.OrdinalIgnoreCase)
               || normalizedPath.StartsWith($"{normalizedDirectory}{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase)
               || normalizedPath.StartsWith($"{normalizedDirectory}{Path.AltDirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase);
    }

    private static bool TryBuildCustomVisualAssetInfo(string root, string sourcePath, out CustomVisualAssetInfo info)
    {
        info = null!;
        if (string.IsNullOrWhiteSpace(root)
            || string.IsNullOrWhiteSpace(sourcePath)
            || !sourcePath.EndsWith(".uasset", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (!TryResolveCustomAssetTargetRelativePath(root, sourcePath, out var targetRelativePath))
        {
            return false;
        }

        var kind = ResolveCustomVisualAssetKind(targetRelativePath);
        var className = ResolveCustomVisualAssetClassName(kind, targetRelativePath);
        if (TryInferCustomVisualAssetIdentity(sourcePath, out var inferredKind, out var inferredClassName))
        {
            kind = inferredKind;
            className = inferredClassName;
        }

        if (string.IsNullOrWhiteSpace(kind) || string.IsNullOrWhiteSpace(className))
        {
            return false;
        }

        var objectPath = BuildGameObjectPathFromTargetRelativePath(targetRelativePath);
        if (string.IsNullOrWhiteSpace(objectPath))
        {
            return false;
        }

        var dotIndex = objectPath.LastIndexOf('.');
        if (dotIndex <= 0 || dotIndex >= objectPath.Length - 1)
        {
            return false;
        }

        var displayName = ResolveCustomVisualAssetDisplayName(targetRelativePath, kind);
        info = new CustomVisualAssetInfo(
            sourcePath,
            targetRelativePath,
            objectPath,
            BuildImportedObjectReferenceRawValue(
                objectPath[..dotIndex],
                objectPath[(dotIndex + 1)..],
                "/Script/Engine",
                className),
            objectPath,
            displayName,
            kind);
        return true;
    }

    private static bool TryResolveCustomAssetTargetRelativePath(string root, string sourcePath, out string targetRelativePath)
    {
        targetRelativePath = string.Empty;
        string rel;
        try
        {
            rel = PathUtil.NormalizeRelative(Path.GetRelativePath(root, sourcePath));
        }
        catch
        {
            return false;
        }

        if (string.IsNullOrWhiteSpace(rel) || rel.StartsWith("../", StringComparison.Ordinal))
        {
            return false;
        }

        var segments = rel.Split('/', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (segments.Length == 0)
        {
            return false;
        }

        var scumIndex = Array.FindIndex(segments, segment => segment.Equals("SCUM", StringComparison.OrdinalIgnoreCase));
        if (scumIndex >= 0
            && scumIndex + 1 < segments.Length
            && segments[scumIndex + 1].Equals("Content", StringComparison.OrdinalIgnoreCase))
        {
            targetRelativePath = PathUtil.NormalizeRelative(string.Join('/', segments[scumIndex..]));
            return true;
        }

        var rootName = Path.GetFileName(root.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
        if (rootName.Equals("Content", StringComparison.OrdinalIgnoreCase))
        {
            targetRelativePath = PathUtil.NormalizeRelative($"SCUM/Content/{rel}");
            return true;
        }

        if (rootName.Equals("SCUM", StringComparison.OrdinalIgnoreCase)
            && rel.StartsWith("Content/", StringComparison.OrdinalIgnoreCase))
        {
            targetRelativePath = PathUtil.NormalizeRelative($"SCUM/{rel}");
            return true;
        }

        var contentIndex = Array.FindIndex(segments, segment => segment.Equals("Content", StringComparison.OrdinalIgnoreCase));
        if (contentIndex >= 0 && contentIndex + 1 < segments.Length)
        {
            targetRelativePath = PathUtil.NormalizeRelative($"SCUM/Content/{string.Join('/', segments[(contentIndex + 1)..])}");
            return true;
        }

        if (rel.StartsWith("Game/", StringComparison.OrdinalIgnoreCase))
        {
            targetRelativePath = PathUtil.NormalizeRelative($"SCUM/Content/{rel["Game/".Length..]}");
            return true;
        }

        targetRelativePath = PathUtil.NormalizeRelative($"SCUM/Content/ScumModStudio/Visuals/{rel}");
        return true;
    }

    private static bool TryInferCustomVisualAssetIdentity(string sourcePath, out string kind, out string className)
    {
        kind = string.Empty;
        className = string.Empty;

        UAsset asset;
        try
        {
            asset = new UAsset(sourcePath, EngineVersion.VER_UE4_27, null, CustomSerializationFlags.None);
        }
        catch
        {
            return false;
        }

        foreach (var export in asset.Exports.OfType<NormalExport>())
        {
            if (TryResolveImportObjectName(asset, export.ClassIndex, out var exportClassName)
                && TryMapEngineVisualClass(exportClassName, out kind, out className))
            {
                return true;
            }
        }

        var candidates = asset.Imports
            .Select(import => import.ObjectName?.ToString() ?? string.Empty)
            .Select(name => TryMapEngineVisualClass(name, out var candidateKind, out var candidateClassName)
                ? new { Kind = candidateKind, ClassName = candidateClassName }
                : null)
            .Where(candidate => candidate is not null)
            .DistinctBy(candidate => $"{candidate!.Kind}|{candidate.ClassName}", StringComparer.OrdinalIgnoreCase)
            .ToList();

        if (candidates.Count != 1)
        {
            return false;
        }

        kind = candidates[0]!.Kind;
        className = candidates[0]!.ClassName;
        return true;
    }

    private static bool TryMapEngineVisualClass(string rawClassName, out string kind, out string className)
    {
        kind = string.Empty;
        className = string.Empty;
        var normalized = (rawClassName ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return false;
        }

        if (normalized.Equals("StaticMesh", StringComparison.OrdinalIgnoreCase))
        {
            kind = "static-mesh";
            className = "StaticMesh";
            return true;
        }

        if (normalized.Equals("SkeletalMesh", StringComparison.OrdinalIgnoreCase))
        {
            kind = "skeletal-mesh";
            className = "SkeletalMesh";
            return true;
        }

        if (normalized.Equals("Skeleton", StringComparison.OrdinalIgnoreCase))
        {
            kind = "supporting-asset";
            className = "Skeleton";
            return true;
        }

        if (normalized.Equals("PhysicsAsset", StringComparison.OrdinalIgnoreCase))
        {
            kind = "supporting-asset";
            className = "PhysicsAsset";
            return true;
        }

        if (normalized.Equals("Texture2D", StringComparison.OrdinalIgnoreCase))
        {
            kind = "texture";
            className = "Texture2D";
            return true;
        }

        if (normalized.Equals("MaterialInstanceConstant", StringComparison.OrdinalIgnoreCase)
            || normalized.Equals("MaterialInstance", StringComparison.OrdinalIgnoreCase))
        {
            kind = "material";
            className = "MaterialInstanceConstant";
            return true;
        }

        if (normalized.Equals("Material", StringComparison.OrdinalIgnoreCase))
        {
            kind = "material";
            className = "Material";
            return true;
        }

        return false;
    }

    private static string ResolveCustomVisualAssetKind(string targetRelativePath)
    {
        var stem = Path.GetFileNameWithoutExtension(targetRelativePath);
        if (stem.StartsWith("SK_", StringComparison.OrdinalIgnoreCase))
        {
            return "skeletal-mesh";
        }

        if (stem.StartsWith("SM_", StringComparison.OrdinalIgnoreCase))
        {
            return "static-mesh";
        }

        if (stem.StartsWith("MI_", StringComparison.OrdinalIgnoreCase)
            || stem.StartsWith("M_", StringComparison.OrdinalIgnoreCase)
            || stem.StartsWith("MAT_", StringComparison.OrdinalIgnoreCase))
        {
            return "material";
        }

        if (stem.StartsWith("T_", StringComparison.OrdinalIgnoreCase)
            || stem.StartsWith("TX_", StringComparison.OrdinalIgnoreCase)
            || stem.StartsWith("TEX_", StringComparison.OrdinalIgnoreCase)
            || stem.StartsWith("ICO_", StringComparison.OrdinalIgnoreCase)
            || stem.StartsWith("ICON_", StringComparison.OrdinalIgnoreCase))
        {
            return "texture";
        }

        var normalizedPath = targetRelativePath.Replace('\\', '/');
        if (normalizedPath.Contains("/SkeletalMeshes/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/SkeletalMesh/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/Skeletal_Meshes/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/Skeletal_Mesh/", StringComparison.OrdinalIgnoreCase))
        {
            return "skeletal-mesh";
        }

        if (normalizedPath.Contains("/StaticMeshes/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/StaticMesh/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/Static_Meshes/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/Static_Mesh/", StringComparison.OrdinalIgnoreCase))
        {
            return "static-mesh";
        }

        if (normalizedPath.Contains("/Materials/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/MaterialInstances/", StringComparison.OrdinalIgnoreCase))
        {
            return "material";
        }

        if (normalizedPath.Contains("/Textures/", StringComparison.OrdinalIgnoreCase)
            || normalizedPath.Contains("/Icons/", StringComparison.OrdinalIgnoreCase))
        {
            return "texture";
        }

        return string.Empty;
    }

    private static string ResolveCustomVisualAssetClassName(string kind, string targetRelativePath)
    {
        return kind switch
        {
            "static-mesh" => "StaticMesh",
            "skeletal-mesh" => "SkeletalMesh",
            "texture" => "Texture2D",
            "material" => Path.GetFileNameWithoutExtension(targetRelativePath).StartsWith("MI_", StringComparison.OrdinalIgnoreCase)
                ? "MaterialInstanceConstant"
                : "Material",
            _ => string.Empty
        };
    }

    private static string ResolveCustomVisualAssetDisplayName(string targetRelativePath, string kind)
    {
        var stem = Path.GetFileNameWithoutExtension(targetRelativePath);
        var display = kind switch
        {
            "static-mesh" => ResolveVisualAssetDisplayName(targetRelativePath, "SM_"),
            "skeletal-mesh" => ResolveVisualAssetDisplayName(targetRelativePath, "SK_"),
            "material" => ResolveVisualAssetDisplayName(targetRelativePath, "MI_", "M_", "MAT_"),
            "texture" => ResolveVisualAssetDisplayName(targetRelativePath, "T_", "TX_", "TEX_", "ICO_", "ICON_"),
            _ => LocalizeAssetStem(stem)
        };

        return string.IsNullOrWhiteSpace(display) ? stem : display;
    }

    private static string BuildGameObjectPathFromTargetRelativePath(string targetRelativePath)
    {
        var normalized = PathUtil.NormalizeRelative(targetRelativePath);
        if (!normalized.EndsWith(".uasset", StringComparison.OrdinalIgnoreCase))
        {
            return string.Empty;
        }

        var withoutExtension = normalized[..^".uasset".Length];
        var contentRelative = withoutExtension.StartsWith("SCUM/Content/", StringComparison.OrdinalIgnoreCase)
            ? withoutExtension["SCUM/Content/".Length..]
            : withoutExtension.StartsWith("scum/content/", StringComparison.OrdinalIgnoreCase)
                ? withoutExtension["scum/content/".Length..]
                : string.Empty;
        if (string.IsNullOrWhiteSpace(contentRelative))
        {
            return string.Empty;
        }

        var objectName = Path.GetFileNameWithoutExtension(normalized);
        return $"/Game/{contentRelative}.{objectName}";
    }

    private static bool IsGameplayVisualAssetPath(string relativePath)
    {
        var path = PathUtil.NormalizeRelative(relativePath).ToLowerInvariant();
        if (!path.EndsWith(".uasset", StringComparison.OrdinalIgnoreCase)
            || !path.StartsWith("scum/content/", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (path.Contains("/ui/", StringComparison.Ordinal)
            || path.Contains("/widgets/", StringComparison.Ordinal)
            || path.Contains("/stringtables/", StringComparison.Ordinal)
            || path.Contains("/vfx/", StringComparison.Ordinal)
            || path.Contains("/fx/", StringComparison.Ordinal)
            || path.Contains("/sounds/", StringComparison.Ordinal)
            || path.Contains("/audio/", StringComparison.Ordinal))
        {
            return false;
        }

        return true;
    }

    private static bool IsVisualStaticMeshAssetCandidate(string relativePath)
    {
        if (!IsGameplayVisualAssetPath(relativePath))
        {
            return false;
        }

        var path = PathUtil.NormalizeRelative(relativePath).ToLowerInvariant();
        var stem = Path.GetFileNameWithoutExtension(path);
        return stem.StartsWith("sm_", StringComparison.OrdinalIgnoreCase)
               || (path.Contains("/meshes/", StringComparison.Ordinal) && !stem.StartsWith("sk_", StringComparison.OrdinalIgnoreCase))
               || (path.Contains("/models/", StringComparison.Ordinal) && stem.StartsWith("sm_", StringComparison.OrdinalIgnoreCase));
    }

