    private static string NormalizeLooseSearch(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return string.Empty;
        }

        var chars = value
            .Where(char.IsLetterOrDigit)
            .Select(char.ToLowerInvariant)
            .ToArray();
        return new string(chars);
    }

    private static bool ContainsIgnoreCase(string text, string term)
    {
        if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(term))
        {
            return false;
        }

        return text.IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static bool ContainsSearchTermAtBoundary(string text, string term)
    {
        if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(term))
        {
            return false;
        }

        var start = 0;
        while (start < text.Length)
        {
            var index = text.IndexOf(term, start, StringComparison.OrdinalIgnoreCase);
            if (index < 0)
            {
                return false;
            }

            var boundaryBefore = index == 0 || !char.IsLetterOrDigit(text[index - 1]);
            if (boundaryBefore)
            {
                return true;
            }

            start = index + 1;
        }

        return false;
    }

    private static int ComputeModAssetSearchScore(StudioModAssetDto asset, string term, string looseTerm)
    {
        if (string.IsNullOrWhiteSpace(term))
        {
            return 1;
        }

        var displayName = asset.DisplayName ?? string.Empty;
        var relativePath = asset.RelativePath ?? string.Empty;
        var categoryName = asset.CategoryName ?? string.Empty;
        var summary = asset.Summary ?? string.Empty;
        var stem = Path.GetFileNameWithoutExtension(relativePath) ?? string.Empty;

        var displayStarts = displayName.StartsWith(term, StringComparison.OrdinalIgnoreCase);
        var displayBoundary = ContainsSearchTermAtBoundary(displayName, term);
        var pathBoundary = ContainsSearchTermAtBoundary(relativePath, term);
        var stemStarts = stem.StartsWith(term, StringComparison.OrdinalIgnoreCase);

        var score = 0;
        if (displayStarts)
        {
            score += 320;
        }
        else if (displayBoundary)
        {
            score += 260;
        }
        else if (ContainsIgnoreCase(displayName, term))
        {
            score += 150;
        }

        if (stemStarts)
        {
            score += 260;
        }
        else if (pathBoundary)
        {
            score += 180;
        }
        else if (ContainsIgnoreCase(relativePath, term))
        {
            score += 80;
        }

        if (ContainsIgnoreCase(categoryName, term))
        {
            score += 40;
        }

        if (ContainsIgnoreCase(summary, term))
        {
            score += 20;
        }

        if (!string.IsNullOrWhiteSpace(looseTerm))
        {
            var normalizedDisplay = NormalizeLooseSearch(displayName);
            var normalizedPath = NormalizeLooseSearch(relativePath);
            var normalizedSummary = NormalizeLooseSearch(summary);
            var normalizedStem = NormalizeLooseSearch(stem);

            if (normalizedStem.StartsWith(looseTerm, StringComparison.Ordinal))
            {
                score += 220;
            }
            else if (normalizedPath.Contains(looseTerm, StringComparison.Ordinal))
            {
                score += 80;
            }

            if (normalizedDisplay.StartsWith(looseTerm, StringComparison.Ordinal))
            {
                score += 180;
            }
            else if (normalizedDisplay.Contains(looseTerm, StringComparison.Ordinal))
            {
                score += 90;
            }

            if (normalizedSummary.Contains(looseTerm, StringComparison.Ordinal))
            {
                score += 15;
            }

            var isShortTerm = looseTerm.Length <= 2;
            if (isShortTerm)
            {
                var strongMatch = displayStarts
                                  || displayBoundary
                                  || stemStarts
                                  || pathBoundary
                                  || normalizedStem.StartsWith(looseTerm, StringComparison.Ordinal);
                if (!strongMatch)
                {
                    return 0;
                }

                score += 60;
            }
        }

        return score;
    }

    private static int ComputeGenericGameplayReferenceSearchScore(StudioReferenceOptionDto option, string term, string looseTerm)
    {
        var label = option.Label ?? string.Empty;
        var value = option.Value ?? string.Empty;
        var normalizedLabel = NormalizeLooseSearch(label);
        var normalizedValue = NormalizeLooseSearch(value);

        var score = 0;
        if (label.StartsWith(term, StringComparison.OrdinalIgnoreCase))
        {
            score += 240;
        }
        else if (label.Contains(term, StringComparison.OrdinalIgnoreCase))
        {
            score += 150;
        }

        if (value.Contains(term, StringComparison.OrdinalIgnoreCase))
        {
            score += 90;
        }

        if (!string.IsNullOrWhiteSpace(looseTerm))
        {
            if (normalizedLabel.StartsWith(looseTerm, StringComparison.Ordinal))
            {
                score += 200;
            }
            else if (normalizedLabel.Contains(looseTerm, StringComparison.Ordinal))
            {
                score += 110;
            }

            if (normalizedValue.Contains(looseTerm, StringComparison.Ordinal))
            {
                score += 70;
            }
        }

        var normalizedTerm = NormalizeLooseSearch(term);
        var asksVehicle = normalizedTerm.Contains("маш", StringComparison.Ordinal)
                          || normalizedTerm.Contains("авто", StringComparison.Ordinal)
                          || normalizedTerm.Contains("трансп", StringComparison.Ordinal)
                          || normalizedTerm.Contains("vehicle", StringComparison.Ordinal)
                          || normalizedTerm.Contains("car", StringComparison.Ordinal);
        if (asksVehicle)
        {
            if (value.Contains("/vehicles/", StringComparison.OrdinalIgnoreCase))
            {
                score += 350;
            }
            else if (value.Contains("/vehicle/", StringComparison.OrdinalIgnoreCase))
            {
                score += 210;
            }
        }

        var asksWeapon = normalizedTerm.Contains("оруж", StringComparison.Ordinal)
                         || normalizedTerm.Contains("патрон", StringComparison.Ordinal)
                         || normalizedTerm.Contains("weapon", StringComparison.Ordinal)
                         || normalizedTerm.Contains("ammo", StringComparison.Ordinal);
        if (asksWeapon && value.Contains("/items/weapons/", StringComparison.OrdinalIgnoreCase))
        {
            score += 260;
        }

        var asksEvent = normalizedTerm.Contains("ивент", StringComparison.Ordinal)
                        || normalizedTerm.Contains("событ", StringComparison.Ordinal)
                        || normalizedTerm.Contains("event", StringComparison.Ordinal)
                        || normalizedTerm.Contains("encounter", StringComparison.Ordinal);
        if (asksEvent && (value.Contains("/encounters/", StringComparison.OrdinalIgnoreCase)
                          || value.Contains("/worldevents/", StringComparison.OrdinalIgnoreCase)
                          || value.Contains("/gameevents/", StringComparison.OrdinalIgnoreCase)))
        {
            score += 260;
        }

        return score;
    }

    private static bool MatchesReferenceSearch(
        StudioReferenceOptionDto option,
        IReadOnlyList<string> searchTerms,
        IReadOnlyList<string> normalizedTerms)
    {
        var normalizedLabel = NormalizeLooseSearch(option.Label);
        var normalizedValue = NormalizeLooseSearch(option.Value);
        return searchTerms.Any(searchTerm =>
                   option.Label.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
                   || option.Value.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
               || normalizedTerms.Any(loose =>
                   normalizedLabel.Contains(loose, StringComparison.Ordinal)
                   || normalizedValue.Contains(loose, StringComparison.Ordinal));
    }

    private static bool MatchesLooseSearchText(
        string primaryText,
        string secondaryText,
        IReadOnlyList<string> searchTerms,
        IReadOnlyList<string> normalizedTerms)
    {
        var normalizedPrimary = NormalizeLooseSearch(primaryText);
        var normalizedSecondary = NormalizeLooseSearch(secondaryText);
        return searchTerms.Any(searchTerm =>
                   (!string.IsNullOrWhiteSpace(primaryText) && primaryText.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
                   || (!string.IsNullOrWhiteSpace(secondaryText) && secondaryText.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)))
               || normalizedTerms.Any(loose =>
                   (!string.IsNullOrWhiteSpace(normalizedPrimary) && normalizedPrimary.Contains(loose, StringComparison.Ordinal))
                   || (!string.IsNullOrWhiteSpace(normalizedSecondary) && normalizedSecondary.Contains(loose, StringComparison.Ordinal)));
    }

