        bool SupportsAddClone,
        bool SupportsRemove,
        bool SupportsClear,
        bool SupportsAddEmpty,
        bool SupportsAddReference,
        string? referencePickerKind)
    {
        output.Add(new StudioListDiscoveryCandidateDto(
            targetPath,
            sourceLabel,
            label,
            itemKind,
            itemCount,
            exposed,
            exposed
                ? "Показывается как редактируемый список."
                : "Скрыто: контейнер не входит в текущий allowlist безопасных списков.",
            SupportsAddClone,
            SupportsRemove,
            SupportsClear,
            SupportsAddEmpty,
            SupportsAddReference,
            referencePickerKind));
    }

    private static string ResolveFieldDiscoveryVisibility(
        string relativePath,
        string userLabel,
        string valueType,
        bool safeFilterPassed,
        bool blockedByAssetRef,
        bool hiddenOpaqueLocalization,
        bool exposed)
    {
        if (exposed)
        {
            return "Показывается как безопасная настройка.";
        }

        if (hiddenOpaqueLocalization)
        {
            return "Скрыто: похоже на внутренний ключ локализации, а не пользовательский текст.";
        }

        if (blockedByAssetRef)
        {
            return "Скрыто: ссылка на ассет пока не имеет безопасного picker для этого контекста.";
        }

        if (!safeFilterPassed)
        {
            return GuessSafeFieldHiddenReason(relativePath, userLabel, valueType);
        }

        return "Скрыто дополнительным защитным правилом.";
    }

    private static string GuessSafeFieldHiddenReason(string relativePath, string userLabel, string valueType)
    {
        if (string.IsNullOrWhiteSpace(userLabel))
        {
            return "Скрыто: пустое имя поля.";
        }

        if (userLabel.Length > 160)
        {
            return "Скрыто: слишком длинный технический путь поля.";
        }

        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();
        var technicalNoiseTokens = new[]
        {
            "icon", "ico", "image", "brush", "texture", "material", "mesh", "skeletal",
            "sound", "audio", "anim", "widget", "sprite", "atlas", "thumbnail", "font",
            "padding", "margin", "alignment", "offset", "shadow", "color", "opacity",
            "pre infinity", "post infinity", "extrap", "default значение", "default value"
        };
        if (technicalNoiseTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            return "Скрыто: техническое/визуальное поле, которое может ломать ассет без отдельной безопасной логики.";
        }

        if (path.Contains("/ui/", StringComparison.Ordinal) && valueType is "string" or "text" or "name")
        {
            return "Скрыто: текст интерфейса часто хранится ключами локализации, а не готовыми строками.";
        }

        if (IsMapGameplayAsset(relativePath))
        {
            return "Скрыто: поле карты не похоже на безопасную точку спавна, NPC, транспорт, торговца или квест.";
        }

        if (valueType is "string" or "text" or "name" or "enum")
        {
            return "Скрыто: строковое поле не похоже на безопасный ID, тип, категорию, группу или разрешённый режим.";
        }

        if (valueType is "soft-object" or "soft-object-path" or "object")
        {
            return "Скрыто: ссылка на ассет не распознана как безопасный предмет, награда, патрон, модель или игровой класс.";
        }

        return "Скрыто: поле не входит в текущий allowlist безопасных игровых параметров этой поверхности.";
    }

    private static List<StudioModFieldDto> ApplyVehicleAutomaticSpawnFieldContext(
        string relativePath,
        List<StudioModFieldDto> fields)
    {
        if (fields.Count == 0
            || string.IsNullOrWhiteSpace(relativePath)
            || !relativePath.Contains("/vehicles/spawningpresets/automaticspawn/", StringComparison.OrdinalIgnoreCase))
        {
            return fields;
        }

        var duplicateLabels = fields
            .GroupBy(field => field.Label, StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.Key)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (duplicateLabels.Count == 0)
        {
            return fields;
        }

        var exportIndices = fields
            .Where(field => duplicateLabels.Contains(field.Label))
            .Select(field => TryParseExportIndexFromFieldPath(field.FieldPath))
            .Where(index => index.HasValue)
            .Select(index => index!.Value)
            .Distinct()
            .OrderBy(index => index)
            .ToList();
        if (exportIndices.Count == 0)
        {
            return fields;
        }

        var exportVariantMap = new Dictionary<int, int>(exportIndices.Count);
        for (var i = 0; i < exportIndices.Count; i++)
        {
            exportVariantMap[exportIndices[i]] = i + 1;
        }

        var rewritten = new List<StudioModFieldDto>(fields.Count);
        foreach (var field in fields)
        {
            if (!duplicateLabels.Contains(field.Label)
                || !TryParseExportIndexFromFieldPath(field.FieldPath).HasValue)
            {
                rewritten.Add(field);
                continue;
            }

            var exportIndex = TryParseExportIndexFromFieldPath(field.FieldPath)!.Value;
            if (!exportVariantMap.TryGetValue(exportIndex, out var variantOrder))
            {
                rewritten.Add(field);
                continue;
            }

            var contextualLabel = $"Вариант транспорта #{variantOrder} / {field.Label}";
            rewritten.Add(field with { Label = contextualLabel });
        }

        return rewritten;
    }

    private static bool ShouldInspectMapExport(UAsset asset, NormalExport export, int exportIndex)
    {
        if (export.Data.Count == 0)
        {
            return false;
        }

        if (IsMapRelevantExportToken(export.ObjectName?.ToString()))
        {
            return true;
        }

        if (TryResolveImportObjectName(asset, export.ClassIndex, out var className)
            && IsMapRelevantExportToken(className))
        {
            return true;
        }

        if (export.OuterIndex.Index > 0)
        {
            var guard = 0;
            var outerExportIndex = export.OuterIndex.Index - 1;
            while (outerExportIndex >= 0
                   && outerExportIndex < asset.Exports.Count
                   && guard++ < 8)
            {
                var outer = asset.Exports[outerExportIndex];
                if (IsMapRelevantExportToken(outer.ObjectName?.ToString()))
                {
                    return true;
                }

                if (outer is NormalExport outerNormal
                    && TryResolveImportObjectName(asset, outerNormal.ClassIndex, out var outerClassName)
                    && IsMapRelevantExportToken(outerClassName))
                {
                    return true;
                }

                if (outer.OuterIndex.Index <= 0)
                {
                    break;
                }

                outerExportIndex = outer.OuterIndex.Index - 1;
            }
        }

        return false;
    }

    private static bool IsMapRelevantExportToken(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
        {
            return false;
        }

        var token = raw.ToLowerInvariant();
        if (token.Equals("persistentlevel", StringComparison.Ordinal))
        {
            return false;
        }

        var relevantTokens = new[]
        {
            "sentry", "sentryspawner", "vehiclespawner", "vehiclespawnbox",
            "npcinteractionbox", "questgiver", "trader",
            "waypoint", "patrol", "route", "marker", "sedentarynpc",
            "guardvolume", "guardedzone", "spline"
        };

        return relevantTokens.Any(value => token.Contains(value, StringComparison.Ordinal));
    }

    private static bool ShouldIncludeMapRootProperty(PropertyData property, string rootName)
    {
        if (string.IsNullOrWhiteSpace(rootName))
        {
            return false;
        }

        var key = NormalizeAssetKey(rootName);
        if (string.IsNullOrWhiteSpace(key))
        {
            return false;
        }

        var blockedTokens = new[]
        {
            "instancecounttorender",
            "allowculldistancevolume",
            "ballowculldistancevolume",
            "mindrawdistance",
            "maxdrawdistance",
            "culldistance",
            "streamingdistance",
            "lightmap",
            "lod",
            "distancefield",
            "material",
            "mesh",
            "collision"
        };
        if (blockedTokens.Any(token => key.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        var alwaysAllowedTokens = new[]
        {
            "relativelocation",
            "relativerotation",
            "relativescale3d",
            "itemspawnlimit",
            "spawnermarkers",
            "itemclasses",
            "vehiclepresets",
            "presets",
            "caneverrespawn",
            "caneverrespawnsentry",
            "radius",
            "relevancydistance",
            "spawndistance",
            "spawnchance",
            "probability",
            "shouldraycastspawnposition"
        };
        if (alwaysAllowedTokens.Any(token => key.Contains(token, StringComparison.Ordinal)))
        {
            return true;
        }

        if (property is ObjectPropertyData or SoftObjectPropertyData or SoftObjectPathPropertyData)
        {
            var referenceTokens = new[]
            {
                "vehiclespawnbox", "spawnbox", "spawner", "itemspawner",
                "npcinteractionbox", "questgiver", "questgivercomponent", "trader",
                "waypoint", "patrol", "route", "marker",
                "childactorclass", "childactortemplate", "sedentarynpc"
            };
            return referenceTokens.Any(token => key.Contains(token, StringComparison.Ordinal));
        }

        if (property is ArrayPropertyData or SetPropertyData or MapPropertyData)
        {
            var listTokens = new[]
            {
                "markers", "points", "point", "waypoint", "patrol", "route",
                "spawn", "classes", "presets", "trader", "npc"
            };
            return listTokens.Any(token => key.Contains(token, StringComparison.Ordinal));
        }

        if (property is StructPropertyData)
        {
            var structTokens = new[]
            {
                "spawn", "marker", "point", "waypoint", "patrol", "route", "location", "rotation"
            };
            return structTokens.Any(token => key.Contains(token, StringComparison.Ordinal));
        }

        if (property is BoolPropertyData or IntPropertyData or Int8PropertyData or Int16PropertyData or Int64PropertyData
            or UInt16PropertyData or UInt32PropertyData or UInt64PropertyData
            or FloatPropertyData or DoublePropertyData)
        {
            var scalarTokens = new[]
            {
                "spawn", "radius", "limit", "count", "respawn", "chance", "probability",
                "location", "rotation", "relevancydistance", "spawndistance"
            };
            return scalarTokens.Any(token => key.Contains(token, StringComparison.Ordinal));
        }

        return false;
    }

    private static List<StudioModFieldDto> ApplyMapFieldContext(UAsset asset, List<StudioModFieldDto> fields)
    {
        if (fields.Count == 0)
        {
            return fields;
        }

        var duplicateLabels = fields
            .GroupBy(field => field.Label, StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.Key)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (duplicateLabels.Count == 0)
        {
            return fields;
        }

        var exportIndices = fields
            .Where(field => duplicateLabels.Contains(field.Label))
            .Select(field => TryParseExportIndexFromFieldPath(field.FieldPath))
            .Where(index => index.HasValue)
            .Select(index => ResolveMapContextRootExportIndex(asset, index!.Value))
            .Distinct()
            .OrderBy(index => index)
            .ToList();
        var exportOrderByIndex = BuildMapContextVariantOrderMap(asset, exportIndices);

        var rewritten = new List<StudioModFieldDto>(fields.Count);
        foreach (var field in fields)
        {
            if (!duplicateLabels.Contains(field.Label))
            {
                rewritten.Add(field);
                continue;
            }

            var exportIndex = TryParseExportIndexFromFieldPath(field.FieldPath);
            if (!exportIndex.HasValue
                || exportIndex.Value < 0
                || exportIndex.Value >= asset.Exports.Count)
            {
                rewritten.Add(field);
                continue;
            }

            var rootExportIndex = ResolveMapContextRootExportIndex(asset, exportIndex.Value);
            var entityLabel = ResolveMapExportContextLabel(asset, rootExportIndex);
            var variantOrder = exportOrderByIndex.TryGetValue(rootExportIndex, out var order) ? order : rootExportIndex + 1;
            rewritten.Add(field with { Label = $"{entityLabel} #{variantOrder} / {field.Label}" });
        }

        return rewritten;
    }

    private static List<StudioModListTargetDto> ApplyMapListTargetContext(UAsset asset, List<StudioModListTargetDto> targets)
    {
        if (targets.Count == 0)
        {
            return targets;
        }

        var duplicateLabels = targets
            .GroupBy(target => target.Label, StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.Key)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (duplicateLabels.Count == 0)
        {
            return targets;
        }

        var exportIndices = targets
            .Where(target => duplicateLabels.Contains(target.Label))
            .Select(target => TryParseExportIndexFromFieldPath(target.TargetPath))
            .Where(index => index.HasValue)
            .Select(index => ResolveMapContextRootExportIndex(asset, index!.Value))
            .Distinct()
            .OrderBy(index => index)
            .ToList();
        var exportOrderByIndex = BuildMapContextVariantOrderMap(asset, exportIndices);

        var rewritten = new List<StudioModListTargetDto>(targets.Count);
        foreach (var target in targets)
        {
            if (!duplicateLabels.Contains(target.Label))
            {
                rewritten.Add(target);
                continue;
            }

            var exportIndex = TryParseExportIndexFromFieldPath(target.TargetPath);
            if (!exportIndex.HasValue
                || exportIndex.Value < 0
                || exportIndex.Value >= asset.Exports.Count)
            {
                rewritten.Add(target);
                continue;
            }

            var rootExportIndex = ResolveMapContextRootExportIndex(asset, exportIndex.Value);
            var entityLabel = ResolveMapExportContextLabel(asset, rootExportIndex);
            var variantOrder = exportOrderByIndex.TryGetValue(rootExportIndex, out var order) ? order : rootExportIndex + 1;
            rewritten.Add(target with { Label = $"{entityLabel} #{variantOrder} / {target.Label}" });
        }

        return rewritten;
    }

    private static List<StudioModFieldDto> PrioritizeMapFields(List<StudioModFieldDto> fields)
    {
        if (fields.Count <= 1)
        {
            return fields;
        }

        return fields
            .OrderByDescending(field => ScoreMapField(field.Label))
            .ThenBy(field => field.Label, StringComparer.OrdinalIgnoreCase)
            .ThenBy(field => field.FieldPath, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private static List<StudioModListTargetDto> PrioritizeMapListTargets(List<StudioModListTargetDto> targets)
    {
        if (targets.Count <= 1)
        {
            return targets;
        }

        return targets
            .OrderByDescending(target => ScoreMapField(target.Label))
            .ThenBy(target => target.Label, StringComparer.OrdinalIgnoreCase)
            .ThenBy(target => target.TargetPath, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private static int ScoreMapField(string? rawLabel)
    {
        var label = (rawLabel ?? string.Empty).ToLowerInvariant();
        if (string.IsNullOrWhiteSpace(label))
        {
            return 0;
        }

        var score = 0;
        var highValueTokens = new[]
        {
            "маршрут", "patrol", "waypoint", "точка маршрута робота",
            "робот", "sentry", "guard", "охраня",
            "торгов", "trader", "npc", "quest giver", "квест",
            "транспорт", "vehicle", "точка на карте", "поворот точки",
            "точка появления npc", "где появляются купленные товары", "где появляется запас торговца"
        };
        if (highValueTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            score += 500;
        }

        var mediumTokens = new[]
        {
            "точки спавна", "spawn transform", "метки торговца", "координаты", "класс сидячего npc",
            "активность сидячего npc", "дистанция активности сидячего npc",
            "проверять позицию спавна лучом", "пресеты транспорта", "варианты транспорта"
        };
        if (mediumTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            score += 220;
        }

        if (label.Contains("маршрут робота", StringComparison.Ordinal)
            || label.Contains("точка маршрута робота", StringComparison.Ordinal))
        {
            score += 240;
        }

        if (label.Contains("brush component", StringComparison.Ordinal)
            || label.Contains("scene component", StringComparison.Ordinal)
            || label.Contains("default scene root", StringComparison.Ordinal))
        {
            score -= 180;
        }

        if (label.Contains("метки торговца", StringComparison.Ordinal)
            && label.Contains("масштаб", StringComparison.Ordinal))
        {
            score -= 260;
        }

        if (label.Contains(" / spawner / ", StringComparison.Ordinal)
            || label.Contains(" spawner / ", StringComparison.Ordinal))
        {
            score -= 180;
        }

        var lowValueTokens = new[]
        {
            "always spawn", "probability", "use item zone", "use item rarity", "use item spawn group",
            "начальный damage", "randomize damage", "начальный dirtiness", "randomize dirtiness",
            "ammo count", "stack amount", "начальный расход за крафт", "randomize расход за крафт",
            "пресеты лута"
        };
        if (lowValueTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            score -= 320;
        }

        return score;
    }

    private static string ResolveMapExportContextLabel(UAsset asset, int exportIndex)
    {
        var rootExportIndex = ResolveMapContextRootExportIndex(asset, exportIndex);
        if (rootExportIndex < 0 || rootExportIndex >= asset.Exports.Count)
        {
            return "Точка карты";
        }

        var currentIndex = rootExportIndex;
        for (var guard = 0; guard < 8 && currentIndex >= 0 && currentIndex < asset.Exports.Count; guard++)
        {
            var export = asset.Exports[currentIndex];
            var objectName = export.ObjectName?.ToString() ?? $"export_{currentIndex}";
            var candidate = ResolveMapEntityLabel(objectName);
            if (!IsGenericMapEntityName(objectName))
            {
                return candidate;
            }

            if (export.OuterIndex.Index <= 0)
            {
                return candidate;
            }

            currentIndex = export.OuterIndex.Index - 1;
        }

        var fallbackName = asset.Exports[rootExportIndex].ObjectName?.ToString() ?? $"export_{rootExportIndex}";
        return ResolveMapEntityLabel(fallbackName);
    }

    private static Dictionary<int, int> BuildMapContextVariantOrderMap(UAsset asset, IEnumerable<int> exportIndices)
    {
        var result = new Dictionary<int, int>();
        var groups = exportIndices
            .Distinct()
            .Select(index => new
            {
                Index = index,
                Label = ResolveMapExportContextLabel(asset, index)
            })
            .GroupBy(item => item.Label, StringComparer.OrdinalIgnoreCase);

        foreach (var group in groups)
        {
            var ordered = group
                .OrderBy(item => item.Index)
                .ToList();
            for (var i = 0; i < ordered.Count; i++)
            {
                result[ordered[i].Index] = i + 1;
            }
        }

        return result;
    }

    private static int ResolveMapContextRootExportIndex(UAsset asset, int exportIndex)
    {
        if (exportIndex < 0 || exportIndex >= asset.Exports.Count)
        {
            return exportIndex;
        }

        var currentIndex = exportIndex;
        for (var guard = 0; guard < 8 && currentIndex >= 0 && currentIndex < asset.Exports.Count; guard++)
        {
            var export = asset.Exports[currentIndex];
            var objectName = export.ObjectName?.ToString() ?? $"export_{currentIndex}";
            if (!IsGenericMapEntityName(objectName))
            {
                return currentIndex;
            }

            if (export.OuterIndex.Index <= 0)
            {
                return currentIndex;
            }

            currentIndex = export.OuterIndex.Index - 1;
        }

        return exportIndex;
    }

    private static bool IsGenericMapEntityName(string rawObjectName)
    {
        var key = NormalizeAssetKey(rawObjectName);
        if (string.IsNullOrWhiteSpace(key))
        {
            return true;
        }

        var genericTokens = new[]
        {
            "brushcomponent",
            "scenecomponent",
            "rootcomponent",
            "defaultsceneroot",
            "staticmeshcomponent",
            "instancedstaticmeshcomponent",
            "hierarchicalinstancedstaticmeshcomponent",
            "boxcomponent",
            "arrowcomponent",
            "billboardcomponent",
            "childactorcomponent"
        };

        return genericTokens.Any(token => key.Contains(token, StringComparison.Ordinal));
    }

    private static string ResolveMapEntityLabel(string objectName)
    {
        var raw = (objectName ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(raw))
        {
            return "Точка карты";
        }

        var normalized = raw.ToLowerInvariant();
        if (normalized.Contains("sentry", StringComparison.Ordinal))
        {
            return "Робот-спавнер";
        }

        if (normalized.Contains("vehiclespawnbox", StringComparison.Ordinal))
        {
            return "Точка спавна транспорта";
        }

        if (normalized.Contains("vehiclespawner", StringComparison.Ordinal))
        {
            return "Спавнер транспорта";
        }

        if (normalized.Contains("sentryspawner", StringComparison.Ordinal))
        {
            return "Спавнер робота";
        }

        if (normalized.Contains("guardedzonemanager", StringComparison.Ordinal))
        {
            return "Менеджер охраняемой зоны";
        }

        if (normalized.Contains("guardvolume", StringComparison.Ordinal))
        {
            return "Охраняемая зона";
        }

        if (normalized.Contains("splinezone", StringComparison.Ordinal))
        {
            return "Сплайн-зона";
        }

        if (normalized.Contains("splinecomponent", StringComparison.Ordinal))
        {
            return "Линия маршрута";
        }

        if (normalized.Contains("itemspawnergroup", StringComparison.Ordinal))
        {
            return "Группа спавна предметов";
        }

        if (normalized.Contains("worlditemspawner", StringComparison.Ordinal))
        {
            return "Спавнер мирового предмета";
        }

        if (normalized.Contains("itemspawner", StringComparison.Ordinal))
        {
            return "Спавнер предметов";
        }

        if (normalized.Contains("npcinteractionbox", StringComparison.Ordinal))
        {
            return "Зона взаимодействия NPC";
        }

        if (normalized.Contains("fishermantrader", StringComparison.Ordinal))
        {
            return "Торговец-рыбак";
        }

        if (normalized.Contains("trader", StringComparison.Ordinal)
            && normalized.Contains("interactionbox", StringComparison.Ordinal))
        {
            return "Зона торговца";
        }

        if (normalized.Contains("vehiclespawner", StringComparison.Ordinal)
            || normalized.Contains("vehiclespawn", StringComparison.Ordinal))
        {
            return "Спавнер транспорта";
        }

        if (normalized.Contains("questgiver", StringComparison.Ordinal))
        {
            return "Источник квестов";
        }

        var stem = Regex.Replace(raw, @"[_\s]*\d+$", string.Empty, RegexOptions.CultureInvariant);
        return CapitalizeFirst(NormalizeLocalizedLabel(LocalizeAssetStem(stem)));
    }

    private static int? TryParseExportIndexFromFieldPath(string? fieldPath)
    {
        if (string.IsNullOrWhiteSpace(fieldPath))
        {
            return null;
        }

        var path = fieldPath.Trim();
        if (!path.StartsWith("e:", StringComparison.OrdinalIgnoreCase))
        {
            return null;
        }

        var slashIndex = path.IndexOf('/');
        var end = slashIndex < 0 ? path.Length : slashIndex;
        var token = path.Substring(2, end - 2);
        return int.TryParse(token, NumberStyles.Integer, CultureInfo.InvariantCulture, out var index)
            ? index
            : null;
    }

    private StudioModAssetSchemaDto BuildSyntheticDataTableRowSchema(
        string assetId,
        string normalizedRelativePath,
        ModCategory category,
        string sourceMode,
        UAsset asset,
        AssetSelection selection,
        List<string> warnings)
    {
        if (!TryGetFirstDataTableExport(asset, out var dataTableExport, out var exportIndex))
        {
            warnings.Add("Не удалось открыть игровую таблицу для анализа.");
            return new StudioModAssetSchemaDto(
                assetId,
                normalizedRelativePath,
                category.Id,
                category.Name,
                sourceMode,
                "uasset",
                [],
                [],
                warnings);
        }

        if (!TryFindDataTableRow(dataTableExport, selection.SyntheticRowName ?? string.Empty, out var row, out var rowIndex))
        {
            warnings.Add("Не удалось найти нужную строку в игровой таблице.");
            return new StudioModAssetSchemaDto(
                assetId,
                normalizedRelativePath,
                category.Id,
                category.Name,
                sourceMode,
                "uasset",
                [],
                [],
                warnings);
        }

        return (selection.SyntheticLaneId ?? string.Empty).ToLowerInvariant() switch
        {
            ItemSpawningParametersLaneId => BuildItemSpawningParametersRowSchema(
                assetId,
                normalizedRelativePath,
                category,
                sourceMode,
                asset,
                exportIndex,
                row,
                rowIndex,
                warnings),
            ItemSpawningCooldownGroupsLaneId => BuildItemSpawningCooldownGroupRowSchema(
                assetId,
                normalizedRelativePath,
                category,
                sourceMode,
                asset,
                exportIndex,
                row,
                rowIndex,
                warnings),
            _ => new StudioModAssetSchemaDto(
                assetId,
                normalizedRelativePath,
                category.Id,
                category.Name,
                sourceMode,
                "uasset",
                [],
                [],
                ["Эта строка таблицы пока не поддерживается в студии."])
        };
    }

    private StudioModAssetSchemaDto BuildItemSpawningParametersRowSchema(
        string assetId,
        string normalizedRelativePath,
        ModCategory category,
        string sourceMode,
        UAsset asset,
        int exportIndex,
        StructPropertyData row,
        int rowIndex,
        List<string> warnings)
    {
        var fields = new List<StudioModFieldDto>(64);
        var listTargets = new List<StudioModListTargetDto>(8);
        var values = row.Value ?? [];
        for (var i = 0; i < values.Count; i++)
        {
            var child = values[i];
            var childName = child.Name?.ToString() ?? GetReadablePropertyName(child, i);
            if (string.Equals(childName, "CooldownGroup", StringComparison.OrdinalIgnoreCase)
                && child is StructPropertyData cooldownGroupStruct)
            {
                AppendItemSpawningCooldownGroupField(fields, cooldownGroupStruct, exportIndex, rowIndex, i);
                continue;
            }

            if (string.Equals(childName, "Variations", StringComparison.OrdinalIgnoreCase)
                && child is ArrayPropertyData variationsArray)
            {
                AppendItemSpawningVariationsListTarget(
                    asset,
                    listTargets,
                    variationsArray,
                    exportIndex,
                    rowIndex,
                    i,
                    normalizedRelativePath);
                continue;
            }

            CollectUassetFields(
                asset,
                child,
                $"e:{exportIndex}/r:{rowIndex}/p:{i}",
                $"Правило спавна {LocalizeItemSpawningRowName(GetDataTableRowName(row))}.{GetReadablePropertyName(child, i)}",
                normalizedRelativePath,
                fields,
                listTargets,
                depth: 0);
        }

        if (fields.Count == 0)
        {
            warnings.Add(ResolveNoSafeFieldWarning(normalizedRelativePath, listTargets.Count > 0));
        }

        return new StudioModAssetSchemaDto(
            assetId,
            normalizedRelativePath,
            category.Id,
            category.Name,
            sourceMode,
            "uasset",
            fields.Take(800).ToList(),
            listTargets.Take(200).ToList(),
            warnings);
    }

    private static void AppendItemSpawningVariationsListTarget(
        UAsset asset,
        List<StudioModListTargetDto> listTargets,
        ArrayPropertyData variationsArray,
        int exportIndex,
        int rowIndex,
        int propertyIndex,
        string relativePath)
    {
        var values = variationsArray.Value ?? [];
        var itemKind = ResolveItemSpawningArrayItemKind(variationsArray, values);
        List<string>? entryLabels = null;
        if (itemKind.Equals("reference", StringComparison.OrdinalIgnoreCase))
        {
            entryLabels = values
                .Select((value, index) => ResolveArrayEntryLabel(asset, relativePath, "Варианты предмета", value, index))
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .ToList();
        }

        listTargets.Add(new StudioModListTargetDto(
            $"e:{exportIndex}/r:{rowIndex}/p:{propertyIndex}",
            "Варианты предмета",
            ResolveListTargetDescription(relativePath, "Варианты предмета"),
            itemKind,
            values.Length,
            SupportsAddClone: false,
            SupportsRemove: values.Length > 0,
            SupportsClear: values.Length > 0,
            SupportsAddEmpty: false,
            SupportsAddReference: itemKind.Equals("reference", StringComparison.OrdinalIgnoreCase),
            ReferencePickerKind: itemKind.Equals("reference", StringComparison.OrdinalIgnoreCase) ? "item-asset" : null,
            ReferencePickerPrompt: itemKind.Equals("reference", StringComparison.OrdinalIgnoreCase)
                ? "Найди предмет, который должен входить в варианты появления для этого правила спавна."
                : null,
            EntryLabels: entryLabels));
    }

    private static string ResolveItemSpawningArrayItemKind(ArrayPropertyData arrayProperty, PropertyData[] values)
    {
        if (values.Length > 0)
        {
            return ResolveUassetArrayItemKind(values);
        }

        var arrayType = arrayProperty.ArrayType?.ToString() ?? string.Empty;
        if (arrayType.Equals("ObjectProperty", StringComparison.OrdinalIgnoreCase)
            || arrayType.Equals("ClassProperty", StringComparison.OrdinalIgnoreCase)
            || arrayType.Equals("SoftObjectProperty", StringComparison.OrdinalIgnoreCase)
            || arrayType.Equals("SoftObjectPathProperty", StringComparison.OrdinalIgnoreCase))
        {
            return "reference";
        }

        return "unknown";
    }

    private StudioModAssetSchemaDto BuildItemSpawningCooldownGroupRowSchema(
        string assetId,
        string normalizedRelativePath,
        ModCategory category,
        string sourceMode,
        UAsset asset,
        int exportIndex,
        StructPropertyData row,
        int rowIndex,
        List<string> warnings)
    {
        var fields = new List<StudioModFieldDto>(24);
        var listTargets = new List<StudioModListTargetDto>(4);
        var values = row.Value ?? [];
        for (var i = 0; i < values.Count; i++)
        {
            var child = values[i];
            if (child is StructPropertyData intervalStruct
                && string.Equals(child.Name?.ToString(), "cooldown", StringComparison.OrdinalIgnoreCase))
            {
                AppendItemSpawningCooldownIntervalFields(fields, intervalStruct, exportIndex, rowIndex, i);
                continue;
            }

            CollectUassetFields(
                asset,
                child,
                $"e:{exportIndex}/r:{rowIndex}/p:{i}",
                $"Группа отката {LocalizeItemSpawningCooldownGroupName(GetDataTableRowName(row))}.{GetReadablePropertyName(child, i)}",
                normalizedRelativePath,
                fields,
                listTargets,
                depth: 0);
        }

        if (fields.Count == 0)
        {
            warnings.Add(ResolveNoSafeFieldWarning(normalizedRelativePath, listTargets.Count > 0));
        }

        return new StudioModAssetSchemaDto(
            assetId,
            normalizedRelativePath,
            category.Id,
            category.Name,
            sourceMode,
            "uasset",
            fields.Take(800).ToList(),
            listTargets.Take(200).ToList(),
            warnings);
    }

    private static void AppendItemSpawningCooldownIntervalFields(
        List<StudioModFieldDto> fields,
        StructPropertyData intervalStruct,
        int exportIndex,
        int rowIndex,
        int propertyIndex)
    {
        var minProperty = FindStructChildProperty<FloatPropertyData>(intervalStruct, "Min", out var minIndex);
        if (minProperty is not null)
        {
            var currentValue = minProperty.Value.ToString(CultureInfo.InvariantCulture);
            fields.Add(new StudioModFieldDto(
                $"e:{exportIndex}/r:{rowIndex}/p:{propertyIndex}/p:{minIndex}",
                "Время отката (минимум)",
                "Минимальная пауза перед тем, как эта группа отката снова разрешит появление предметов.",
                "Откат появления",
                "float",
                "number",
                currentValue,
                true,
                "0",
                "86400",
                null,
                null,
                null,
                currentValue));
        }

        var maxProperty = FindStructChildProperty<FloatPropertyData>(intervalStruct, "Max", out var maxIndex);
        if (maxProperty is not null)
        {
            var currentValue = maxProperty.Value.ToString(CultureInfo.InvariantCulture);
            fields.Add(new StudioModFieldDto(
                $"e:{exportIndex}/r:{rowIndex}/p:{propertyIndex}/p:{maxIndex}",
                "Время отката (максимум)",
                "Максимальная пауза перед тем, как эта группа отката снова разрешит появление предметов.",
                "Откат появления",
                "float",
                "number",
                currentValue,
                true,
                "0",
                "86400",
                null,
                null,
                null,
                currentValue));
        }
    }

    private void AppendItemSpawningCooldownGroupField(
        List<StudioModFieldDto> fields,
        StructPropertyData cooldownGroupStruct,
        int exportIndex,
        int rowIndex,
        int propertyIndex)
    {
        var rowNameProperty = FindStructChildProperty<NamePropertyData>(cooldownGroupStruct, "RowName", out var rowNameIndex);
        if (rowNameProperty is null)
        {
            return;
        }

        var currentValue = rowNameProperty.Value?.ToString();
        if (string.IsNullOrWhiteSpace(currentValue))
        {
            currentValue = "None";
        }

        fields.Add(new StudioModFieldDto(
            $"e:{exportIndex}/r:{rowIndex}/p:{propertyIndex}/p:{rowNameIndex}",
            "Группа отката",
            "Выбери общую группу отката, которая управляет задержкой повторного появления этого предмета. Если группа пустая, предмет работает без общей таблицы отката.",
            "Откат появления",
            "name",
            "select",
            currentValue,
            true,
            null,
            null,
            GetItemSpawningCooldownGroupFieldOptions(),
            null,
            null,
            currentValue.Equals("None", StringComparison.OrdinalIgnoreCase)
                ? "Без группы отката"
                : LocalizeItemSpawningCooldownGroupName(currentValue)));
    }

    private List<StudioModFieldOptionDto> GetItemSpawningCooldownGroupFieldOptions()
    {
        lock (_sync)
        {
            return _itemSpawningCooldownGroupFieldOptionsCache ??= BuildItemSpawningCooldownGroupFieldOptions();
        }
    }

    private List<StudioModFieldOptionDto> BuildItemSpawningCooldownGroupFieldOptions()
    {
        var options = new List<StudioModFieldOptionDto>
        {
            new("None", "Без группы отката")
        };

        if (!TryLoadGameDataTableAsset(ItemSpawningCooldownGroupsTableRelativePath, out _, out var dataTableExport))
        {
            return options;
        }

        foreach (var row in dataTableExport.Table.Data)
        {
            var rowName = row.Name?.ToString()?.Trim();
            if (string.IsNullOrWhiteSpace(rowName))
            {
                continue;
            }

            options.Add(new StudioModFieldOptionDto(
                rowName,
                LocalizeItemSpawningCooldownGroupName(rowName)));
        }

        return options
            .DistinctBy(option => option.Value, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private StudioModAssetSchemaDto BuildCraftingRecipeSchema(
        string assetId,
        string normalizedRelativePath,
        ModCategory category,
        string sourceMode,
        UAsset asset,
        List<string> warnings)
    {
        if (!TryGetCraftingRecipeExport(asset, out var normalExport, out var exportIndex))
        {
            warnings.Add("Не удалось открыть рецепт для анализа.");
            return new StudioModAssetSchemaDto(
                assetId,
                normalizedRelativePath,
                category.Id,
                category.Name,
                sourceMode,
                "uasset",
                [],
                [],
                warnings);
        }

        var fields = new List<StudioModFieldDto>(180);
        var listTargets = new List<StudioModListTargetDto>(8);

        AppendCraftingRecipeMetadataFields(asset, fields);

        var product = FindTopLevelProperty<SoftObjectPropertyData>(normalExport, "Product", out _);
        if (product is not null)
        {
            fields.Add(new StudioModFieldDto(
                $"{RecipeFieldPrefix}product",
                "Что создаётся",
                "Выбери предмет, который игрок получит после успешного крафта.",
                "Результат",
                "soft-object",
                "item-picker",
                ExtractSoftObjectReference(product.Value),
                true,
                null,
                null,
                null));
        }
        else
        {
            warnings.Add("У рецепта не найден итоговый предмет.");
        }

        var productQuantity = FindTopLevelProperty<IntPropertyData>(normalExport, "ProductQuantity", out _);
        fields.Add(new StudioModFieldDto(
            $"{RecipeFieldPrefix}product-quantity",
            "Сколько предметов получается",
            "Сколько готовых предметов выдаёт рецепт за одно создание.",
            "Результат",
            "int",
            "number",
            (productQuantity?.Value ?? 1).ToString(CultureInfo.InvariantCulture),
            true,
            "1",
            "999",
            null));

        var relevantSkill = FindTopLevelProperty<ObjectPropertyData>(normalExport, "RelevantSkill", out _);
        var skillCurrentValue = string.Empty;
        var skillCurrentDisplayValue = string.Empty;
        if (relevantSkill is not null)
        {
            if (!TryExtractObjectReferencePickerValue(asset, relevantSkill.Value, out skillCurrentValue, out skillCurrentDisplayValue))
            {
                skillCurrentDisplayValue = ResolveObjectReferenceLabel(asset, relevantSkill.Value);
            }
        }

        fields.Add(new StudioModFieldDto(
            $"{RecipeFieldPrefix}skill-info",
            "Какой навык влияет на рецепт",
            relevantSkill is null
                ? "Выбери навык, который будет определять скорость, сложность и прокачку этого рецепта. Если поле ещё отсутствует, студия добавит его при сохранении."
                : "Выбери навык, который будет определять скорость, сложность и прокачку этого рецепта.",
            "Навык",
            "object",
            "reference-picker",
            skillCurrentValue,
            true,
            null,
            null,
            null,
            "skill-asset",
            "Найди навык, который должен влиять на этот рецепт, и выбери его из списка.",
            skillCurrentDisplayValue));

        AddRecipePerSkillFloatFields(
            fields,
            FindTopLevelProperty<StructPropertyData>(normalExport, "Duration", out _),
            $"{RecipeFieldPrefix}duration:",
            "Время крафта",
            "Сколько секунд длится создание рецепта на каждом уровне навыка.",
            "Время крафта",
            min: "0",
            max: "3600");

        AddRecipePerSkillFloatFields(
            fields,
            FindTopLevelProperty<StructPropertyData>(normalExport, "ExperienceReward", out _),
            $"{RecipeFieldPrefix}exp:",
            "Опыт за крафт",
            "Сколько опыта получает игрок за успешный крафт.",
            "Награда",
            min: "0",
            max: "5000");

        AddRecipePerSkillFloatFields(
            fields,
            FindTopLevelProperty<StructPropertyData>(normalExport, "FamePointReward", out _),
            $"{RecipeFieldPrefix}fame:",
            "Очки славы за крафт",
            "Сколько очков славы выдаётся за успешный крафт.",
            "Награда",
            min: "0",
            max: "100");

        var ingredients = FindTopLevelProperty<ArrayPropertyData>(normalExport, "Ingredients", out var ingredientsIndex);
        if (ingredients is not null)
        {
            var slots = ingredients.Value ?? [];
            listTargets.Add(new StudioModListTargetDto(
                $"e:{exportIndex}/p:{ingredientsIndex}",
                "Слоты ингредиентов",
                "Добавляй, копируй или убирай слоты ингредиентов, чтобы собрать свой состав рецепта.",
                "ingredient-slot",
                slots.Length,
                SupportsAddClone: slots.Length > 0,
                SupportsRemove: slots.Length > 0,
                SupportsClear: slots.Length > 0,
                SupportsAddEmpty: false));

            for (var i = 0; i < slots.Length; i++)
            {
                if (slots[i] is not StructPropertyData ingredientSlot)
                {
                    continue;
                }

                var section = $"Ингредиент {i + 1}";
                var allowedTypes = FindStructChildProperty<ArrayPropertyData>(ingredientSlot, "AllowedTypes", out _);
                var allowedValues = allowedTypes?.Value ?? [];
                var entryLabels = allowedValues
                    .Select((value, entryIndex) => ResolveArrayEntryLabel(asset, normalizedRelativePath, "Варианты ингредиента", value, entryIndex))
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .ToList();

                listTargets.Add(new StudioModListTargetDto(
                    $"{SyntheticRecipeAllowedTypesTargetPrefix}{exportIndex}:{ingredientsIndex}:{i}",
                    $"{section}: допустимые группы и предметы",
                    "Какие группы ингредиентов или готовые предметы можно положить в этот слот рецепта. Если список пока отсутствует в ассете, студия создаст его сама.",
                    "reference",
                    allowedValues.Length,
                    SupportsAddClone: false,
                    SupportsRemove: allowedValues.Length > 0,
                    SupportsClear: allowedValues.Length > 0,
                    SupportsAddEmpty: false,
                    SupportsAddReference: true,
                    ReferencePickerKind: "crafting-ingredient-asset",
                    ReferencePickerPrompt: "Найди группу или игровой предмет, который должен подходить в этот слот рецепта.",
                    EntryLabels: entryLabels));

                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:allowed-display",
                    "Что подходит в слот",
                    "Справка по этому слоту: какие группы или предметы сюда можно положить.",
                    section,
                    "string",
                    "text",
                    ResolveCraftingAllowedTypesSummary(asset, FindStructChildProperty<ArrayPropertyData>(ingredientSlot, "AllowedTypes", out _)),
                    false,
                    null,
                    null,
                    null));

                var purpose = FindStructChildProperty<EnumPropertyData>(ingredientSlot, "Purpose", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:purpose",
                    "Роль ингредиента",
                    "Определи, это расходный материал или инструмент, который нужен только как условие рецепта. Если настройки ещё нет, студия безопасно добавит её.",
                    section,
                    "enum",
                    "select",
                    purpose?.Value?.ToString() ?? "ECraftingIngredientPurpose::Material",
                    true,
                    null,
                    null,
                    CraftingIngredientPurposeOptions));

                var mixingType = FindStructChildProperty<EnumPropertyData>(ingredientSlot, "MixingType", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:mixing",
                    "Как можно смешивать варианты",
                    "Разрешать ли смешивать разные варианты подходящих предметов в одном слоте рецепта. Если этой настройки нет, студия добавит её сама.",
                    section,
                    "enum",
                    "select",
                    mixingType?.Value?.ToString() ?? "ECraftingIngredientMixingType::NoMixing",
                    true,
                    null,
                    null,
                    CraftingIngredientMixingTypeOptions));

                var consumeWhole = FindStructChildProperty<BoolPropertyData>(ingredientSlot, "ShouldConsumeWhole", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:consume-whole",
                    "Тратить предмет целиком",
                    "Если включено, слот забирает весь предмет, а не только часть его ресурса. Если флага нет, студия создаст его при сохранении.",
                    section,
                    "bool",
                    "toggle",
                    consumeWhole is not null && consumeWhole.Value ? "true" : "false",
                    true,
                    null,
                    null,
                    null));

                var isResource = FindStructChildProperty<BoolPropertyData>(ingredientSlot, "IsResource", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:resource",
                    "Это жидкость или ресурс",
                    "Включай только для воды, топлива и других ресурсных ингредиентов, которые расходуются частями. Если настройки нет, студия добавит её.",
                    section,
                    "bool",
                    "toggle",
                    isResource is not null && isResource.Value ? "true" : "false",
                    true,
                    null,
                    null,
                    null));

                var liters = FindStructChildProperty<FloatPropertyData>(ingredientSlot, "Liters", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:liters",
                    "Сколько литров нужно",
                    "Сколько литров жидкости или ресурса должен содержать этот слот рецепта. Если поля ещё нет, студия создаст его.",
                    section,
                    "float",
                    "number",
                    (liters?.Value ?? 0f).ToString(CultureInfo.InvariantCulture),
                    true,
                    "0",
                    "20",
                    null));

                var nutrientInclusion = FindStructChildProperty<FloatPropertyData>(ingredientSlot, "NutrientInclusionFactor", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:nutrient",
                    "Вклад в питательность",
                    "Какая доля питательных свойств этого ингредиента переносится в готовый результат. Если поля нет, студия безопасно добавит его.",
                    section,
                    "float",
                    "number",
                    (nutrientInclusion?.Value ?? 0f).ToString(CultureInfo.InvariantCulture),
                    true,
                    "0",
                    "5",
                    null));

                AddRecipePerSkillIntFields(
                    fields,
                    FindStructChildProperty<StructPropertyData>(ingredientSlot, "Amount", out _),
                    $"{RecipeFieldPrefix}ingredient:{i}:amount:",
                    "Сколько нужно",
                    "Сколько единиц этого ингредиента нужно для крафта.",
                    section,
                    min: "0",
                    max: "999");

                AddRecipePerSkillIntFields(
                    fields,
                    FindStructChildProperty<StructPropertyData>(ingredientSlot, "AdditionalAmount", out _),
                    $"{RecipeFieldPrefix}ingredient:{i}:additional:",
                    "Дополнительно сверху",
                    "Сколько предметов сверху может потребовать этот слот рецепта.",
                    section,
                    min: "0",
                    max: "999");

                var qualityInfluence = FindStructChildProperty<FloatPropertyData>(ingredientSlot, "ProductQualityInfluence", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:quality",
                    "Влияние на качество результата",
                    "Насколько этот ингредиент влияет на качество готового предмета. Если поля нет, студия добавит его при сохранении.",
                    section,
                    "float",
                    "number",
                    (qualityInfluence?.Value ?? 0f).ToString(CultureInfo.InvariantCulture),
                    true,
                    "0",
                    "5",
                    null));

                var returnOnUncraft = FindStructChildProperty<BoolPropertyData>(ingredientSlot, "ReturnOnUncraft", out _);
                fields.Add(new StudioModFieldDto(
                    $"{RecipeFieldPrefix}ingredient:{i}:return",
                    "Возвращать при разборе",
                    "Нужно ли возвращать этот ингредиент при обратном разборе предмета. Если этой настройки нет, студия создаст её сама.",
                    section,
                    "bool",
                    "toggle",
                    returnOnUncraft is not null && returnOnUncraft.Value ? "true" : "false",
                    true,
                    null,
                    null,
                    null));

                AddRecipePerSkillIntFields(
                    fields,
                    FindStructChildProperty<StructPropertyData>(ingredientSlot, "DamagePercentageOnUncraft", out _),
                    $"{RecipeFieldPrefix}ingredient:{i}:damage:",
                    "Потеря прочности при разборе (%)",
                    "Какой процент прочности теряет этот ингредиент при обратном разборе.",
                    section,
                    min: "0",
                    max: "100");
            }
        }
        else
        {
            warnings.Add("У рецепта не найден список ингредиентов.");
        }

        return new StudioModAssetSchemaDto(
            assetId,
            normalizedRelativePath,
            category.Id,
            category.Name,
            sourceMode,
            "uasset",
            fields,
            listTargets,
            warnings);
    }

    private static void AppendCraftingRecipeMetadataFields(UAsset asset, List<StudioModFieldDto> fields)
    {
        for (var exportIndex = 0; exportIndex < asset.Exports.Count; exportIndex++)
        {
            if (asset.Exports[exportIndex] is not NormalExport normalExport)
            {
                continue;
            }

            var categoryTag = FindTopLevelProperty<StructPropertyData>(
                normalExport,
                "CraftingCategoryTag",
                out var tagPropertyIndex);
            if (categoryTag is null)
            {
                continue;
            }

            var tagName = FindStructChildProperty<NamePropertyData>(categoryTag, "TagName", out var tagNameIndex);
            if (tagName is null)
            {
                continue;
            }

            var currentValue = tagName.Value?.ToString() ?? string.Empty;
            var isPlaceable = currentValue.Contains("BaseBuilding", StringComparison.OrdinalIgnoreCase);
            fields.Add(new StudioModFieldDto(
                $"e:{exportIndex}/p:{tagPropertyIndex}/p:{tagNameIndex}",
                "Категория крафта",
                "В новых версиях SCUM рецепт привязывается к меню крафта через CraftingMetadata рядом с рецептом. Меняй GameplayTag категории здесь, если рецепт должен перейти в другой раздел.",
                "Категория",
                "name",
                "text",
                currentValue,
                true,
                null,
                null,
                null,
                null,
                null,
                ResolveCraftingUiCategoryLabel(currentValue, isPlaceable)));
        }
    }

    private StudioModAssetSchemaDto BuildCraftingUiDataSchema(
        string assetId,
        string normalizedRelativePath,
        ModCategory category,
        string sourceMode,
        UAsset asset,
        List<string> warnings)
    {
        if (!TryGetFirstNormalExport(asset, out var normalExport, out var exportIndex))
        {
            warnings.Add("Не удалось открыть реестр крафта для анализа.");
            return new StudioModAssetSchemaDto(
                assetId,
                normalizedRelativePath,
                category.Id,
                category.Name,
                sourceMode,
                "uasset",
                [],
                [],
                warnings);
        }

        var fields = new List<StudioModFieldDto>(8);
        var listTargets = new List<StudioModListTargetDto>(64);

        var categoryNames = FindTopLevelProperty<MapPropertyData>(normalExport, "CategoryNames", out _);
        var itemCategories = FindTopLevelProperty<ArrayPropertyData>(normalExport, "ItemCategories", out var itemCategoriesIndex);
        var placeableCategories = FindTopLevelProperty<ArrayPropertyData>(normalExport, "PlaceableCategories", out var placeableCategoriesIndex);
        var itemCategoryOrder = FindTopLevelProperty<ArrayPropertyData>(normalExport, "ItemCategoryOrder", out var itemCategoryOrderIndex);
        var placeableCategoryOrder = FindTopLevelProperty<ArrayPropertyData>(normalExport, "PlaceableCategoryOrder", out var placeableCategoryOrderIndex);
        var domainOrder = FindTopLevelProperty<ArrayPropertyData>(normalExport, "DomainOrder", out _);

        fields.Add(new StudioModFieldDto(
            "crafting-registry:item-categories",
            "Категорий предметного крафта",
            "Сколько категорий предметов использует меню крафта.",
            "Обзор",
            "int",
            "text",
            ((itemCategories?.Value ?? itemCategoryOrder?.Value ?? []).Length).ToString(CultureInfo.InvariantCulture),
            false,
            null,
            null,
            null));

        fields.Add(new StudioModFieldDto(
            "crafting-registry:placeable-categories",
            "Категорий строительства",
            "Сколько категорий строительства и базы использует меню крафта.",
            "Обзор",
            "int",
            "text",
            ((placeableCategories?.Value ?? placeableCategoryOrder?.Value ?? []).Length).ToString(CultureInfo.InvariantCulture),
            false,
            null,
            null,
            null));

        if (categoryNames is not null)
        {
            fields.Add(new StudioModFieldDto(
                "crafting-registry:category-names",
                "Локализованных названий категорий",
                "Сколько GameplayTag категорий связано с текстовыми ключами названий.",
                "Обзор",
                "int",
                "text",
                categoryNames.Value.Count.ToString(CultureInfo.InvariantCulture),
                false,
                null,
                null,
                null));
        }

        if (domainOrder is not null)
        {
            fields.Add(new StudioModFieldDto(
                "crafting-registry:domain-order",
                "Доменов крафта",
                "Сколько доменов меню крафта описано в текущем реестре.",
                "Обзор",
                "int",
                "text",
                (domainOrder.Value?.Length ?? 0).ToString(CultureInfo.InvariantCulture),
                false,
                null,
                null,
                null));
        }

        if (itemCategories is not null)
        {
            AppendCraftingUiCategoryRecipeTargets(
                asset,
                normalizedRelativePath,
                exportIndex,
                itemCategories,
                itemCategoriesIndex,
                isPlaceable: false,
                listTargets);
        }

        if (placeableCategories is not null)
        {
            AppendCraftingUiCategoryRecipeTargets(
                asset,
                normalizedRelativePath,
                exportIndex,
                placeableCategories,
                placeableCategoriesIndex,
                isPlaceable: true,
                listTargets);
        }

        if (itemCategoryOrder is not null)
        {
            AppendCraftingUiCategoryOrderTarget(
                itemCategoryOrder,
                itemCategoryOrderIndex,
                exportIndex,
                "Порядок категорий предметов",
                "Какие категории предметного крафта и в каком порядке отображаются в меню. В новых версиях SCUM сами рецепты привязываются к категориям через CraftingMetadata в recipe-asset.",
                isPlaceable: false,
                listTargets);
        }

        if (placeableCategoryOrder is not null)
        {
            AppendCraftingUiCategoryOrderTarget(
                placeableCategoryOrder,
                placeableCategoryOrderIndex,
                exportIndex,
                "Порядок категорий строительства",
                "Какие категории строительства и в каком порядке отображаются в меню. В новых версиях SCUM сами рецепты привязываются к категориям через CraftingMetadata в recipe-asset.",
                isPlaceable: true,
                listTargets);
        }

        if (listTargets.Count == 0 && (itemCategories is not null || placeableCategories is not null))
        {
            warnings.Add("В реестре крафта не найдены категории с массивами рецептов.");
        }

        return new StudioModAssetSchemaDto(
            assetId,
            normalizedRelativePath,
            category.Id,
            category.Name,
            sourceMode,
            "uasset",
            fields,
            listTargets,
            warnings);
    }

    private static void AppendCraftingUiCategoryOrderTarget(
        ArrayPropertyData categories,
        int categoriesPropertyIndex,
        int exportIndex,
        string label,
        string description,
        bool isPlaceable,
        List<StudioModListTargetDto> output)
    {
        var categoryValues = categories.Value ?? [];
        var entryLabels = categoryValues
            .OfType<StructPropertyData>()
            .Select(value => ResolveCraftingUiCategoryLabel(ResolveGameplayTagStructValue(value), isPlaceable))
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .ToList();

        output.Add(new StudioModListTargetDto(
            $"e:{exportIndex}/p:{categoriesPropertyIndex}",
            label,
            description,
            "struct",
            categoryValues.Length,
            SupportsAddClone: categoryValues.Length > 0,
            SupportsRemove: categoryValues.Length > 0,
            SupportsClear: categoryValues.Length > 0,
            SupportsAddEmpty: false,
            SupportsAddReference: false,
            ReferencePickerKind: null,
            ReferencePickerPrompt: null,
            EntryLabels: entryLabels));
    }

    private void AppendCraftingUiCategoryRecipeTargets(
        UAsset asset,
        string normalizedRelativePath,
        int exportIndex,
        ArrayPropertyData categories,
        int categoriesPropertyIndex,
        bool isPlaceable,
        List<StudioModListTargetDto> output)
    {
        var categoryValues = categories.Value ?? [];
        for (var i = 0; i < categoryValues.Length; i++)
        {
            if (categoryValues[i] is not StructPropertyData categoryStruct)
            {
                continue;
            }

            var tagStruct = FindStructChildProperty<StructPropertyData>(categoryStruct, "Tag", out _);
            var tagValue = ResolveGameplayTagStructValue(tagStruct);
            var categoryLabel = ResolveCraftingUiCategoryLabel(tagValue, isPlaceable);
            var recipes = EnsureStructObjectArrayChild(asset, categoryStruct, "Recipes");
            var recipeValues = recipes.Value ?? [];
            var entryLabels = recipeValues
                .Select((value, entryIndex) => ResolveArrayEntryLabel(asset, normalizedRelativePath, "Рецепты категории", value, entryIndex))
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .ToList();
            var pickerKind = isPlaceable
                ? "crafting-placeable-recipe-asset"
                : "crafting-item-recipe-asset";

            output.Add(new StudioModListTargetDto(
                $"{SyntheticCraftingUiCategoryRecipesTargetPrefix}{exportIndex}:{categoriesPropertyIndex}:{i}",
                $"Общий пул крафта: {categoryLabel}",
                "Какие рецепты входят в эту категорию меню крафта. Добавляй новые рецепты из игры или убирай лишние без ручного редактирования внутренних структур.",
                "reference",
                recipeValues.Length,
                SupportsAddClone: false,
                SupportsRemove: recipeValues.Length > 0,
                SupportsClear: recipeValues.Length > 0,
                SupportsAddEmpty: false,
                SupportsAddReference: true,
                ReferencePickerKind: pickerKind,
                ReferencePickerPrompt: isPlaceable
                    ? "Найди рецепт строительства, который должен появиться в этой категории."
                    : "Найди рецепт предмета, который должен появиться в этой категории.",
                EntryLabels: entryLabels));
        }
    }

    private static string ResolveGameplayTagStructValue(StructPropertyData? tagStruct)
    {
        if (tagStruct is null)
        {
            return string.Empty;
        }

        var nameProperty = tagStruct.Value
            .OfType<NamePropertyData>()
            .FirstOrDefault(property => string.Equals(property.Name?.ToString(), "TagName", StringComparison.OrdinalIgnoreCase));
        return nameProperty?.Value?.ToString() ?? string.Empty;
    }

    private static string ResolveCraftingUiCategoryLabel(string tagValue, bool isPlaceable)
    {
        if (string.IsNullOrWhiteSpace(tagValue))
        {
            return isPlaceable ? "Категория строительства" : "Категория предметов";
        }

        var normalized = tagValue.StartsWith("CraftingCategory.", StringComparison.OrdinalIgnoreCase)
            ? tagValue["CraftingCategory.".Length..]
            : tagValue;
        var parts = normalized.Split('.', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (parts.Length == 0)
        {
            return isPlaceable ? "Категория строительства" : "Категория предметов";
        }

        var localizedParts = new List<string>(parts.Length);
        foreach (var part in parts)
        {
            var localized = ResolveCraftingUiCategoryTokenLabel(part);
            if (string.IsNullOrWhiteSpace(localized))
            {
                continue;
            }

            localizedParts.Add(localized);
        }

        if (localizedParts.Count == 0)
        {
            return isPlaceable ? "Категория строительства" : "Категория предметов";
        }

        return string.Join(" / ", localizedParts);
    }

    private static string ResolveCraftingUiCategoryTokenLabel(string token)
    {
        return token switch
        {
            "Items" => "Предметы",
            "Placeables" => "Постройки",
            "BaseBuilding" => "База",
            "Ammunition" => "Боеприпасы",
            "Bullets" => "Пули",
            "ArrowsAndBolts" => "Стрелы и болты",
            "MeleeWeapons" => "Ближний бой",
            "RangedWeapons" => "Дальний бой",
            "Firearms" => "Огнестрел",
            "Attachments" => "Обвес и крепления",
            "BowsAndCrossbows" => "Луки и арбалеты",
            "Explosives" => "Взрывчатка",
            "Clothing" => "Одежда",
            "Equipment" => "Снаряжение",
            "GeneralBuildingElements" => "Общие элементы",
            "OutdoorElements" => "Уличные элементы",
            "Furniture" => "Мебель",
            "Utility" => "Служебные объекты",
            "Storage" => "Хранилища",
            "Lights" => "Освещение",
            "Defenses" => "Оборона",
            "Traps" => "Ловушки",
            "Flags" => "Флаги",
            "Favorites" => "Избранное",
            _ => LocalizeAssetStem(token)
        };
    }

    private StudioModAssetSchemaDto BuildStarterSpawnEquipmentSchema(
        string assetId,
        string normalizedRelativePath,
        ModCategory category,
        string sourceMode,
        UAsset asset,
        List<string> warnings)
    {
        if (!TryGetFirstNormalExport(asset, out var normalExport, out var exportIndex))
        {
            warnings.Add("Не удалось открыть стартовый предмет для анализа.");
            return new StudioModAssetSchemaDto(
                assetId,
                normalizedRelativePath,
                category.Id,
                category.Name,
                sourceMode,
                "uasset",
                [],
                [],
                warnings);
        }

        var fields = new List<StudioModFieldDto>(24);

        var itemClass = FindTopLevelProperty<SoftObjectPropertyData>(normalExport, "ItemClass", out _);
        if (itemClass is null)
        {
            warnings.Add("У стартового предмета не найдено поле выдаваемого предмета. При сохранении студия создаст его заново.");
        }

        fields.Add(new StudioModFieldDto(
            $"{StarterSpawnFieldPrefix}item",
            "Какой предмет выдавать",
            "Выбери предмет, который попадёт игроку в стартовый набор.",
            "Стартовый предмет",
            "soft-object",
            "item-picker",
            itemClass is null ? string.Empty : ExtractSoftObjectReference(itemClass.Value),
            true,
            null,
            null,
            null));

        var equipType = FindTopLevelProperty<EnumPropertyData>(normalExport, "EquipType", out _);
        if (equipType is null)
        {
            warnings.Add("У стартового предмета не найдено поле места выдачи. При сохранении студия создаст его заново.");
        }

        var equipValue = equipType?.Value?.ToString();
        if (string.IsNullOrWhiteSpace(equipValue))
        {
            equipValue = "EPrisonerItemEquipType::Inventory";
        }

        fields.Add(new StudioModFieldDto(
            $"{StarterSpawnFieldPrefix}equip",
            "Куда положить предмет",
            "Определи, где у персонажа появится этот предмет при старте.",
            "Стартовый предмет",
            "enum",
            "select",
            equipValue,
            true,
            null,
            null,
            StarterEquipOptions));

        var biomeRequirement = FindTopLevelProperty<EnumPropertyData>(normalExport, "BiomeRequriment", out _)
            ?? FindTopLevelProperty<EnumPropertyData>(normalExport, "BiomeRequirement", out _);
        if (biomeRequirement is null)
        {
            warnings.Add("У стартового предмета не найдено поле ограничения по биому. При сохранении студия создаст его заново.");
        }

        var biomeValue = biomeRequirement?.Value?.ToString();
        if (string.IsNullOrWhiteSpace(biomeValue))
        {
            biomeValue = "EBiomeType::None";
        }

        fields.Add(new StudioModFieldDto(
            $"{StarterSpawnFieldPrefix}biome",
            "Ограничение по биому",
            "Если нужно, предмет будет выдаваться только для выбранного биома старта.",
            "Условия выдачи",
            "enum",
            "select",
            biomeValue,
            true,
            null,
            null,
            StarterBiomeOptions));

        var conditionProperty = FindTopLevelProperty<StructPropertyData>(normalExport, "Condition", out _);
        var parsedCondition = new StarterSpawnConditionModel();
        string? parseWarning = null;
        var parsedConditionOk = conditionProperty is not null
            && TryParseStarterSpawnCondition(conditionProperty, out parsedCondition, out parseWarning);
        var conditionModel = parsedConditionOk
            ? parsedCondition
            : new StarterSpawnConditionModel();

        if (!string.IsNullOrWhiteSpace(parseWarning))
        {
            warnings.Add(parseWarning);
        }

        var conditionEditable = conditionProperty is null || conditionModel.SupportsSafeRewrite;
        if (conditionProperty is null)
        {
            warnings.Add("У стартового предмета нет отдельного блока условий. Если ты задашь ограничения ниже, студия создаст их автоматически.");
        }
        else if (!conditionEditable)
        {
            warnings.Add("Условия выдачи у этого стартового предмета используют нестандартную схему. Их можно просмотреть, но изменять в студии сейчас нельзя.");
        }

        warnings.Add("Для каждого типа персонажа можно отдельно указать: разрешить, запретить или не добавлять отдельное правило.");

        foreach (var flag in StarterSpawnFlags)
        {
            var currentValue = "ignore";
            if (conditionModel.RequiredTags.Contains(flag.Tag))
            {
                currentValue = "require";
            }
            else if (conditionModel.ForbiddenTags.Contains(flag.Tag))
            {
                currentValue = "exclude";
            }

            fields.Add(new StudioModFieldDto(
                $"{StarterSpawnFieldPrefix}flag:{flag.Key}",
                flag.Label,
                flag.Description,
                "Условия выдачи",
                "enum",
                "select",
                currentValue,
                conditionEditable,
                null,
                null,
                StarterConditionModeOptions));
        }

        foreach (var character in StarterSpawnCharacters)
        {
            var currentValue = "ignore";
            if (conditionModel.AnyTags.Contains(character.Tag))
            {
                currentValue = "allow";
            }
            else if (conditionModel.ForbiddenTags.Contains(character.Tag))
            {
                currentValue = "exclude";
            }

            fields.Add(new StudioModFieldDto(
                $"{StarterSpawnFieldPrefix}character:{character.Key}",
                character.Label,
                "Разреши, запрети или вообще не указывай это правило для выбранного типа персонажа.",
                "Типы персонажей",
                "enum",
                "select",
                currentValue,
                conditionEditable,
                null,
                null,
                StarterCharacterModeOptions));
        }

        return new StudioModAssetSchemaDto(
            assetId,
            normalizedRelativePath,
            category.Id,
            category.Name,
            sourceMode,
            "uasset",
            fields,
            [],
            warnings.Distinct(StringComparer.OrdinalIgnoreCase).ToList());
    }

