    private static bool ShouldExposeSafeField(string relativePath, string userLabel, string valueType)
    {
        if (string.IsNullOrWhiteSpace(userLabel))
        {
            return false;
        }

        if (userLabel.Length > 160)
        {
            return false;
        }

        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();

        if (IsVisualReferenceFieldCandidate(relativePath, userLabel, valueType))
        {
            return true;
        }

        if (path.Contains("/items/", StringComparison.Ordinal)
            && IsItemSpawnerParticipationLabel(label))
        {
            return true;
        }

        if ((path.Contains("/encounters/", StringComparison.Ordinal)
                || path.Contains("/npcs/", StringComparison.Ordinal))
            && IsEncounterSpawnAmountCurveLabel(label))
        {
            return true;
        }

        if (path.Contains("/economy/", StringComparison.Ordinal)
            && IsEconomyCurveLabel(label))
        {
            return true;
        }

        if (path.Contains("/economy/", StringComparison.Ordinal)
            && IsEconomyCurrencyDescriptionLabel(label))
        {
            return true;
        }

        if (path.Contains("/economy/", StringComparison.Ordinal)
            && IsEconomyBankCardLabel(label))
        {
            return true;
        }

        if (path.Contains("/items/", StringComparison.Ordinal)
            && (IsItemHandsCorrectionsLabel(label)
                || IsItemFirstPersonAnimationsLabel(label)
                || IsItemAttachmentSocketMountTypeLabel(label)
                || IsItemAttachmentSocketOffsetLabel(label)
                || IsItemGripSocketNameLabel(label)
                || IsItemWeaponHandIkToggleLabel(label)))
        {
            return true;
        }

        var technicalNoiseTokens = new[]
        {
            "icon", "ico", "image", "brush", "texture", "material", "mesh", "skeletal",
            "sound", "audio", "anim", "widget", "sprite", "atlas", "thumbnail", "font",
            "padding", "margin", "alignment", "offset", "shadow", "color", "opacity",
            "pre infinity", "post infinity", "extrap", "default значение", "default value"
        };

        if (technicalNoiseTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        var hardBlockedTechnicalTokens = new[]
        {
            "draw distance", "дистанция отображения", "ignored by spawners", "игнорируется спавнерами",
            "не использовать для спавна в мире", "socket", "сокет",
            "mesh slice", "части 3d-модели", "override materials", "переопределение материалов",
            "asset user data", "query token stream", "token stream version",
            "net update frequency", "частота обновления сети",
            "служебный поток условий", "служебная версия потока условий",
            "post process settings", "ambient occlusion",
            "дальность отображения (lod)", "ld максимум draw", "ld maximum draw",
            "primary actor tick", "primary component tick", "tick интервал", "b start with tick enabled",
            "replicate physics", "body instance", "collision responses", "component template",
            "component class", "root component", "inheritable component handler", "simple construction script",
            "uber graph function", "mass in kg", "b override mass"
        };

        if (hardBlockedTechnicalTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        if (path.Contains("/items/", StringComparison.Ordinal)
            && (IsCommonItemSafeFieldLabel(label) || IsFuelPoweredItemSafeFieldLabel(label)))
        {
            return true;
        }

        if (IsFishingGameplaySurface(relativePath))
        {
            return ShouldExposeFishingSafeField(relativePath, userLabel, valueType);
        }

        if (IsCookingGameplaySurface(relativePath))
        {
            return ShouldExposeCookingSafeField(relativePath, userLabel, valueType);
        }

        if (IsHuntingGameplaySurface(relativePath))
        {
            return ShouldExposeHuntingSafeField(relativePath, userLabel, valueType);
        }

        if (IsWeatherGameplaySurface(relativePath))
        {
            return ShouldExposeWeatherSafeField(relativePath, userLabel, valueType);
        }

        if (IsMapGameplayAsset(relativePath))
        {
            if (IsMapTechnicalLabel(label))
            {
                return false;
            }

            var blockedMapFieldTokens = new[]
            {
                "override", "spawner preset / узлы", "spawner preset / items",
                "spawner preset / subpresets", "spawner preset / fixed items",
                "spawner preset / post", "spawner preset /", "draw distance", "cull distance"
            };
            if (blockedMapFieldTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            if ((label.Contains(" / spawner / ", StringComparison.OrdinalIgnoreCase)
                 || label.Contains(" spawner / ", StringComparison.OrdinalIgnoreCase))
                && (label.Contains("always spawn", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("probability", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("use item zone", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("use item rarity", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("use item spawn group", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("ammo count", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("stack amount", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("damage", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("dirtiness", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("расход за крафт", StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            if ((label.Contains("метки торговца", StringComparison.OrdinalIgnoreCase)
                 || label.Contains("точка спавна транспорта", StringComparison.OrdinalIgnoreCase))
                && (label.Contains("scale 3 d", StringComparison.OrdinalIgnoreCase)
                    || label.Contains("масштаб", StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            var allowedMapTokens = new[]
            {
                "робот", "sentry", "mech", "спавн", "spawn", "spawner", "маршрут", "waypoint", "patrol",
                "точка", "координат", "поворот", "масштаб зоны", "радиус", "лимит",
                "respawn", "перезапуск", "npc", "транспорт", "vehicle", "quest giver", "квест",
                "trader", "торгов", "relevancy", "активность", "проверять позицию спавна лучом",
                "профиль торговца", "класс сидячего npc", "точка появления npc", "точка маршрута робота"
            };
            var hasAllowedToken = allowedMapTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
            if (!hasAllowedToken)
            {
                return false;
            }

            if (valueType is "string" or "text" or "name" or "enum")
            {
                var allowedStringTokens = new[] { "тип", "класс", "state", "режим", "tag", "тег" };
                return allowedStringTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
            }

            return true;
        }

        if (path.Contains("/items/crafting/recipes/", StringComparison.Ordinal))
        {
            var blockedCraftTokens = new[]
            {
                "ручное название варианта", "название варианта", "audio", "sound", "caption"
            };
            if (blockedCraftTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
            {
                return false;
            }

            var allowedCraftTokens = new[]
            {
                "что создаётся", "ингредиент", "подходящий предмет", "варианты ингредиента",
                "время", "опыт за крафт", "очки славы за крафт", "дополнительный расход",
                "расход за крафт", "влияние на качество результата", "роль ингредиента",
                "как можно смешивать варианты", "возврат при разборе", "повреждение при разборе",
                "тратить предмет целиком", "это жидкость или ресурс", "литры", "питательност",
                "когда начинается эта ступень", "насколько сильно действует эта ступень"
            };

            return allowedCraftTokens.Any(token => label.Contains(token, StringComparison.Ordinal));
        }

        if (path.Contains("/data/spawnequipment/", StringComparison.Ordinal))
        {
            return label.Contains("выдаваемый предмет", StringComparison.Ordinal);
        }

        if (path.Contains("/characters/spawnerpresets/fishspeciespresets/", StringComparison.Ordinal))
        {
            var allowedFishTokens = new[]
            {
                "вид рыбы", "вес появления"
            };

            return allowedFishTokens.Any(token => label.Contains(token, StringComparison.Ordinal));
        }

        if (IsWorldEventManagerAsset(relativePath))
        {
            var allowedWorldEventManagerTokens = new[]
            {
                "пул мировых ивентов",
                "пауза между ивентами (минимум, сек)",
                "пауза между ивентами (максимум, сек)"
