            if (valueType is "string" or "text" or "name" or "enum")
            {
                var allowedStringTokens = new[]
                {
                    "тип", "type", "катег", "category", "качество готовки", "готовность еды",
                    "ингредиент", "вариант ингредиента", "предмет", "результат",
                    "тратить предмет целиком", "включено"
                };
                return allowedStringTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
            }

            return allowedRecipeTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
        }

        return false;
    }

    private static bool IsHuntingGameplaySurface(string relativePath)
    {
        var path = relativePath.ToLowerInvariant();
        if (!path.Contains("/hunting/", StringComparison.Ordinal)
            || path.Contains("/hunting/clues/clue_meshes/", StringComparison.Ordinal))
        {
            return false;
        }

        var fileName = Path.GetFileNameWithoutExtension(path);
        return path.Contains("/hunting/biomedata/", StringComparison.Ordinal)
            || (path.Contains("/hunting/clues/", StringComparison.Ordinal)
                && fileName.StartsWith("bp_huntingclue", StringComparison.OrdinalIgnoreCase));
    }

    private static bool ShouldExposeHuntingSafeField(string relativePath, string userLabel, string valueType)
    {
        if (string.IsNullOrWhiteSpace(userLabel))
        {
            return false;
        }

        var path = relativePath.ToLowerInvariant();
        var label = userLabel.ToLowerInvariant();

        var blockedTokens = new[]
        {
            "mesh", "модель", "material", "материал", "texture", "текстур", "icon", "икон",
            "decal", "декал", "visual", "визуал", "static mesh", "skeletal",
            "relative location", "relative rotation", "relative scale", "scale 3 d",
            "translation", "rotation", "transform", "component", "collision", "socket", "сокет",
            "primary actor tick", "tick", "replicate", "replicated", "net cull", "net update",
            "draw distance", "cull distance", "asset user data", "root component", "mobility",
            "first clue visuals", "clue visuals"
        };
        if (blockedTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase)))
        {
            return false;
        }

        if (path.Contains("/hunting/biomedata/", StringComparison.Ordinal))
        {
            var allowedBiomeTokens = new[]
            {
                "дистанция до следующего следа",
                "количество следов",
                "размер группы животных",
                "угол разброса следующего следа",
                "вес появления",
                "next clue",
                "num clues",
                "pack size",
                "herd size",
                "spawn weight"
            };

            return allowedBiomeTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
        }

        if (path.Contains("/hunting/clues/", StringComparison.Ordinal))
        {
            var allowedClueTokens = new[]
            {
                "дистанция слышимости",
                "минимальная дистанция видимости",
                "время исчезновения",
                "жизнь после исчезновения",
                "hearing distance",
                "apparent distance",
                "fade time",
                "lifetime after fade out"
            };

            return allowedClueTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
        }

        return false;
    }

    private static bool IsWeatherGameplaySurface(string relativePath)
    {
        return relativePath.Contains("/weather/curves/", StringComparison.OrdinalIgnoreCase);
    }

    private static bool ShouldExposeWeatherSafeField(string relativePath, string userLabel, string valueType)
    {
        var label = userLabel.ToLowerInvariant();
        return label.Contains("точки кривой", StringComparison.Ordinal)
            || label.Contains("положение точки кривой", StringComparison.Ordinal)
            || label.Contains("значение точки кривой", StringComparison.Ordinal)
            || label.Contains("когда начинается эта ступень", StringComparison.Ordinal)
            || label.Contains("насколько сильно действует эта ступень", StringComparison.Ordinal);
    }

    private static bool IsVisualReferenceFieldCandidate(string relativePath, string userLabel, string valueType)
    {
        if (!IsReferenceValueType(valueType))
        {
            return false;
        }

        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();
        var hardBlockTokens = new[]
        {
            "draw distance", "дистанция отображения", "ignored by spawners", "игнорируется спавнерами",
            "не использовать для спавна в мире", "socket", "сокет",
            "mesh slice condition", "условие части 3d-модели",
            "asset user data", "query token stream", "token stream version",
            "net update frequency", "частота обновления сети",
            "служебный поток условий", "служебная версия потока условий",
            "дальность отображения (lod)", "ld максимум draw", "ld maximum draw",
            "animation", "анимац", "curve", "кривая", "atlas", "sprite"
        };
        if (hardBlockTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        var supportedPath = IsVisualReferenceSurfacePath(relativePath);
        if (!supportedPath || path.Contains("/ui/", StringComparison.Ordinal))
        {
            return false;
        }

        return IsVisualModelLabel(label) || IsVisualMaterialLabel(label) || IsVisualTextureLabel(label);
    }

    private static bool IsVisualReferenceSurfacePath(string relativePath)
    {
        return IsGameplayVisualAssetPath(relativePath);
    }

    private static bool ShouldExposeReferenceInfoField(string relativePath, string userLabel)
    {
        if (string.IsNullOrWhiteSpace(userLabel))
        {
            return false;
        }

        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();
        if (path.Contains("/items/fishing/", StringComparison.Ordinal))
        {
            return false;
        }

        if (path.Contains("/skills/", StringComparison.Ordinal)
            && (label.Contains("curve", StringComparison.Ordinal)
                || label.Contains("кривая", StringComparison.Ordinal)))
        {
            return false;
        }

        if (label.Contains("ui data", StringComparison.Ordinal)
            || label.Contains("данные интерфейса", StringComparison.Ordinal)
            || path.Contains("/ui/", StringComparison.Ordinal))
        {
            return false;
        }

        var usefulTokens = new[]
        {
            "симптом", "вещество", "вещества", "навык", "предмет", "предметы", "патрон", "награда", "награды"
        };

        return usefulTokens.Any(token => label.Contains(token, StringComparison.Ordinal));
    }

    private static bool ShouldExposeListTarget(string relativePath, string userLabel)
    {
        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();

        if (IsCookingGameplaySurface(relativePath))
        {
            return ShouldExposeCookingListTarget(relativePath, userLabel);
        }

        if (IsHuntingGameplaySurface(relativePath))
        {
            return false;
        }

        if (IsWeatherGameplaySurface(relativePath))
        {
            return IsStandaloneGameplayCurvePointsSurface(relativePath, userLabel);
        }

        var blockedTokens = new[]
        {
            "tag dictionary", "query token", "asset user data", "root nodes", "all nodes",
            "action sequence", "attachment sockets", "supported firing modes", "items",
            "mesh slices", "socket overrides", "override materials", "сокет", "сокеты",
            "переопределение материалов", "переопределение сокетов", "части 3d-модели", "части 3d модели",
            "корневые узлы", "все узлы"
        };

        var allowQuestItemTargets = path.Contains("/quests/", StringComparison.Ordinal)
            && (label.Contains("нужно держать рядом", StringComparison.Ordinal)
                || label.Contains("подходящие предметы", StringComparison.Ordinal)
                || (label.Contains("item экипировать", StringComparison.Ordinal) && label.Contains("items", StringComparison.Ordinal)));
        if (!allowQuestItemTargets && blockedTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        if (path.Contains("/data/spawnequipment/", StringComparison.Ordinal))
        {
            return false;
        }

        if (path.Contains("/items/fishing/", StringComparison.Ordinal))
        {
            return IsFishingBaitChanceListSurface(relativePath, userLabel);
        }

        if (IsMapGameplayAsset(relativePath))
        {
            if (IsMapTechnicalLabel(label))
            {
                return false;
            }

            var blockedNestedTokens = new[]
            {
                "узлы", "nodes", "subpresets", "fixed items", "post появление actions", "post spawn actions", "spawner preset /", "spawner preset"
            };
            if (blockedNestedTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            if (label.Equals("точки спавна в группе", StringComparison.OrdinalIgnoreCase)
                || label.Equals("spawner markers", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (label.Contains("пресеты лута", StringComparison.OrdinalIgnoreCase)
                || label.Contains("item classes", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (label.Contains("маршрут", StringComparison.OrdinalIgnoreCase)
                || label.Contains("waypoint", StringComparison.OrdinalIgnoreCase)
                || label.Contains("patrol", StringComparison.OrdinalIgnoreCase)
                || label.Contains("spawn points", StringComparison.OrdinalIgnoreCase)
                || label.Contains("vehicle spawn", StringComparison.OrdinalIgnoreCase)
                || label.Contains("торгов", StringComparison.OrdinalIgnoreCase)
                || label.Contains("trader", StringComparison.OrdinalIgnoreCase)
                || label.Contains("quest giver", StringComparison.OrdinalIgnoreCase)
                || label.Contains("npc interaction", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            return false;
        }

        if (IsCargoDropContainerAsset(relativePath))
        {
            return IsCargoDropMajorSpawnerOptionsSurface(relativePath, userLabel)
                || IsCargoDropMajorSpawnerPresetOptionsSurface(relativePath, userLabel);
        }

        if (IsCargoDropWorldEventAsset(relativePath))
        {
            return IsCargoDropEncounterVariantsSurface(relativePath, userLabel)
                || IsCargoDropContainerClassListSurface(relativePath, userLabel);
        }

        if (path.Contains("/items/spawnerpresets/examine_data_presets/", StringComparison.Ordinal))
        {
            return IsExamineDataPresetItemListSurface(relativePath, userLabel);
        }

        if (IsCargoDropPackagePresetAsset(relativePath))
        {
            return IsAdvancedItemSpawnerPresetItemListSurface(relativePath, userLabel);
        }

        if (IsAdvancedItemSpawnerPresetAsset(relativePath))
        {
            return IsAdvancedItemSpawnerPresetItemListSurface(relativePath, userLabel)
                || IsAdvancedItemSpawnerPresetSubpresetListSurface(relativePath, userLabel);
        }

        if (IsRegularItemSpawnerPresetAsset(relativePath))
        {
            return IsRegularItemSpawnerPresetItemListSurface(relativePath, userLabel);
        }

        if (path.Contains("/data/tables/items/spawning/", StringComparison.Ordinal))
        {
            return IsItemSpawningVariationListSurface(relativePath, userLabel);
        }

        if (path.Contains("/ui/gameevents/itemselection/", StringComparison.Ordinal))
        {
            return label.Contains("дополнительные предметы", StringComparison.Ordinal)
                || label.Contains("крепления", StringComparison.Ordinal);
        }

        if (IsStandaloneGameplayCurvePointsSurface(relativePath, userLabel))
        {
            return true;
        }

        if (IsGameEventMarkerAsset(relativePath))
        {
            return IsGameEventLoadoutListLabel(userLabel);
        }

        if (IsVehicleSpawnGroupAsset(relativePath))
        {
            return IsVehicleSpawnPresetListSurface(relativePath, userLabel);
        }

        if (path.Contains("/items/weapons/", StringComparison.Ordinal))
        {
            return false;
        }

        if (path.Contains("/skills/", StringComparison.Ordinal))
        {
            return label.Contains("точки кривой", StringComparison.Ordinal);
        }

        if (path.Contains("/quests/", StringComparison.Ordinal))
        {
            var blockedQuestTokens = new[]
            {
                "служебный поток условий", "query token stream",
                "служебная версия потока условий", "token stream version"
            };
            if (blockedQuestTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
            {
                return false;
            }

            if (IsQuestRewardVariantsLabel(relativePath, userLabel)
                || IsQuestRewardSkillExperienceLabel(relativePath, userLabel))
            {
                return true;
            }

            var allowedQuestTokens = new[]
            {
                "настройки источников квестов", "quest givers setup",
                "специальные наборы квестов", "special quest sets",
                "варианты награды", "possible rewards",
                "опыт навыков за квест", "reward skill experience",
                "нужно держать рядом", "must be in vicinity",
                "подходящие предметы", "accepted items",
                "подходящие рецепты", "accepted recipes"
            };

            return allowedQuestTokens.Any(token => label.Contains(token, StringComparison.Ordinal));
        }

        if (path.Contains("/bodyeffects/", StringComparison.Ordinal)
            || path.Contains("/metabolism/", StringComparison.Ordinal))
        {
            var allowedBodyEffectTokens = new[]
            {
                "побочные эффекты", "вещество", "вещества", "симптом", "анимац", "точки кривой"
            };

            return allowedBodyEffectTokens.Any(token => label.Contains(token, StringComparison.Ordinal));
        }

        if (path.Contains("/characters/spawnerpresets/fishspeciespresets/", StringComparison.Ordinal))
        {
            return label.Contains("виды рыбы", StringComparison.Ordinal);
        }

        if (path.Contains("/foliage/farming/", StringComparison.Ordinal))
        {
            return IsPlantSpeciesListSurface(relativePath, userLabel)
                || IsPlantPestListSurface(relativePath, userLabel)
                || IsPlantDiseaseListSurface(relativePath, userLabel);
        }

        if (path.Contains("/items/crafting/", StringComparison.Ordinal))
        {
            return true;
        }

        if (path.Contains("/encounters/", StringComparison.Ordinal)
            || path.Contains("/npcs/", StringComparison.Ordinal))
        {
            var allowedEncounterTokens = new[]
            {
                "классы персонажей", "персонажи для события", "состав пресета npc", "лимит конкретных npc", "точки появления"
            };

            return allowedEncounterTokens.Any(token => label.Contains(token, StringComparison.Ordinal));
        }

        return false;
    }

    private static bool ShouldExposeCookingListTarget(string relativePath, string userLabel)
    {
        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();

        if (path.Contains("/cooking/data/curves/", StringComparison.Ordinal))
        {
            return IsStandaloneGameplayCurvePointsSurface(relativePath, userLabel);
        }

        if (!path.Contains("/cooking/recipes/", StringComparison.Ordinal)
            && !path.Contains("/cooking/data/cookingreciperegistry.uasset", StringComparison.Ordinal))
        {
            return false;
        }

        var blockedTokens = new[]
        {
            "mesh", "material", "texture", "icon", "widget", "audio", "sound",
            "visual", "transform", "component", "root nodes", "all nodes",
            "asset user data", "primary asset"
        };
        if (blockedTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase)))
        {
            return false;
        }

        if (path.Contains("/cooking/data/cookingreciperegistry.uasset", StringComparison.Ordinal))
        {
            return label.Contains("блюда", StringComparison.Ordinal)
                || label.Contains("recipe", StringComparison.Ordinal);
        }

        var allowedTokens = new[]
        {
            "ингредиент", "варианты ингредиента", "вариант ингредиента",
            "possible ingredient", "main ingredient", "ingredients",
            "подходящие предметы", "allowed items", "allowed types"
        };
        return allowedTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
    }

    private static bool IsFishingBaitChanceListSurface(string relativePath, string userLabel)
    {
        if (string.IsNullOrWhiteSpace(userLabel)
            || !relativePath.Contains("/items/fishing/", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var label = userLabel.ToLowerInvariant();
        var normalized = NormalizeAssetKey(userLabel);
        return label.Contains("множитель шанса наживки", StringComparison.Ordinal)
            || label.Contains("множитель шанса покл", StringComparison.Ordinal)
            || label.Contains("catching chance multiplier", StringComparison.Ordinal)
            || label.Contains("catching шанс multiplier", StringComparison.Ordinal)
            || normalized.Contains("catchingchancemultiplier", StringComparison.Ordinal)
            || normalized.Contains("baitchancemultiplier", StringComparison.Ordinal);
    }

    private static bool ShouldExposeGenericContainerTarget(
        string relativePath,
        string userLabel,
        string itemKind,
        string? mapKeyType = null,
        string? mapValueType = null)
    {
        if (!IsGenericGameplayReferenceSurface(relativePath, userLabel))
        {
            return false;
        }

        if (relativePath.Contains("/items/fishing/", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (itemKind.Equals("reference", StringComparison.OrdinalIgnoreCase)
            || itemKind.Equals("reference-map", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (itemKind.Equals("struct", StringComparison.OrdinalIgnoreCase))
        {
            var safeStructLabels = new[]
            {
                "набор", "вариант", "пресет", "состав", "классы", "точки появления", "группа", "вариации",
                "точки спавна", "маркер", "патруль", "маршрут"
            };
            return safeStructLabels.Any(token => userLabel.Contains(token, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(mapKeyType)
            && IsReferenceTypeName(mapKeyType)
            && !string.IsNullOrWhiteSpace(mapValueType)
            && IsMapValueTypeSafeForGenericAdd(mapValueType))
        {
            return true;
        }

        return false;
    }

    private static bool IsGenericGameplayReferenceSurface(string relativePath, string userLabel)
    {
        var path = relativePath.ToLowerInvariant();
        var label = userLabel.ToLowerInvariant();
        if (path.Contains("/items/fishing/", StringComparison.Ordinal))
        {
            return false;
        }

        var blockedPathTokens = new[]
        {
            "/ui/", "/widgets/", "/stringtables/", "/item_icons/", "/icons/", "/textures/", "/texture/",
            "/materials/", "/material/", "/meshes/", "/mesh/", "/skeletal", "/animations/", "/anim/",
            "/vfx/", "/fx/", "/sounds/", "/audio/", "/wwiseaudio/"
        };
        if (blockedPathTokens.Any(token => path.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        var blockedLabelTokens = new[]
        {
            "bytecode", "script", "scriptbytecode", "name map", "namemap", "import", "exports",
            "query token", "asset user data", "root nodes", "all nodes", "корневые узлы", "все узлы",
            "socket", "сокет", "material override", "override materials"
        };
        if (blockedLabelTokens.Any(token => label.Contains(token, StringComparison.Ordinal)))
        {
            return false;
        }

        if (IsMapGameplayAsset(relativePath))
        {
            if (IsMapTechnicalLabel(label))
            {
                return false;
            }

            var allowedMapReferenceTokens = new[]
            {
                "спавн", "spawn", "spawner", "маршрут", "waypoint", "patrol",
                "robot", "sentry", "npc", "vehicle", "транспорт", "квест"
            };
            return allowedMapReferenceTokens.Any(token => label.Contains(token, StringComparison.OrdinalIgnoreCase));
        }

        return path.Contains("/items/", StringComparison.Ordinal)
               || path.Contains("/vehicles/", StringComparison.Ordinal)
               || path.Contains("/maps/", StringComparison.Ordinal)
               || path.Contains("/encounters/", StringComparison.Ordinal)
               || path.Contains("/worldevents/", StringComparison.Ordinal)
               || path.Contains("/gameevents/", StringComparison.Ordinal)
               || path.Contains("/npcs/", StringComparison.Ordinal)
               || path.Contains("/quests/", StringComparison.Ordinal)
               || path.Contains("/skills/", StringComparison.Ordinal)
               || path.Contains("/bodyeffects/", StringComparison.Ordinal)
               || path.Contains("/metabolism/", StringComparison.Ordinal)
               || path.Contains("/foliage/farming/", StringComparison.Ordinal)
               || path.Contains("/fortifications/", StringComparison.Ordinal)
               || path.Contains("/basebuilding/", StringComparison.Ordinal)
               || path.Contains("/characters/spawnerpresets/", StringComparison.Ordinal)
               || path.Contains("/data/tables/items/spawning/", StringComparison.Ordinal);
    }

    private static bool IsReferenceTypeName(string typeName)
    {
        return typeName.Equals("ObjectProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("ClassProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("SoftObjectProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("SoftObjectPathProperty", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsReferencePropertyData(PropertyData property)
    {
        return property is ObjectPropertyData
            or SoftObjectPropertyData
            or SoftObjectPathPropertyData;
    }

    private static bool IsMapValueTypeSafeForGenericAdd(string typeName)
    {
        return typeName.Equals("BoolProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("FloatProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("DoubleProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("IntProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("Int8Property", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("Int16Property", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("Int64Property", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("ByteProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("UInt16Property", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("UInt32Property", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("UInt64Property", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("NameProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("StrProperty", StringComparison.OrdinalIgnoreCase)
               || typeName.Equals("TextProperty", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsStandaloneGameplayCurvePointsSurface(string relativePath, string userLabel)
    {
        if (!userLabel.Contains("точки кривой", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var path = relativePath.ToLowerInvariant();
        return path.Contains("/encounters/spawn_amount_curves/", StringComparison.Ordinal)
            || path.Contains("/cooking/data/curves/", StringComparison.Ordinal)
            || path.Contains("/weather/curves/", StringComparison.Ordinal)
            || path.Contains("/data/weapon/malfunctionprobabilitycurves/", StringComparison.Ordinal)
            || path.Contains("/data/batteryeffectscurves/", StringComparison.Ordinal)
            || path.Contains("/curves/falling/", StringComparison.Ordinal)
            || path.Contains("/curves/landing/", StringComparison.Ordinal)
            || path.Contains("/minigames/lockpicking/", StringComparison.Ordinal)
            || path.Contains("/basebuilding/energydamagecurves/", StringComparison.Ordinal)
            || path.Contains("/characters/mechanoids/sentry/curves/", StringComparison.Ordinal)
            || path.Contains("/characters/zombies2/data/observingcurve", StringComparison.Ordinal)
            || path.Contains("/vehicles/", StringComparison.Ordinal);
    }

    private static bool IsQuestRewardVariantsLabel(string relativePath, string userLabel)
    {
        if (!relativePath.Contains("/quests/", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var label = userLabel.ToLowerInvariant();
        var normalized = NormalizeAssetKey(userLabel);
        return label.Contains("варианты награды", StringComparison.Ordinal)
            || label.Contains("варианты наград", StringComparison.Ordinal)
            || label.Contains("possible rewards", StringComparison.Ordinal)
            || label.Contains("possible награды", StringComparison.Ordinal)
            || normalized.Contains("possiblerewards", StringComparison.Ordinal);
    }

    private static bool IsQuestRewardSkillExperienceLabel(string relativePath, string userLabel)
    {
        if (!relativePath.Contains("/quests/", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var label = userLabel.ToLowerInvariant();
        var normalized = NormalizeAssetKey(userLabel);
        return label.Contains("опыт навыков", StringComparison.Ordinal)
            || label.Contains("skill experience", StringComparison.Ordinal)
            || normalized.Contains("rewardskillexperience", StringComparison.Ordinal)
            || normalized.Contains("skillexperience", StringComparison.Ordinal);
    }

    private static string ResolveFieldSection(string relativePath, string userLabel)
    {
        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();

        if (IsMapGameplayAsset(relativePath))
        {
