    private static string ResolveFieldDescription(string relativePath, string userLabel)
    {
        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();
        if (!path.Contains("/ui/", StringComparison.Ordinal)
            && IsVisualReferenceSurfacePath(relativePath)
            && (IsVisualModelLabel(label) || IsVisualMaterialLabel(label) || IsVisualTextureLabel(label)))
        {
            if (IsVisualModelLabel(label))
            {
                return "Определяет 3D-модель объекта в мире. Замена позволяет подменить внешний вид предмета или объекта без изменения его игровой логики.";
            }

            if (IsVisualMaterialLabel(label))
            {
                return "Определяет материал поверхности: окраску, отражение и общий стиль. Используй совместимые материалы, чтобы избежать визуальных артефактов.";
            }

            return "Определяет текстуру или иконку для инвентаря/интерфейса. Замена меняет отображение предмета, но не его характеристики.";
        }

        if (IsFishingGameplaySurface(relativePath))
        {
            return ResolveFishingFieldDescription(label, path);
        }

        if (IsCookingGameplaySurface(relativePath))
        {
            return ResolveCookingFieldDescription(label, path);
        }

        if (IsHuntingGameplaySurface(relativePath))
        {
            return ResolveHuntingFieldDescription(label, path);
        }

        if (IsWeatherGameplaySurface(relativePath))
        {
            return ResolveWeatherFieldDescription(label, path);
        }

        if (path.Contains("/fortifications/locks/", StringComparison.Ordinal)
            && (label.Contains("внешняя модель замка", StringComparison.Ordinal)
                || label.Contains("внутренняя модель замка", StringComparison.Ordinal)))
        {
            return "Какая модель используется у внешней и внутренней части замка в мини-игре. Ставь только совместимые модели замка, чтобы не сломать визуал и анимацию.";
        }

        if (path.Contains("/fortifications/locks/", StringComparison.Ordinal)
            && IsLockExplosionRadiusLabel(label))
        {
            return label.Contains("внешний", StringComparison.Ordinal)
                || label.Contains("outer", StringComparison.Ordinal)
                    ? "Внешний радиус взрывного штрафа при провале. За пределами этого радиуса урон уже не применяется."
                    : "Радиус зоны полного урона взрывного штрафа при провале. Увеличивай аккуратно, чтобы не сделать замки слишком разрушительными.";
        }

        if (path.Contains("/vehicles/spawningpresets/spawngroups/", StringComparison.Ordinal)
            && label.Contains("доступные варианты транспорта", StringComparison.Ordinal))
        {
            return "Какие пресеты транспорта входят в эту группу спавна. Замена меняет, какие машины, лодки или самолёты игра сможет выбрать для этой группы.";
        }

        if (path.Contains("/vehicles/spawningpresets/automaticspawn/", StringComparison.Ordinal)
            && label.Contains("класс транспорта", StringComparison.Ordinal))
        {
            return "Какой базовый blueprint транспорта создаёт этот пресет. Меняй только на совместимый класс машины, лодки или самолёта.";
        }

        if (path.Contains("/vehicles/spawningpresets/automaticspawn/", StringComparison.Ordinal)
            && label.Contains("класс детали транспорта", StringComparison.Ordinal))
        {
            return "Какая деталь или узел транспорта входит в этот пресет. Используй совместимые attachment-классы этой же линейки транспорта.";
        }

        if (path.Contains("/items/vehicle/attachments/", StringComparison.Ordinal)
            && IsVehicleAttachmentClassLabel(label))
        {
            return "Какой blueprint детали транспорта создаёт этот предмет. Меняй на совместимый attachment-класс, чтобы предмет ставился на правильный транспортный слот.";
        }

        if (path.Contains("/items/food/", StringComparison.Ordinal)
            && IsFoodConsumptionResourceLabel(label))
        {
            return "Какой пищевой GameResource используется при употреблении предмета. Этот ресурс задаёт воду, калории, нутриенты и связанные эффекты еды.";
        }

        if (path.Contains("/quests/", StringComparison.Ordinal)
            && IsQuestAcceptedRecipesLabel(label))
        {
            return "Какие рецепты засчитываются этим квестовым условием. Добавляй только рецепты той же игровой логики, чтобы шаг корректно завершался.";
        }

        if (path.Contains("/items/spawnerpresets2/", StringComparison.Ordinal)
            && label.Contains("предметы контейнерного набора", StringComparison.Ordinal))
        {
            return "Конкретный предмет внутри контейнерного набора лута. Меняй на совместимый предмет игры или свой cooked-ассет предмета.";
        }

        if (path.Contains("/items/", StringComparison.Ordinal))
        {
            if (IsCommonItemSpawnZoneFieldLabel(label))
            {
                return "В каких типах зон этот предмет считается подходящим для появления. Эти флаги помогают спавнерам выбирать лут по месту.";
            }

            if (IsItemSpawnerParticipationLabel(label))
            {
                return "Если включено, обычные мировые спавнеры не выбирают этот предмет. Отключай осторожно: предмет начнёт участвовать в луте только там, где другие таблицы уже допускают его появление.";
            }

            if (IsItemHandsCorrectionsLabel(label))
            {
                return "Профиль коррекции рук, который подгоняет хват под форму предмета. Полезно после замены модели: выбирай профиль от похожего предмета.";
            }

            if (IsItemFirstPersonAnimationsLabel(label))
            {
                return "Профиль анимаций от первого лица для предмета. Меняй на совместимый профиль, чтобы новая модель нормально выглядела в руках.";
            }

            if (IsItemAttachmentSocketMountTypeLabel(label))
            {
                return "Какой профиль крепления используется для удержания, кобуры или слота. При замене модели выбирай профиль от похожего предмета: несовместимый профиль может плохо позиционировать предмет.";
            }

            if (IsItemAttachmentSocketOffsetLabel(label))
            {
                if (label.Contains("прицельной", StringComparison.Ordinal)
                    || label.Contains("aiming down", StringComparison.Ordinal))
                {
                    return "Тонкое смещение оружия в прицельной стойке. Используй после замены модели, если мушка/прицел не попадает в центр экрана.";
                }

                if (label.Contains("левой руки", StringComparison.Ordinal)
                    || label.Contains("supporting hand", StringComparison.Ordinal))
                {
                    return "Позиция IK поддерживающей руки относительно оружия. Помогает посадить левую руку на цевьё или рукоять новой модели.";
                }

                if (label.Contains("кость крепления", StringComparison.Ordinal)
                    || label.Contains("bone name", StringComparison.Ordinal))
                {
                    return "Кость скелета персонажа, к которой привязывается предмет при переноске или креплении на теле. Для нестандартной модели меняй только если понимаешь, где должен висеть предмет.";
                }

                if (label.Contains("поворот", StringComparison.Ordinal)
                    || label.Contains("наклон", StringComparison.Ordinal)
                    || label.Contains("разворот", StringComparison.Ordinal)
                    || label.Contains("крен", StringComparison.Ordinal)
                    || label.Contains("rotation", StringComparison.Ordinal))
                {
                    return "Поворот предмета на теле или в кобуре. Используется для точной посадки модели после замены внешнего вида.";
                }

                return "Смещение предмета на теле или в кобуре. Используется для точной посадки модели после замены внешнего вида.";
            }

            if (IsItemGripSocketNameLabel(label))
            {
                if (label.Contains("дул", StringComparison.Ordinal)
                    || label.Contains("muzzle", StringComparison.Ordinal))
                {
                    return "Имя socket/bone на модели, откуда выходит выстрел, вспышка и трасса. Для пользовательского оружейного rig программа создаёт Muzzle автоматически.";
                }

                if (label.Contains("прицел", StringComparison.Ordinal)
                    || label.Contains("aiming down", StringComparison.Ordinal))
                {
