            return "Насколько уверенно пуля проходит через цели и преграды.";
        }

        if (label.Contains("бронепробиваемость", StringComparison.Ordinal))
        {
            return "Насколько хорошо пуля проходит через броню. 1.0 обычно означает стандартное пробитие, выше — лучше против защиты.";
        }

        if (label.Contains("длина трассера", StringComparison.Ordinal))
        {
            return "Визуальная длина следа пули. Почти не влияет на баланс, но влияет на заметность трассера.";
        }

        if (label.Contains("шум от попадания", StringComparison.Ordinal))
        {
            return "Громкость звука при попадании этой пули.";
        }

        if (label.Contains("разрешена перекраска", StringComparison.Ordinal))
        {
            return "Разрешает использовать перекраску для этого типа боеприпаса.";
        }

        if (label.Contains("скорострельност", StringComparison.Ordinal))
        {
            return "Как быстро оружие делает следующие выстрелы.";
        }

        if (label.Contains("сила отдачи", StringComparison.Ordinal) || label.Contains("отдач", StringComparison.Ordinal))
        {
            return "Насколько сильно оружие уводит при выстреле.";
        }

        if (label.Contains("выдаваемый предмет", StringComparison.Ordinal))
        {
            return "Какой предмет будет выдаваться в этой ячейке набора.";
        }

        if (label.Contains("состояние предмета", StringComparison.Ordinal))
        {
            return "Насколько целым или изношенным будет выдан предмет.";
        }

        if (label.Contains("внешняя модель замка", StringComparison.Ordinal)
            || label.Contains("внутренняя модель замка", StringComparison.Ordinal))
        {
            return "Какая 3D-модель используется у частей замка в мини-игре. Меняй на совместимую модель замка, чтобы не сломать отображение или анимацию.";
        }

        if (label.Contains("время взлома", StringComparison.Ordinal))
        {
            return "Сколько времени длится базовая попытка взлома этого замка.";
        }

        if (label.Contains("число попыток обезвреживания", StringComparison.Ordinal))
        {
            return "Сколько попыток даётся игроку на обезвреживание или взлом.";
        }

        if (label.Contains("опыт за минуту", StringComparison.Ordinal))
        {
            return "Сколько опыта получает навык за минуту этого действия.";
        }

        if (label.Contains("значение на минимальном опыте", StringComparison.Ordinal)
            || label.Contains("значение на максимальном опыте", StringComparison.Ordinal))
        {
            return "Предел бонуса навыка на старте и на полном развитии.";
        }

        if (label.Contains("вид рыбы", StringComparison.Ordinal))
        {
            return "Какой вид рыбы может водиться в этом пресете водоёма.";
        }

        if (label.Contains("вес появления", StringComparison.Ordinal)
            && relativePath.Contains("/characters/spawnerpresets/fishspeciespresets/", StringComparison.OrdinalIgnoreCase))
        {
            return "Насколько часто этот вид рыбы выбирается по сравнению с другими видами в этом водоёме.";
        }

        if (label.Contains("опыт за ", StringComparison.Ordinal))
        {
            return "Сколько опыта получает этот навык за выбранное действие или дистанцию.";
        }

        if (label.Contains("дистанция ремонта", StringComparison.Ordinal))
        {
            return "С какого расстояния персонаж может безопасно выполнять ремонт на этом уровне навыка.";
        }

        if (label.Contains("расход инструмента", StringComparison.Ordinal))
        {
            return "Во сколько раз быстрее или медленнее тратится инструмент. Меньше число обычно выгоднее.";
        }

        if (label.Contains("время ремонта", StringComparison.Ordinal)
            || label.Contains("время заправки", StringComparison.Ordinal)
            || label.Contains("время слива топлива", StringComparison.Ordinal)
            || label.Contains("время зарядки аккумулятора", StringComparison.Ordinal)
            || label.Contains("время запуска с толкача", StringComparison.Ordinal)
            || label.Contains("время зажигания", StringComparison.Ordinal)
            || label.Contains("время взятия крови", StringComparison.Ordinal)
            || label.Contains("задержка переключения передачи", StringComparison.Ordinal))
        {
            return "Во сколько раз навык ускоряет или замедляет это действие. Меньше число обычно означает быстрее.";
        }

        if (label.Contains("максимальная скорость", StringComparison.Ordinal)
            || label.Contains("сила разгона", StringComparison.Ordinal)
            || label.Contains("скорость поворота колёс", StringComparison.Ordinal)
            || label.Contains("параметры двигателя", StringComparison.Ordinal)
            || label.Contains("параметры коробки передач", StringComparison.Ordinal))
        {
            return "Насколько уверенно персонаж управляет транспортом на этом уровне навыка.";
        }

        if (label.Contains("шанс сбоя зажигания", StringComparison.Ordinal)
            || label.Contains("шанс заглушить двигатель", StringComparison.Ordinal)
            || label.Contains("шанс ручного улучшения bcu", StringComparison.Ordinal))
        {
            return "Вероятность успешного или неудачного исхода для этого действия на выбранном уровне навыка.";
        }

        if (label.Contains("ингредиент", StringComparison.Ordinal))
        {
            return "Параметр состава рецепта и требований к предметам.";
        }

        if (relativePath.Contains("radiation", StringComparison.OrdinalIgnoreCase))
        {
            return "Параметр радиационного эффекта или зоны.";
        }

        if (relativePath.Contains("/encounters/", StringComparison.OrdinalIgnoreCase)
            || relativePath.Contains("/npcs/", StringComparison.OrdinalIgnoreCase))
        {
            return "Безопасный параметр поведения NPC, орд или игровых событий.";
        }

        if (relativePath.Contains("/economy/", StringComparison.OrdinalIgnoreCase))
        {
            return "Безопасный параметр торговли, аванпоста или экономики.";
        }

        if (relativePath.Contains("/fortifications/locks/", StringComparison.OrdinalIgnoreCase)
            || relativePath.Contains("/minigames/lockpicking/", StringComparison.OrdinalIgnoreCase)
            || relativePath.Contains("/basebuilding/", StringComparison.OrdinalIgnoreCase))
        {
            return "Безопасный параметр замка, взлома, ловушки или защиты базы.";
        }

        if (relativePath.Contains("/vehicles/", StringComparison.OrdinalIgnoreCase))
        {
            return "Безопасный параметр транспорта, столкновения или урона при аварии.";
        }

        if (relativePath.Contains("/skills/", StringComparison.OrdinalIgnoreCase))
        {
            return "Безопасный параметр навыка и его прокачки.";
        }

        if (relativePath.Contains("/quests/", StringComparison.OrdinalIgnoreCase))
        {
            return "Безопасный параметр цели, награды или хода квеста.";
        }

        return "Игровая настройка этого раздела.";
    }

    private static string ResolveFishingFieldDescription(string label, string path)
    {
        if (path.Contains("/characters/spawnerpresets/fishspeciespresets/", StringComparison.Ordinal))
        {
            if (label.Contains("вид рыбы", StringComparison.Ordinal))
            {
                return "Какой вид рыбы входит в этот пресет водоёма.";
            }

            if (label.Contains("вес появления", StringComparison.Ordinal))
            {
                return "Насколько часто этот вид выбирается внутри пресета. Чем выше вес, тем чаще рыба появляется.";
            }
        }

        if (path.Contains("/characters/spawnerpresets/fishspawningpresets/", StringComparison.Ordinal))
        {
            return "Насколько часто этот водный пресет участвует в выборе появления рыбы.";
        }

        if (label.Contains("множитель шанса", StringComparison.Ordinal)
            || label.Contains("catching шанс", StringComparison.Ordinal)
            || label.Contains("покл", StringComparison.Ordinal))
        {
            return "Как сильно эта наживка повышает или снижает шанс поймать конкретный вид рыбы.";
        }

        if (label.Contains("заброс", StringComparison.Ordinal)
            || label.Contains("casting", StringComparison.Ordinal))
        {
            return "Параметр заброса удилища: сила или угол, которые влияют на дальность и удобство рыбалки.";
        }

        if (label.Contains("рабочей зоны рыбалки", StringComparison.Ordinal)
            || label.Contains("fishing bounds angle", StringComparison.Ordinal))
        {
            return "Угол рабочей зоны мини-игры рыбалки. Меняет допустимый сектор, в котором удерживать снасть проще или сложнее.";
        }

        if (label.Contains("катуш", StringComparison.Ordinal)
            || label.Contains("reel", StringComparison.Ordinal)
            || label.Contains("подмот", StringComparison.Ordinal))
        {
            return "Параметр катушки и подмотки лески: скорость, ускорение или сопротивление при вываживании.";
        }

        if (label.Contains("леск", StringComparison.Ordinal)
            || label.Contains("натяж", StringComparison.Ordinal)
            || label.Contains("tension", StringComparison.Ordinal)
            || label.Contains("разрыв", StringComparison.Ordinal))
        {
            return "Прочность и натяжение лески. Слишком большие значения могут сделать рыбалку слишком лёгкой, слишком маленькие - ломать снасть слишком часто.";
        }

        if (label.Contains("рыб", StringComparison.Ordinal)
            || label.Contains("fish", StringComparison.Ordinal))
        {
            return "Параметр поведения рыбы во время вываживания: скорость, восстановление или расход выносливости.";
        }

        if (label.Contains("поплав", StringComparison.Ordinal)
            || label.Contains("погруж", StringComparison.Ordinal)
            || label.Contains("ряб", StringComparison.Ordinal))
        {
            return "Параметр поплавка: как он ведёт себя на воде и при подмотке.";
        }

        if (label.Contains("урон со временем", StringComparison.Ordinal))
        {
            return "Скорость износа предмета со временем или при использовании.";
        }

        if (label.Contains("боевой режим", StringComparison.Ordinal))
        {
            return "Если включено, предмет автоматически сбрасывается при переходе персонажа в боевой режим.";
        }

        return "Игровая настройка рыболовной системы.";
    }

    private static string ResolveCookingFieldDescription(string label, string path)
    {
        if (path.Contains("/cooking/data/cookingcommondata.uasset", StringComparison.Ordinal))
        {
            if (label.Contains("базовый опыт", StringComparison.Ordinal))
            {
                return "Сколько опыта кулинарии выдаётся за сам факт приготовления рецепта.";
            }

            if (label.Contains("время готовки", StringComparison.Ordinal))
            {
                return "Дополнительный опыт за длительность приготовления. Чем выше значение, тем сильнее время рецепта влияет на награду навыка.";
            }

            if (label.Contains("температур", StringComparison.Ordinal))
            {
                return "Дополнительный опыт за температурную часть готовки. Меняй осторожно, чтобы прокачка кулинарии не стала слишком быстрой.";
            }
        }

        if (path.Contains("/cooking/data/cookingreciperegistry.uasset", StringComparison.Ordinal))
        {
            return "Включает или отключает блюдо в игровом реестре готовки.";
        }

        if (path.Contains("/cooking/data/curves/", StringComparison.Ordinal))
        {
            if (label.Contains("положение точки кривой", StringComparison.Ordinal)
                || label.Contains("когда начинается эта ступень", StringComparison.Ordinal))
            {
                return "Входное значение кривой: количество, ошибка времени, температура или другой параметр готовки.";
            }

            return "Выходное значение кривой: как сильно меняется качество, масса или итог приготовления в этой точке.";
        }

        if (label.Contains("что создаётся", StringComparison.Ordinal)
            || label.Contains("результат", StringComparison.Ordinal)
            || label.Contains("product", StringComparison.Ordinal))
        {
            return "Какой предмет или блюдо игрок получает после успешного приготовления.";
        }

        if (label.Contains("ингредиент", StringComparison.Ordinal)
            || label.Contains("подходящий предмет", StringComparison.Ordinal)
            || label.Contains("вариант", StringComparison.Ordinal))
        {
            return "Какие продукты или группы продуктов подходят для этого слота рецепта.";
        }

        if (label.Contains("тратить предмет целиком", StringComparison.Ordinal))
        {
            return "Если включено, ингредиент расходуется полностью, а не частично по ресурсу или объёму.";
        }

        if (label.Contains("литры", StringComparison.Ordinal)
            || label.Contains("расход", StringComparison.Ordinal))
        {
            return "Сколько ингредиента тратится при приготовлении этого блюда.";
        }

        if (label.Contains("питательност", StringComparison.Ordinal))
        {
            return "Насколько этот ингредиент влияет на питательность итогового блюда.";
        }

        if (label.Contains("качество", StringComparison.Ordinal)
            || label.Contains("готовност", StringComparison.Ordinal)
            || label.Contains("температур", StringComparison.Ordinal)
            || label.Contains("время", StringComparison.Ordinal))
        {
            return "Параметр приготовления, который влияет на готовность, качество или итоговую ценность блюда.";
        }

        return "Безопасная настройка системы готовки.";
    }

    private static string ResolveHuntingFieldDescription(string label, string path)
    {
        if (path.Contains("/hunting/biomedata/", StringComparison.Ordinal))
        {
            if (label.Contains("дистанция до следующего следа", StringComparison.Ordinal))
            {
                return "На какой дистанции от текущей подсказки игра может разместить следующий след животного.";
            }

            if (label.Contains("количество следов", StringComparison.Ordinal))
            {
                return "Сколько подсказок игрок должен последовательно найти перед выходом на животное.";
            }

            if (label.Contains("размер группы животных", StringComparison.Ordinal))
            {
                return "Минимальный и максимальный размер группы животных для этого охотничьего биома.";
            }

            if (label.Contains("угол разброса", StringComparison.Ordinal))
            {
                return "Насколько широко следующий след может отклоняться от направления текущей цепочки.";
            }

            if (label.Contains("вес появления", StringComparison.Ordinal))
            {
                return "Насколько часто этот вариант выбирается среди охотничьих биомов. Чем выше вес, тем вероятнее появление.";
            }
        }

        if (label.Contains("дистанция слышимости", StringComparison.Ordinal))
        {
            return "С какой дистанции игрок может услышать подсказку охоты.";
        }

        if (label.Contains("минимальная дистанция видимости", StringComparison.Ordinal))
        {
            return "Минимальная дистанция, на которой подсказка становится заметной игроку.";
        }

        if (label.Contains("время исчезновения", StringComparison.Ordinal))
        {
            return "Сколько времени занимает затухание охотничьей подсказки.";
        }

        if (label.Contains("жизнь после исчезновения", StringComparison.Ordinal))
        {
            return "Сколько подсказка ещё живёт в мире после визуального исчезновения.";
        }

        return "Безопасная настройка охотничьих следов и подсказок.";
    }

    private static string ResolveWeatherFieldDescription(string label, string path)
    {
        if (label.Contains("положение точки кривой", StringComparison.Ordinal)
            || label.Contains("когда начинается эта ступень", StringComparison.Ordinal))
        {
            return "Входное значение погодной кривой: время, высота солнца, облачность или другая переменная симуляции.";
        }

        return "Выходное значение погодной кривой: сила ветра, плотность тумана, влажность, освещение или другой погодный эффект.";
    }

    private static string ResolveReferenceInfoDescription(string relativePath, string userLabel)
    {
        var label = userLabel.ToLowerInvariant();
        if (label.Contains("связанные вещества эффекта", StringComparison.Ordinal))
        {
            return "Справка: какие вещества или стимуляторы могут включать этот эффект.";
        }

        if (label.Contains("симптом", StringComparison.Ordinal))
        {
            return "Справка: какой игровой симптом связан с этим эффектом.";
        }

        if (label.Contains("вещество", StringComparison.Ordinal)
            || label.Contains("вещества", StringComparison.Ordinal))
        {
            return "Справка: какое вещество или стимулятор запускает этот эффект.";
        }

        if (label.Contains("навык", StringComparison.Ordinal))
        {
            return "Справка: какая игровая система или навык связаны с этим параметром.";
        }

        return ResolveFieldDescription(relativePath, userLabel);
    }

    private static List<StudioModFieldOptionDto>? ResolveFieldOptions(string relativePath, string userLabel, string valueType, string currentValue)
    {
        if (valueType != "enum")
        {
            return null;
        }

        if (currentValue.StartsWith("ECraftingIngredientPurpose::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("роль ингредиента", StringComparison.OrdinalIgnoreCase))
        {
            return CraftingIngredientPurposeOptions;
        }

        if (currentValue.StartsWith("ECraftingIngredientMixingType::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("смешивать варианты", StringComparison.OrdinalIgnoreCase))
        {
            return CraftingIngredientMixingTypeOptions;
        }

        if (currentValue.StartsWith("EDisposition::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("тип воздействия", StringComparison.OrdinalIgnoreCase))
        {
            return DispositionOptions;
        }

        if (currentValue.StartsWith("ETraderType::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("тип торговца", StringComparison.OrdinalIgnoreCase))
        {
            return TraderTypeOptions;
        }

        if (currentValue.StartsWith("ECurrencyType::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("валюта покупки карты", StringComparison.OrdinalIgnoreCase))
        {
            return CurrencyTypeOptions;
        }

        if (currentValue.StartsWith("EBankCardType::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("требуемая банковская карта", StringComparison.OrdinalIgnoreCase))
        {
            return BankCardTypeOptions;
        }

        if (currentValue.StartsWith("EFoodCookLevel::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("готовность еды", StringComparison.OrdinalIgnoreCase))
        {
            return FoodCookLevelOptions;
        }

        if (currentValue.StartsWith("EFoodCookQuality::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("качество еды", StringComparison.OrdinalIgnoreCase))
        {
            return FoodCookQualityOptions;
        }

        if (currentValue.StartsWith("EPlantGrowthStage::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("финальная стадия роста", StringComparison.OrdinalIgnoreCase))
        {
            return PlantGrowthStageOptions;
        }

        if (currentValue.StartsWith("EItemRarity::", StringComparison.OrdinalIgnoreCase)
            || userLabel.Contains("редкость набора", StringComparison.OrdinalIgnoreCase))
        {
            return ItemRarityOptions;
        }

        return null;
    }

    private static (string? ReferencePickerKind, string? ReferencePickerPrompt) ResolveFieldReferencePicker(
        string relativePath,
        string userLabel,
        string valueType,
        string currentValue)
    {
        if (valueType is not ("object" or "soft-object" or "soft-object-path"))
        {
            return (null, null);
        }

        var label = userLabel.ToLowerInvariant();
        var path = relativePath.ToLowerInvariant();

        if (TryResolveVisualReferencePicker(valueType, label, currentValue, out var visualPickerKind, out var visualPickerPrompt))
        {
            return (visualPickerKind, visualPickerPrompt);
        }

        if (path.Contains("/items/food/", StringComparison.Ordinal)
            && IsFoodConsumptionResourceLabel(label))
        {
            return (
                "food-resource-class",
                "Найди пищевой ресурс, который должен использоваться при употреблении этого предмета.");
        }

        if (path.Contains("/items/vehicle/attachments/", StringComparison.Ordinal)
            && IsVehicleAttachmentClassLabel(label))
        {
            return (
                "vehicle-attachment-class",
                "Найди совместимый blueprint детали транспорта для этого предмета.");
        }

        if (path.Contains("/items/", StringComparison.Ordinal)
            && IsItemHandsCorrectionsLabel(label))
        {
            return (
                "item-hands-corrections",
                "Найди профиль коррекции рук от похожего предмета, чтобы новая модель правильно сидела в руках.");
        }

        if (path.Contains("/items/", StringComparison.Ordinal)
            && IsItemFirstPersonAnimationsLabel(label))
        {
            return (
                "item-first-person-animations",
                "Найди профиль анимаций от первого лица для похожего предмета.");
        }

        if (path.Contains("/items/", StringComparison.Ordinal)
            && IsItemAttachmentSocketMountTypeLabel(label))
        {
            return (
                "item-attachment-socket-mount-type",
                "Найди совместимый профиль крепления предмета для руки, кобуры или слота.");
        }

        if (path.Contains("/quests/", StringComparison.Ordinal)
            && IsQuestAcceptedRecipesLabel(label))
        {
            return (
                "crafting-recipe-asset",
                "Найди рецепт, который должен засчитываться этим квестовым условием.");
        }

        if (path.Contains("/economy/", StringComparison.Ordinal)
            && IsEconomyCurveLabel(label))
        {
            return (
                "economy-curve",
                "Найди CurveFloat из экономики, который должен управлять этим ценовым или торговым множителем.");
        }

        if ((path.Contains("/encounters/", StringComparison.Ordinal)
                || path.Contains("/npcs/", StringComparison.Ordinal))
            && IsEncounterSpawnAmountCurveLabel(label))
        {
            return (
                "encounter-spawn-amount-curve",
                "Найди кривую количества спавна, которая должна управлять базовой плотностью NPC для этого события.");
        }

        if (path.Contains("/items/spawnerpresets2/", StringComparison.Ordinal)
            && label.Contains("предметы контейнерного набора", StringComparison.Ordinal))
        {
            return (
                "item-asset",
                "Найди предмет, который должен входить в этот контейнерный набор лута.");
        }

        if (path.Contains("/vehicles/spawningpresets/spawngroups/", StringComparison.Ordinal)
            && label.Contains("доступные варианты транспорта", StringComparison.Ordinal))
        {
            return (
                "vehicle-spawn-preset",
                "Найди пресет транспорта, который эта группа сможет выбирать при спавне.");
        }

        if (path.Contains("/vehicles/spawningpresets/automaticspawn/", StringComparison.Ordinal)
            && label.Contains("класс транспорта", StringComparison.Ordinal))
        {
            return (
                "vehicle-class",
                "Найди blueprint класса транспорта, который этот пресет должен создавать.");
        }

        if (path.Contains("/vehicles/spawningpresets/automaticspawn/", StringComparison.Ordinal)
            && label.Contains("класс детали транспорта", StringComparison.Ordinal))
        {
            return (
                "vehicle-attachment-class",
                "Найди совместимую деталь или узел транспорта для этого пресета.");
        }

        if (path.Contains("/cooking/recipes/", StringComparison.Ordinal)
            && (label.Contains("ингредиент", StringComparison.Ordinal)
                || label.Contains("подходящий предмет", StringComparison.Ordinal)
                || label.Contains("вариант ингредиента", StringComparison.Ordinal)
                || label.Contains("что создаётся", StringComparison.Ordinal)
                || label.Contains("результат", StringComparison.Ordinal)
                || label.Contains("product", StringComparison.Ordinal)))
        {
            return (
                "item-asset",
                "Найди игровой предмет или блюдо, которое должно использоваться в этом рецепте.");
        }

        if (IsMapGameplayAsset(relativePath)
            && (label.Contains("класс сидячего npc", StringComparison.Ordinal)
                || label.Contains("sedentary npc class", StringComparison.Ordinal)))
        {
            return (
                "encounter-npc-class",
                "Найди класс NPC, который должен использоваться для этой точки торговца или сидячего персонажа.");
        }

        if (IsCargoDropContainerAsset(relativePath))
        {
            if (label.Contains("основные пресеты лута", StringComparison.Ordinal)
                || label.Contains("основные обычные пресеты лута", StringComparison.Ordinal)
                || label.Contains("обычный пресет лута", StringComparison.Ordinal))
            {
                return (
                    "item-spawner-preset",
                    "Найди совместимый пресет грузового дропа, который контейнер должен использовать для этого варианта лута.");
            }

            if (label.Contains("контейнерные наборы лута", StringComparison.Ordinal)
                || label.Contains("основные расширенные пресеты лута", StringComparison.Ordinal)
                || label.Contains("контейнерный набор лута", StringComparison.Ordinal)
                || label.Contains("расширенный пресет лута", StringComparison.Ordinal))
            {
                return (
                    "advanced-item-spawner-preset",
                    "Найди совместимый контейнерный набор грузового дропа, который должен использовать этот вариант лута.");
            }
        }

        if ((path.Contains("/bodyeffects/", StringComparison.Ordinal)
                || path.Contains("/metabolism/", StringComparison.Ordinal))
            && label.Contains("вещество-источник эффекта", StringComparison.Ordinal))
        {
            return (
                "foreign-substance-all",
                "Найди вещество, которое должно запускать этот эффект, и выбери его из списка.");
        }

        if (path.Contains("/items/weapons/", StringComparison.Ordinal)
            && (label.Contains("патрон по умолчанию", StringComparison.Ordinal)
                || label.Contains("default ammunition", StringComparison.Ordinal)))
        {
            return (
                "ammo-item-asset",
                "Найди тип патрона, который оружие должно считать базовым, и выбери его из списка.");
        }

        if (path.Contains("/items/ammunition/", StringComparison.Ordinal)
            && (label.Contains("класс пули", StringComparison.Ordinal)
                || label.Contains("данные пули", StringComparison.Ordinal)
                || label.Contains("projectile", StringComparison.Ordinal)))
        {
            return (
                "ammo-projectile-class",
                "Найди класс пули, который должен использовать этот боеприпас, и выбери его из списка.");
        }

        if (path.Contains("/items/crafting/recipes/", StringComparison.Ordinal)
            && (label.Contains("какой навык влияет на рецепт", StringComparison.Ordinal)
                || label.Contains("основной навык рецепта", StringComparison.Ordinal)
                || label.Contains("навык влияет на рецепт", StringComparison.Ordinal)))
        {
            return (
                "skill-asset",
                "Найди навык, который должен влиять на этот рецепт, и выбери его из списка.");
        }

        if (path.Contains("/bodyeffects/", StringComparison.Ordinal)
            && label.Contains("какой симптом запускается", StringComparison.Ordinal))
        {
            return (
                "bodyeffect-symptom",
                "Найди симптом, который должен запускаться этим эффектом, и выбери его из списка.");
        }

        if (path.Contains("/quests/", StringComparison.Ordinal)
            && label.Contains(" / квесты", StringComparison.Ordinal))
        {
            return (
                "quest-asset",
                "Найди квест, который должен входить в этот набор, и выбери его из списка.");
        }

        if (path.Contains("/quests/", StringComparison.Ordinal)
            && (label.Contains("что открыть после завершения", StringComparison.Ordinal)
                || label.Contains("tasks to unlock", StringComparison.Ordinal)))
        {
            return (
                "quest-asset",
                "Найди квест или задачу, которая должна открыться после выполнения текущего задания.");
        }

        if (IsGameEventMarkerAsset(relativePath)
            && (label.Contains("класс события", StringComparison.Ordinal)
                || label.Contains("game event class", StringComparison.Ordinal)))
        {
            return (
                "gameevent-class",
                "Найди игровой режим, который эта точка карты должна запускать (бой насмерть, командный бой, захват флага, зона сброса).");
        }

        if (IsGameEventMarkerAsset(relativePath)
            && (label.Contains("класс границы события", StringComparison.Ordinal)
                || label.Contains("border class", StringComparison.Ordinal)))
        {
            return (
                "gameevent-border-class",
                "Найди класс границы события, который должен ограничивать игровую зону.");
        }

        if (IsGameEventCoreAsset(relativePath)
            && (label.Contains("набор снаряжения команды a", StringComparison.Ordinal)
                || label.Contains("набор снаряжения команды b", StringComparison.Ordinal)))
        {
            return (
                "gameevent-team-equipment-set",
                label.Contains("команды a", StringComparison.Ordinal)
                    ? "Найди готовый набор снаряжения для команды A."
                    : "Найди готовый набор снаряжения для команды B.");
        }

        if (IsGameEventCoreAsset(relativePath)
            && label.Contains("класс ящика события", StringComparison.Ordinal))
        {
            return (
                "gameevent-dropzone-crate-class",
                "Найди класс ящика для Drop Zone: именно этот класс будет создан для командных контейнеров.");
        }

        if (IsGameEventCoreAsset(relativePath)
            && label.Contains("класс груза события", StringComparison.Ordinal))
        {
            return (
                "gameevent-dropzone-cargo-class",
                "Найди тип центрального груза для Drop Zone: именно этот объект события будет создан в центре, а его наполнение настраивается отдельно.");
        }

        if (path.Contains("/characters/spawnerpresets/fishspeciespresets/", StringComparison.Ordinal)
            && label.Contains("вид рыбы", StringComparison.Ordinal))
        {
            return (
                "fish-species-asset",
                "Найди вид рыбы, который должен водиться в этом пресете водоёма.");
        }

        if (path.Contains("/ui/gameevents/itemselection/", StringComparison.Ordinal)
            && label.Contains("главный предмет", StringComparison.Ordinal))
        {
            return (
                "item-asset",
                "Найди главный предмет, который игрок должен получать при выборе этого набора события.");
        }

        if (path.Contains("/ui/gameevents/itemselection/", StringComparison.Ordinal)
            && (label.Contains("дополнительные предметы", StringComparison.Ordinal)
                || label.Contains("крепления", StringComparison.Ordinal)))
        {
            return (
                "item-asset",
                label.Contains("крепления", StringComparison.Ordinal)
                    ? "Найди крепление, которое должно выдаваться вместе с главным оружием набора."
                    : "Найди дополнительный предмет, который должен выдаваться вместе с набором события.");
        }

        if (IsGameEventMarkerAsset(relativePath) && IsGameEventLoadoutListLabel(userLabel))
        {
            if (label.Contains("основное оружие", StringComparison.Ordinal))
            {
                return (
                    "gameevent-primary-loadout",
                    "Найди набор основного оружия, который игрок сможет выбрать в этом событии.");
            }

            if (label.Contains("пистолет", StringComparison.Ordinal))
            {
                return (
                    "gameevent-secondary-loadout",
                    "Найди набор пистолета, который игрок сможет выбрать как второй слот.");
            }

            if (label.Contains("ближний бой", StringComparison.Ordinal))
            {
                return (
                    "gameevent-tertiary-loadout",
                    "Найди набор ближнего боя, который игрок сможет выбрать как третий слот.");
            }

            if (label.Contains("одежда", StringComparison.Ordinal))
            {
                return (
                    "gameevent-outfit-loadout",
                    "Найди комплект одежды, который игрок сможет выбрать для события.");
            }

            if (label.Contains("обязательный набор", StringComparison.Ordinal))
            {
                return (
                    "gameevent-mandatory-loadout",
                    "Найди обязательный набор снаряжения, который событие выдаёт всем участникам.");
            }

            if (label.Contains("дополнительное снаряжение", StringComparison.Ordinal))
            {
                return (
                    "gameevent-support-loadout",
                    "Найди дополнительный набор снаряжения, который событие выдаёт участникам.");
            }
        }

        if (path.Contains("/foliage/farming/", StringComparison.Ordinal)
            && label.Contains("пакет семян", StringComparison.Ordinal))
        {
            return (
                "item-asset",
                "Найди пакет семян, который должен использоваться для посадки этой культуры.");
        }

        if (path.Contains("/foliage/farming/", StringComparison.Ordinal)
            && IsPlantPestListSurface(relativePath, userLabel))
        {
            return (
                "plant-pest-asset",
                "Найди вредителя, который должен уметь поражать это растение.");
        }

        if (path.Contains("/foliage/farming/", StringComparison.Ordinal)
            && IsPlantDiseaseListSurface(relativePath, userLabel))
        {
            return (
                "plant-disease-asset",
                "Найди болезнь, которую это растение должно уметь подхватывать.");
        }

        if (path.Contains("/items/spawnerpresets2/", StringComparison.Ordinal)
            && label.Contains("готовый подпакет", StringComparison.Ordinal))
        {
            return (
                "advanced-item-spawner-subpreset",
                "Найди совместимый контейнерный подпакет, который этот контейнер сможет выбирать.");
        }

        if (valueType == "object"
            && currentValue.StartsWith("script:PrisonerBodyConditionOrSymptomSideEffect_", StringComparison.OrdinalIgnoreCase))
        {
            return (
                "bodyeffect-side-effect",
                "Найди, какое последствие нужно включить: сила, скорость, урон, приступ или другой эффект.");
        }

        if ((path.Contains("/encounterzones/", StringComparison.Ordinal)
                || path.Contains("/encounters/", StringComparison.Ordinal)
                || path.Contains("/characters/npcs/", StringComparison.Ordinal))
            && (label.Contains("класс десантного корабля", StringComparison.Ordinal)
                || label.Contains("класс охраны десантного корабля", StringComparison.Ordinal)))
        {
            return (
                "guarded-zone-dropship-class",
                "Найди класс дропшипа для охраняемой зоны: обычный или охранный вариант.");
        }

        if ((path.Contains("/encounterzones/", StringComparison.Ordinal)
                || path.Contains("/encounters/", StringComparison.Ordinal)
                || path.Contains("/characters/npcs/", StringComparison.Ordinal))
            && (label.Contains("какое событие может запуститься", StringComparison.Ordinal)
                || label.Contains("класс орды защитников", StringComparison.Ordinal)))
        {
            return (
                "encounter-class",
                "Найди подходящий класс события из игры и выбери его из списка.");
        }

        return (null, null);
    }

    private static bool TryResolveVisualReferencePicker(
        string valueType,
        string label,
        string currentValue,
        out string pickerKind,
        out string pickerPrompt)
    {
        pickerKind = string.Empty;
        pickerPrompt = string.Empty;
        if (!IsReferenceValueType(valueType))
        {
            return false;
        }

        var lowerCurrent = (currentValue ?? string.Empty).ToLowerInvariant();
        var isMaterial = IsVisualMaterialLabel(label);
        var isTexture = IsVisualTextureLabel(label);
        var isModel = IsVisualModelLabel(label);
        if (!isMaterial && !isTexture && !isModel)
        {
            return false;
        }

        if (isMaterial)
        {
            pickerKind = IsObjectReferenceType(valueType) ? "visual-material-object" : "visual-material-asset";
            pickerPrompt = "Найди материал внешнего вида, который должен использовать этот предмет или объект.";
            return true;
        }

        if (isTexture)
        {
            pickerKind = IsObjectReferenceType(valueType) ? "visual-icon-object" : "visual-icon-asset";
            pickerPrompt = "Найди подходящую текстуру или иконку, чтобы заменить внешний вид в интерфейсе и инвентаре.";
            return true;
        }

        var prefersSkeletal = label.Contains("skeletal", StringComparison.Ordinal)
                              || label.Contains("скелет", StringComparison.Ordinal)
                              || lowerCurrent.Contains(".sk_", StringComparison.Ordinal)
                              || lowerCurrent.Contains("/sk_", StringComparison.Ordinal);
        pickerKind = prefersSkeletal
            ? (IsObjectReferenceType(valueType) ? "visual-skeletal-mesh-object" : "visual-skeletal-mesh-asset")
            : (IsObjectReferenceType(valueType) ? "visual-static-mesh-object" : "visual-static-mesh-asset");
        pickerPrompt = "Найди модель, которую нужно использовать вместо текущей для этого предмета или объекта.";
        return true;
    }

    private static bool IsVisualModelLabel(string label)
    {
        var hasModelToken = ContainsSearchTermAtBoundary(label, "mesh")
                            || ContainsSearchTermAtBoundary(label, "model")
                            || ContainsSearchTermAtBoundary(label, "модель");
        return hasModelToken
               && !label.Contains("slice", StringComparison.Ordinal)
               && !label.Contains("socket", StringComparison.Ordinal)
               && !label.Contains("сокет", StringComparison.Ordinal);
    }

    private static bool IsVisualMaterialLabel(string label)
    {
        return (label.Contains("material", StringComparison.Ordinal)
                || label.Contains("материал", StringComparison.Ordinal))
               && !label.Contains("расход", StringComparison.Ordinal)
               && !label.Contains("ингредиент", StringComparison.Ordinal);
    }

    private static bool IsVisualTextureLabel(string label)
    {
        return label.Contains("texture", StringComparison.Ordinal)
               || label.Contains("текстур", StringComparison.Ordinal)
               || label.Contains("icon", StringComparison.Ordinal)
               || label.Contains("икон", StringComparison.Ordinal);
    }

    private static bool IsReferenceValueType(string valueType)
    {
        return valueType is "object" or "soft-object" or "soft-object-path";
    }

    private static bool IsObjectReferenceType(string valueType)
    {
        return valueType.Equals("object", StringComparison.Ordinal);
    }

    private static string ResolveEditorKind(
        string relativePath,
        string userLabel,
        string valueType,
        IReadOnlyCollection<StudioModFieldOptionDto>? options,
        string? referencePickerKind)
    {
        if (options is not null && options.Count > 0)
        {
            return "select";
        }

        if (!string.IsNullOrWhiteSpace(referencePickerKind))
        {
            return "reference-picker";
        }

        if (valueType == "object")
        {
            return "asset-ref";
        }

        if (valueType is "soft-object" or "soft-object-path")
        {
            var label = userLabel.ToLowerInvariant();
            if (relativePath.Contains("/spawnequipment/", StringComparison.OrdinalIgnoreCase)
                || label.Contains("предмет", StringComparison.Ordinal)
                || label.Contains("патрон", StringComparison.Ordinal)
                || label.Contains("награда", StringComparison.Ordinal)
                || label.Contains("что создаётся", StringComparison.Ordinal))
            {
                return "item-picker";
            }

            return "asset-ref";
        }

        return valueType switch
        {
            "bool" => "toggle",
            "int" or "int8" or "int16" or "int64" or "uint16" or "uint32" or "uint64" or "byte" or "float" or "double" or "long" => "number",
            _ => "text"
        };
    }

