    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return "без названия";
        }

        var text = value
            .Replace('_', ' ')
            .Replace('-', ' ')
            .Trim();

        var compactReplacements = new (string From, string To)[]
        {
            ("questcommondata", "quest common data"),
            ("questmangerdata", "quest manager data"),
            ("generalgoods", "general goods"),
            ("ammobox", " ammo box"),
