    private static bool TryApplyForeignSubstanceAttributeFieldEdit(
        UAsset asset,
        StudioFieldEditDto edit,
        List<string> warnings,
        out bool applied)
    {
        applied = false;
        var propertyName = edit.FieldPath[ForeignSubstanceAttributeFieldPrefix.Length..].Trim();
        if (string.IsNullOrWhiteSpace(propertyName))
        {
            warnings.Add("UAsset edit skipped: не указан параметр вещества-модификатора.");
            return true;
        }

        var allowedProperties = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "_strengthChange",
            "_strengthModifier",
            "_constitutionChange",
            "_constitutionModifier",
            "_dexterityChange",
            "_dexterityModifier",
            "_intelligenceChange",
            "_intelligenceModifier"
        };

        if (!allowedProperties.Contains(propertyName))
        {
            warnings.Add($"UAsset edit skipped: неподдерживаемый параметр вещества {propertyName}");
            return true;
        }

        if (!IsForeignSubstanceAttributeModifierAsset(asset))
        {
            warnings.Add($"UAsset edit skipped: параметр {propertyName} можно добавлять только в вещества, которые модифицируют характеристики.");
            return true;
        }

        if (!TryFindForeignSubstanceModifierExport(asset, out var export, out _))
        {
            warnings.Add($"UAsset edit skipped: экспорт для {propertyName} не найден.");
            return true;
        }

        if (!float.TryParse(edit.Value, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var value))
        {
            warnings.Add($"UAsset edit skipped: {propertyName} (ожидается float)");
            return true;
        }

        var conflictingProperty = export.Data
            .OfType<PropertyData>()
            .FirstOrDefault(property =>
                PropertyNamesMatch(property.Name?.ToString(), propertyName)
                && property is not FloatPropertyData);
        if (conflictingProperty is not null)
        {
            warnings.Add($"UAsset edit skipped: {propertyName} уже существует, но хранится не как число.");
            return true;
        }

        var existingFloatProperty = FindTopLevelFloatPropertyLoose(export, propertyName);
        if (existingFloatProperty is not null)
        {
            existingFloatProperty.Value = value;
        }
        else
        {
            EnsureTopLevelFloatProperty(asset, export, propertyName).Value = value;
        }

        applied = true;
        return true;
    }

    private static bool TryApplyWeaponSyntheticFieldEdit(
        UAsset asset,
        StudioFieldEditDto edit,
        List<string> warnings,
        out bool applied)
    {
        applied = false;
        var propertyName = edit.FieldPath[WeaponSyntheticFieldPrefix.Length..].Trim();
        if (string.IsNullOrWhiteSpace(propertyName))
        {
            warnings.Add("UAsset edit skipped: не указан параметр оружия.");
            return true;
        }

        if (propertyName.StartsWith("clear-override-materials:", StringComparison.OrdinalIgnoreCase))
        {
            var exportPath = propertyName["clear-override-materials:".Length..].Trim();
            if (!TryResolveExportIndexFromSyntheticPath(exportPath, asset.Exports.Count, out var exportIndex))
            {
                warnings.Add($"Weapon edit skipped: неверный component path {exportPath}");
                return true;
            }

            if (asset.Exports[exportIndex] is not NormalExport componentExport)
            {
                warnings.Add($"Weapon edit skipped: export {exportPath} не является NormalExport");
                return true;
            }

            var overrideMaterials = FindTopLevelProperty<ArrayPropertyData>(componentExport, "OverrideMaterials", out _);
            if (overrideMaterials is not null && overrideMaterials.Value.Length > 0)
            {
                overrideMaterials.Value = [];
                applied = true;
            }

            return true;
        }

        var allowedProperties = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "DefaultAmmunitionItemClass",
            "MaxLoadedAmmo",
            "EventMaxAmmo",
            "DamagePerShot",
            "ROF",
            "ViewKickMultiplier",
            "MaxRecoilOffset",
            "RecoilRecoverySpeed"
        };
        if (!allowedProperties.Contains(propertyName))
        {
            warnings.Add($"UAsset edit skipped: неподдерживаемый параметр оружия {propertyName}");
            return true;
        }

        if (!TryFindWeaponOwnerExport(asset, out var export, out _))
        {
            warnings.Add($"UAsset edit skipped: экспорт для {propertyName} не найден.");
            return true;
        }

        if (propertyName.Equals("DefaultAmmunitionItemClass", StringComparison.OrdinalIgnoreCase))
        {
            if (!TryBuildObjectReferenceFromPicker(asset, edit.Value, out var objectReference, out var objectError))
            {
                warnings.Add($"UAsset edit skipped: {propertyName} ({objectError})");
                return true;
            }

            var conflictingObjectProperty = export.Data
                .OfType<PropertyData>()
                .FirstOrDefault(property =>
                    PropertyNamesMatch(property.Name?.ToString(), propertyName)
                    && property is not ObjectPropertyData);
            if (conflictingObjectProperty is not null)
            {
                warnings.Add($"UAsset edit skipped: {propertyName} уже существует, но хранится не как object-ссылка.");
                return true;
            }

            EnsureTopLevelObjectProperty(asset, export, propertyName).Value = objectReference;
            applied = true;
            return true;
        }

        if (propertyName.Equals("MaxLoadedAmmo", StringComparison.OrdinalIgnoreCase)
            || propertyName.Equals("EventMaxAmmo", StringComparison.OrdinalIgnoreCase))
        {
            if (!long.TryParse(edit.Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var intValue))
            {
                warnings.Add($"UAsset edit skipped: {propertyName} (ожидается целое число)");
                return true;
            }

            var existingIntegerProperty = FindTopLevelIntegerLikePropertyLoose(export, propertyName);
            if (existingIntegerProperty is not null)
            {
                if (!TrySetIntegerLikePropertyValue(existingIntegerProperty, intValue, out var setError))
                {
                    warnings.Add($"UAsset edit skipped: {propertyName} ({setError}).");
                    return true;
                }
            }
            else
            {
                if (intValue < int.MinValue || intValue > int.MaxValue)
                {
                    warnings.Add($"UAsset edit skipped: {propertyName} (значение выходит за диапазон int32).");
                    return true;
                }

                EnsureTopLevelIntProperty(asset, export, propertyName).Value = (int)intValue;
            }

            applied = true;
            return true;
        }

        if (!float.TryParse(edit.Value, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var value))
        {
            warnings.Add($"UAsset edit skipped: {propertyName} (ожидается float)");
            return true;
        }

        var existingNumericProperty = FindTopLevelNumericPropertyLoose(export, propertyName);
        if (existingNumericProperty is not null)
        {
            if (!TrySetNumericPropertyValue(existingNumericProperty, value, out var setError))
            {
                warnings.Add($"UAsset edit skipped: {propertyName} ({setError}).");
                return true;
            }
        }
        else
        {
            EnsureTopLevelFloatProperty(asset, export, propertyName).Value = (float)value;
        }

        applied = true;
        return true;
    }

